#!/usr/bin/env node
// Single source of truth for the ORRERY realism backlog.
// Emits  briefs/realism-backlog.md  and  site/realism.html.
//
//   node scripts/realism.mjs
//
// Two passes in one file: PASS1 is the pipeline (light, fields, materials, the map).
// PASS2 is the photograph — Earth itself, as a modern SimEarth.
//
// k:  EYE = what it looks like · SIM = the mechanism behind the look · PLAY = instrument, lever, legibility.
// e:  effort S/M/L.  i: impact 1..3.
// g:  capability token this item provides.  n: tokens it needs first.

import { writeFile, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

const CATS = [
  ['light', 'Light, exposure and the single tone curve',
    'The planet surface runs `tonemap(col * uExposure)` with an ACES curve. Until this pass the atmosphere shell did not: it computed an unbounded radiance, wrote `o = vec4(col, 1.0)`, and was additively blended over an image that had already been mapped — so the sunward limb clipped to flat white and painted a fat ring of blown sky several tenths of a radius wide. The moon was worse: it was drawn with `healthProg`, whose entire fragment shader is `o = vec4(uCol, 0.85)`, so the nearest object to the planet was an unlit beige circle. The shell and the moon now share `_exposure` with the surface. Everything else that draws over the planet — entities, meshes, streaks, rims, the interior stack — still does not, and every one of them is a place where two differently-scaled images meet.'],
  ['field', 'The field pipeline: precision, packing and what the GPU is given',
    'Two RGBA8 atlases, `6N x N`, carried eight scalars to the shader and one of the eight was wrong. `uField0.a` bit-packed sediment into the low nibble and cloud into the high nibble — in a texture sampled `LINEAR`. Hardware interpolation between two packed bytes runs across the nibble boundary, so `mod(packed, 16.0)` returned garbage wherever cloud cover crossed any of its sixteen steps, and the visible symptom was a tan sediment contour stair-stepping across four kilometres of open ocean. That is fixed here by splitting into a third atlas — cloud is 8-bit, sediment and intertidal have their own channels, and precipitation and river discharge reach the surface shader for the first time. What is left is the rest of the pipeline: every channel is still 8-bit, still uploaded by a full `NC` CPU loop every tick, and still nearest-in-face at the six cube seams.'],
  ['surface', 'The four missing decades between a cell and a footprint',
    'A cell is about 250 km across at N=64. The renderer draws it, the local map draws it, and between the two there is nothing: no material, no sub-cell variation, no reason for one square of savanna to look different from the next. This pass adds two octaves of object-space value noise, faded out by `fwidth(vObj)` before either period reaches the Nyquist limit, driving an albedo mottle and a sun-direction finite difference that lights slopes. That is the floor, not the ceiling. There is still no material model, no soil, no rock type on the surface, no scale-aware detail stack, and no triplanar anything.'],
  ['water', 'The sea as a surface rather than a tinted sphere',
    'The old specular was a Blinn-Phong lobe wide enough to survive a calm sea, which meant it blew out to a white blob at every sun angle; it is a GGX lobe now, with roughness driven by the wind field, plus a Fresnel sky term so grazing water brightens the way real water does. Underneath that the sea is still one colour per cell computed on the CPU in `refreshColours`, with no subsurface scattering, no depth-dependent extinction spectrum, no swell direction, no shoreline foam that knows where the shore is, and no wet sand.'],
  ['sky', 'Cloud, haze and weather you can see happening',
    'Cloud coverage was read with `dirToCell` — nearest neighbour — onto a shell of `6 x 17 x 17` vertices, a quarter of the grid resolution, and then displaced radially by coverage. Every band edge therefore became a hard terrace with a visible ledge on the limb. The shell now matches the grid and samples bilinearly, and the lift comes from convective type rather than raw coverage. Above that: cloud is still one scalar with no top height, no base, no phase, no anvil, no shadow cast into the world rather than multiplied into the albedo.'],
  ['relief', 'Shape: the mesh, the seams and the silhouette',
    '`rebuildGeometry` displaces a `6 x (N*subd+1)^2` lattice by `W.h`, clamps Earth relief to 0.028, blends 40% bilinear against 60% piecewise-constant neighbour mean, then recomputes vertex normals over the whole index buffer and welds the twelve cube edges. It runs on the main thread, in full, every time geometry is dirty. The result has no LOD, no tessellation near the camera, no silhouette detail, and the horizon of a planet you are supposed to be able to walk on is a polygon.'],
  ['ice', 'The cryosphere as a material, not a white paint',
    'Sea ice was a single `sin(dot(N.xy, ...))` hash — evaluated on the *world* normal, so the floe pattern swam across the ocean whenever the planet turned. It is object-space fBm now, with leads and pressure ridges. Everything else about ice is still one number: `W.ice[c]`. There is no thickness, no age, no firn, no blue ice, no crevasse field, no shelf front, no iceberg, and no melt pond.'],
  ['life', 'The biosphere as something you can see from orbit',
    '`lifeGreen` multiplies a biome colour by NPP and calls it phenology. The globe has no canopy structure, no leaf-area index, no snow-under-canopy, no burn scar, no seasonal deciduous colour, and no way to tell a rainforest from a plantation. The local map has fifteen biome stamp routines and no lighting model between them.'],
  ['pixel', 'The local map as a place, not a texture sample',
    'This is the half of the product with the most ground to make up. `drawLocalView` rebuilds the whole patch every frame and paints, per cell, in this order: a flat fill, a detail pass, a life stamp, buildings, then a full-patch grid, rivers, weather and plumes on top. Every layer draws at roughly the same alpha and the same density, so a savanna cell and a river and a herd of animals all read as the same amount of ink. There is no aerial perspective, no shadow direction shared with the globe, no horizon, and no sense that the patch is a piece of a sphere.'],
  ['motion', 'What moves, and at what rate',
    '`presentAdvance` gives the view a clock decoupled from the 10 kyr sim tick, and `stampPhase`, `windSway` and `entityGait` use it. The globe barely does: `uTime` reaches the shader for lightning and aurora and nothing else. Nothing on the planet drifts, sways, flows, breathes, grows or decays in a way the eye can track between two frames, which is why a paused ORRERY and a running one look almost identical from orbit.'],
  ['night', 'The dark half',
    'Night is `pow(1.0 - nl, 3.2)` times a few additive terms: bioluminescence keyed to life, city lights keyed to `vD.b`, lava keyed to `vD.a`, aurora on a tilted dipole, airglow on the limb. The moonlight term was added recently and is a flat wash. There is no light pollution geography, no skyglow dome, no earthshine on the moon derived from the actual albedo of the actual planet, and no reason for a city to be a different colour in one century than another.'],
  ['body', 'Every world that is not Earth',
    'The catalogue names 120 real bodies and the renderer has one planet shader with an `uEarth` switch. Ice shells get a three-layer stack, airless worlds get the same surface with the atmosphere turned down, and a gas giant is not representable at all. There are no rings, no limb-darkened stars as objects, no synchronous-rotation terminator, no tidally heated fracture pattern, and no reason Europa should look like Europa rather than like Earth with the sea frozen.'],
  ['instr', 'Reading the model off the picture',
    'Twenty-odd overlays map one scalar to one colour ramp. None of them has a legend with units, none can be compared to another, and the only thing on the globe that shows direction is the flow streak buffer — 1600 line segments, one frame long, no taper, no lifetime, drawn additively at a constant alpha. An overlay is how a teaching tool answers "why", and right now it answers "how much" and stops.'],
  ['perf', 'The budget, the tiers and the guard',
    'Everything in this document costs fill rate or CPU time on a device that might be a phone or a standalone headset. `refreshColours` is a 300-line per-cell loop over 24,576 cells; `uploadFieldTextures` is another; `rebuildGeometry` is a third plus a full normal rebuild. There is one quality control, `GLOBE_SUBD`, and one new one, `uGrain`. There is no frame budget, no tier detection, no measured cost per layer, and — most dangerous for a document like this — no rendered-reference test, so every item here can be silently reverted by one clever optimisation.'],
  ['marble', 'The Blue Marble: Earth as a photograph',
    'SimEarth painted biomes as a palette. The modern claim is that the globe in your hands is the same object DSCOVR photographs every two hours. `seedEarthBiosphere` paints life by latitude belt; `refreshColours` lerps two hand-picked ocean triples by `clamp((sea - h) * 1.9, 0, 1)`; `uEarth` turns the vegetation mix down so the result is quieter rather than truer. Nothing in the renderer has ever been compared to a photograph of the actual planet.'],
  ['limb', 'The thin blue line',
    'Every photograph of Earth from space is famous for the same millimetre of atmosphere. The shell is a `6 x (N+1)^2` lattice with an analytic Rayleigh rim, and `scatter.js` already builds a 32x32 transmittance LUT that the surface samples only for `muV`. The limb is still a glow painted on a sphere, not a volume with a scale height. On an Earth 12,742 km across the atmosphere is 100 km; at the current relief cap of 0.028 that air is thicker than the Himalaya.'],
  ['coast', 'Where land meets the sea',
    'The coastline is the most photographed edge on Earth and in this model it is a contour of `h` against `seaLevel`. `refineEarthHypsometry` runs two Laplacian passes to pull shelves toward the water, `coast.js` already knows intertidal fraction and harbour settlements, and the shader paints a symmetric ochre band with `smoothstep` on `heightF`. A real coast is fractal, asymmetric, and the reason a planet reads as a planet rather than a texture.'],
  ['season', 'The year as a picture',
    '`W.season` exists and drives insolation, the Keeling sawtooth and a green-wave comment. The shader multiplies vegetation by NPP and calls it phenology. Half the planet changing colour twice a year is the most watchable thing a temperate world does, and it is also how you tell, from orbit, that this is Earth and not a still. Snow line, sea ice, monsoon cloud and the ITCZ all have an annual motion and none of them currently travel.'],
  ['anthro', 'The human planet',
    '`W.build` is a scalar that lifts the mesh by 0.0035 on Earth and paints city lights from `vD.b`, the blue channel of the biome colour. `city.js` places named settlements; nothing connects them. From orbit the Anthropocene is the most geometric thing on the surface — lights, fields, roads, contrails, reservoirs — and it is the layer SimEarth called Civilization. A modern Earth without it is a Holocene diorama.'],
  ['ground', 'Standing on it',
    'The thesis is hold a planet, shrink, walk in. The local map is a top-down square of cells with `imageSmoothingEnabled` toggled per stamp. There is no ground-level camera, no sky that occupies half the frame, no sense of standing. SimEarth never let you walk; the modern extrapolation has to, or the second sentence of the pitch is a menu.'],
  ['hold', 'The planet in your hands',
    '`scaleXR` is a joystick axis clamped between 0.07 and 0.95. `orreryTable.js` can lay six shelf worlds on a disc and tints them from meanLife and meanTemp. The product is named for a table of worlds you hold, and the object in XR is still a rendering of a sphere at arm length with no weight, no limb you can occlude with a thumb, and no Earth that is Earth-sized next to a Mars that is Mars-sized.'],
  ['chroma', 'Colour that is Earth, not a palette',
    '`landTerra` and `ocean(d) => [10+42d, 48+72d, 96+100d]` are the whole of Earth colour. Real Earth albedo is dark: open ocean about 0.06, conifer canopy about 0.08, desert about 0.30, fresh snow about 0.85. The render is brighter and greener than the planet because every layer was tuned to read on a dim headset, and `uEarth` then desaturates the vegetation to compensate. The modern picture has to be dark, then exposed, the way a camera does it.'],
  ['gaia', 'The planet as a face: Gaia made visible',
    'SimEarth thesis was that the planet is a system that regulates. `gaia.js` tracks resilience, habitability, inhabitance and seven tipping elements — and `W._amoc` is written once as `?? 0.7`, `_monsoon` is a constant 0.5, and Daisyworld is `uDaisy` mixing toward luminance. The modern extrapolation is that you can see the metabolism: the carbon being breathed, the albedo being tuned, the daisy bands doing the work Watson and Lovelock said they would.'],
  ['photo', 'Matching the real photograph',
    '`calibrate.mjs` asserts meanTemp, landFrac, iceFrac, O2, CO2 and meanLife against wide numeric bands. It has never asserted a colour. A teaching tool that claims to be Earth needs a visual calibration target: NASA Blue Marble 2002, a DSCOVR EPIC frame, a VIIRS night composite, a MODIS chlorophyll map. Until the render can sit next to those and not look like a diagram, every other item in this document is decoration.'],
  ['zoom', 'From the table to a footprint',
    'N defaults to 64, about 157 km per cell; `N_LADDER` lists 96 as the shipped default and goes to 768. `LOCAL_RADII` is 3, 5, 8, 12, 18, 28. `scaleXR` jumps 0.07 to 0.95. None of these are one scale. The SimEarth planet was one zoom; the modern one promises a continuous descent, and the four decades between a cell and a shoe currently have two octaves of value noise and a square of stamps.'],
  ['record', 'The surface as a record of time',
    'Earth looks like Earth because it is old. Cratons, mobile belts, glacial scour, river terraces, farmed valleys, recovering burn scars — the picture is a palimpsest. Fields in this model are the present state. `chronicle.js` logs 4,000 events and `whatHappenedHere` finds them with index arithmetic. A planet that cannot show what happened to it will always read as generated rather than lived in, which is the opposite of Earth.'],
  ['toy', 'SimEarth DNA, modernised',
    'Wright planet was a toy: daisyworld, a time slider, biome paint, atmosphere gauges, a report card. ORRERY has all of those as code and almost none of them as picture. `uDaisy` is a mix factor; the ICS ribbon jumps epochs; `TIPPING` is seven thresholds on scalars nobody can see. The modern extrapolation keeps the toy — you still hold it, you still push sliders — and makes the toy the actual Earth, so every gesture has a photographic consequence.'],
  ['teach', 'An honest picture of a real planet',
    'Stated limits beat implied precision. The globe currently implies it is Earth: it is round, it is wet, it is green in bands. `param-coverage.json` records which catalogue numbers are measured; the renderer of the calibration planet itself has no such label. This category is the teaching contract for the one world everyone already knows, because that is the world against which every lie in the picture will be caught.'],
];

const PASS1 = [
/* --------------------------------------------------------------- light -- */
{c:'light',t:'One tone curve for every pass that draws over the planet',g:'tonecurve',d:'The surface, the atmosphere shell and the moon now share `_exposure` and the same ACES curve. Entities, low-poly meshes, flow streaks, the local rim, the interior stack and the solar shade disc still write raw sRGB-ish colours straight into the framebuffer. Route every draw through one `tonemap(col * uExposure)` and the compositing stops being a lottery.',k:'EYE',e:'M',i:3},
{c:'light',t:'Render to a linear HDR target and tonemap once',g:'hdrbuf',n:['tonecurve'],d:'Tonemapping per-pass is the wrong shape: bloom, exposure adaptation and any correct additive blending need the sum of radiances before the curve. One `RGBA16F` framebuffer, every pass writing linear, a single fullscreen resolve. WebGL2 with `EXT_color_buffer_float` — already probed for by `gpgpu/index.js` — has this.',k:'EYE',e:'L',i:3},
{c:'light',t:'Physical solar irradiance instead of a magic 1.0',n:['hdrbuf'],d:'`uSun` is a unit direction and the key light is `pow(nl, 1.15) * 1.05`. `W.solar` already carries insolation relative to Earth and only reaches exposure via `log2`. Make the light term proportional to actual irradiance and a planet at 0.3 AU is genuinely blinding rather than slightly brighter.',k:'SIM',e:'S',i:2},
{c:'light',t:'Star colour from effective temperature',n:['hdrbuf'],d:'`star.js` computes a spectral type and `worldRecord` carries `st_teff`, and the sun in the shader is white on every world. A Planckian locus lookup keyed to teff makes an M dwarf red, an F star blue-white, and the same landscape read completely differently under each — which is the whole point of a catalogue of real hosts.',k:'SIM',e:'S',i:3},
{c:'light',t:'Bloom that comes from the HDR buffer',n:['hdrbuf'],d:'The specular highlight on water, the sun glint, city lights, lava and lightning are all sub-pixel sources that should smear. Today they are clamped and lost. A two-pass Karis-average downsample and upsample chain on the float target costs about 1.5 ms at 1080p and does more for perceived realism than any other single item here.',k:'EYE',e:'M',i:3},
{c:'light',t:'Eye adaptation with a real time constant',n:['hdrbuf'],d:'`baseExpo` is a static function of `W.solar`, so flying from the night side to the day side has no adaptation at all. Measure average luminance from the smallest mip of the HDR buffer and drive exposure toward it with separate rise and fall constants — fast to dark, slow to light, as in a real eye.',k:'EYE',e:'M',i:2},
{c:'light',t:'A sun disc with the correct angular size',d:'There is no sun in the scene. Draw one as a billboard whose angular radius is derived from the host radius and the orbital distance in `worldRecord`, and a tidally locked world around a red dwarf gets a sun that fills a third of the sky — a fact about that world that no number in a panel will ever convey.',k:'EYE',e:'S',i:3},
{c:'light',t:'Limb darkening on that disc',n:['tonecurve'],d:'A star is not a flat disc: intensity falls toward the edge as roughly `1 - u(1 - mu)` with `u` about 0.6 in visible light and strongly temperature dependent. One line in the sun billboard shader, and the object stops looking like a sticker.',k:'EYE',e:'S',i:1},
{c:'light',t:'Shadows cast by terrain along the sun direction',g:'terrshadow',d:'At low sun a mountain range should lay a shadow across the plain behind it. There is no shadow of any kind on the globe — only `pow(1 - heightF, 1.4)` valley darkening, which is an occlusion guess with no direction in it. A cheap horizon-map raymarch along the sun-tangential direction in the height texture gets most of the way.',k:'EYE',e:'M',i:3},
{c:'light',t:'Cloud shadows cast onto the surface, not multiplied into it',n:['terrshadow'],d:'`col *= 1.0 - cloudF * landMask * 0.38` darkens the cell that is under the cloud. A real cloud shadow lands where the sun projects it, which at 60 degrees of solar zenith is several cells away and moves as the cloud advects. Same raymarch as terrain shadow, offset into the cloud shell.',k:'EYE',e:'M',i:2},
{c:'light',t:'Ambient occlusion baked per cell',d:'`AREA`, `NBR` and `W.h` are all resident and the sky-visibility of a cell is a fifteen-line loop over its neighbourhood. Bake it once per geometry rebuild into a spare field channel and every valley, crater and rift gets contact darkening for free at zero per-frame cost.',k:'EYE',e:'M',i:2},
{c:'light',t:'Sky light that carries the sky colour',d:'The ambient term is `0.14 + 0.10 * wrap * wrap` — grey. Real ambient on a clear day is the sky, so it is blue from above and bounced ground colour from below. Split ambient into a hemispheric pair driven by `uAtmo` and the bounce colour of the local albedo.',k:'EYE',e:'S',i:2},
{c:'light',t:'Bounce light from bright ground onto what stands on it',n:['tonecurve'],d:'Entities, buildings and meshes are lit by the sun and an ambient constant. Over a salt flat or an ice sheet the dominant light is from below. One extra term using the cell albedo already in `vD`.',k:'EYE',e:'S',i:1},
{c:'light',t:'Aerial perspective between the camera and the surface',n:['hdrbuf'],d:'The transmittance LUT is sampled for the surface and for the limb but nothing attenuates the surface by the air *in front of* it. At close range the far side of a basin should be hazier than the near side. Sample `uScatter` with the view path length rather than only with `muV`.',k:'EYE',e:'M',i:2},
{c:'light',t:'Specular anti-aliasing on the water lobe',d:'A GGX lobe at roughness 0.035 on a sphere is a sub-pixel highlight at orbital distance and will crawl and sparkle as the camera moves. Clamp roughness from the screen-space derivative of the normal — the standard Kaplanyan filter — so the lobe widens exactly as fast as it needs to stay stable.',k:'EYE',e:'S',i:2},
{c:'light',t:'Dither the framebuffer before the 8-bit write',d:'A smooth atmospheric gradient across a dark limb is the classic banding case and the output is `RGBA8`. A triangular-PDF noise of one LSB added before the write removes it entirely and costs two instructions.',k:'EYE',e:'S',i:2},
{c:'light',t:'A colour grade that belongs to the world, not to the app',d:'Every ruleset gets the same neutral image. A per-ruleset lift/gamma/gain — dusty warm for Ares, blue-green cold for Europa, high-contrast airless for Selene — is three uniforms and turns the world picker into something you can feel the difference of.',k:'EYE',e:'S',i:2},
{c:'light',t:'Correct the terminator softness for the actual atmosphere',d:'`term = smoothstep(-0.18 - uAerosol * 0.25, 0.22 + uAtmoK * 0.12, nl)` is a hand-tuned pair of constants. The width of a real terminator is set by scale height over radius, both of which `worldRecord` knows. On an airless body it should be a knife edge and on Venus it should be tens of degrees wide.',k:'SIM',e:'S',i:2},
{c:'light',t:'Twilight colour from the ozone Chappuis band',d:'The `ray` term already mixes toward `vec3(0.05, 0.12, 0.55)` under `uOzone`. Drive the mix from the actual slant optical depth through the ozone layer rather than from `1 - muS`, and the deep blue appears where it physically does — a narrow ring just past the terminator, not across the whole night limb.',k:'SIM',e:'M',i:1},
{c:'light',t:'Earthshine on the moon from the planet it orbits',d:'The moon shader has a constant `0.055` earthshine floor. The planet renderer knows its own mean albedo, its phase as seen from the moon, and their separation. Compute it, and a crescent moon over a snowball Earth is visibly brighter on its dark limb than the same crescent over an ocean world.',k:'SIM',e:'S',i:2},
{c:'light',t:'Eclipses, both ways',d:'`W.moon` has a position and the sun has a direction, so the geometry for both a solar eclipse shadow track on the surface and a lunar eclipse coppering of the moon is already present. Nothing computes either. This is the single most memorable thing a planet with a moon can do.',k:'SIM',e:'M',i:3},
{c:'light',t:'The solar shade disc should occlude, not tint',d:'`W.solarShade` draws a flat dark circle at 1.85 radii toward the sun and separately scales insolation. Give it a real penumbra on the surface using the same shadow path as terrain and the geoengineering lever becomes a thing you watch rather than a number you read.',k:'EYE',e:'M',i:2},
{c:'light',t:'Volumetric god rays through cloud gaps',n:['hdrbuf'],d:'`crep` is `vec3(1.0, 0.55, 0.25) * termBand * rim2` — a crepuscular colour with no rays in it. A radial blur of the bright pixels away from the sun position in screen space is the cheap version and it is convincing at the terminator, where the cloud shell is edge-on.',k:'EYE',e:'M',i:2},
{c:'light',t:'Separate the night-side additive terms from exposure',d:'City lights, bioluminescence, lava and aurora are all added *before* `tonemap(col * uExposure)`. When exposure rises for a bright star the night side gets brighter too, which is backwards — emissive sources do not scale with insolation. Add them after the curve, or carry them in a separate emissive channel.',k:'EYE',e:'S',i:2},
{c:'light',t:'A light probe for entities standing on the surface',d:'`drawEntityMeshes` lights with `uSun` and a constant. Sample the cell colour, the sky colour and the sun at the entity position and a creature on a beach at sunset is lit by a beach at sunset.',k:'EYE',e:'M',i:1},
{c:'light',t:'Shadow the entities onto the ground they stand on',d:'`castShadow` exists in the local map and there is nothing equivalent on the globe. At the zoom where entity meshes appear, a contact shadow is the only thing that puts them on the surface rather than above it.',k:'EYE',e:'M',i:2},
{c:'light',t:'Expose the exposure',d:'`S.exposure` is settable and unexposed. A single slider in View, with the automatic value as its default and a reset, is a two-line UI change that lets someone photograph the planet the way they want to.',k:'PLAY',e:'S',i:1},
{c:'light',t:'A rendered-reference test for the tone curve',g:'imgtest',d:'Six fixed camera/sun/world combinations, rendered headless through a software path or a stored framebuffer hash, diffed against committed PNGs with a perceptual tolerance. Without it every item in this category is one merge away from being undone by accident.',k:'PLAY',e:'L',i:3},
/* --------------------------------------------------------------- field -- */
{c:'field',t:'Never bit-pack into a linearly filtered texture again',g:'nopack',d:'`uField0.a` carried `sedQ + cldQ * 16` and was sampled `LINEAR`. Interpolating between two packed bytes runs the blend straight across the nibble boundary, so the low field returned nonsense wherever the high field stepped — visible as a tan sediment contour stair-stepping across the abyssal plain at every 1/16 of cloud cover. Split into a third atlas, done in this pass. The rule generalises: if a channel is filtered, it holds exactly one quantity.',k:'SIM',e:'S',i:3},
{c:'field',t:'Move the field atlases to float textures',g:'floatfield',d:'Every channel is `UNSIGNED_BYTE`. Cloud now has 256 levels instead of 16, which is enough; height, temperature and NPP are not — `heightF = clamp(0.5 + (h - sea) * 2.2, 0, 1)` throws away everything below 4 km and above 4 km of elevation and quantises the rest to 1/255. `EXT_color_buffer_float` is already probed by the GPGPU path; use `RGBA16F` where it exists and keep the byte path as the fallback.',k:'SIM',e:'M',i:3},
{c:'field',t:'Fix the six seams in the field atlas',g:'seamfix',d:'`vFieldUV` maps cell `(f, i, j)` to `(f * N + i + 0.5) / (6N)`, and the atlas is `CLAMP_TO_EDGE`. A fragment near the edge of face 0 therefore blends with the edge of face 1, which is a completely different part of the planet. Every field the shader reads is wrong in a one-cell band around all twelve cube edges. A one-texel gutter per face, filled with the correct neighbour from `NBR`, fixes all of them at once.',k:'SIM',e:'M',i:3},
{c:'field',t:'Write the fields on the GPU, not in a CPU loop',g:'gpufield',n:['floatfield'],d:'`uploadFieldTextures` walks all 24,576 cells in JavaScript every tick, does eight `clamp`s and a `dominantGuildAt` call per cell, and uploads two full `texSubImage2D`s. The GPGPU climate path already keeps temperature, moisture, ice and cloud resident on the GPU; the atlas should be produced there and never round-trip.',k:'SIM',e:'L',i:2},
{c:'field',t:'Stop recomputing colour on the CPU for every cell every tick',g:'gpucolour',n:['floatfield'],d:'`refreshColours` is 320 lines of per-cell branching — ocean depth ramp, sea ice leads, whitecaps, SST warm shift, rain darkening, NPP bloom, sediment, reef, river plume, storm trail, land biome, ice, ash, build, guild tint — run over `NC` and then bilinearly spread to `GNV` vertices. All of it is a function of fields the shader can already read. Moving it into the fragment shader deletes the largest CPU cost in the renderer and makes every one of those effects sub-cell rather than per-cell.',k:'SIM',e:'L',i:3},
{c:'field',t:'A published channel map',d:'Eight channels across two atlases, plus four more added here, with their meanings in comments in three files. One exported `FIELD_CHANNELS` table naming each slot, its source field, its range and its consumer, checked by a test that the shader declares the same names.',k:'PLAY',e:'S',i:2},
{c:'field',t:'Upload only the tiles that changed',n:['gpufield'],d:'`texSubImage2D` uploads the whole `6N x N` atlas every tick. Most ticks change a small fraction of it. Track a per-face dirty rect from the sim and upload sub-rectangles.',k:'SIM',e:'M',i:1},
{c:'field',t:'Interpolate fields in time, not just life and ice',d:'`uploadFieldTextures` lerps `life` and `ice` between `prev` and current using `alpha`; moisture, cloud, NPP, wind, sediment and everything else snap. At 10 kyr per tick and a 60 Hz view the snap is the dominant motion artefact on the globe.',k:'EYE',e:'S',i:3},
{c:'field',t:'Keep two frames of every field the renderer reads',n:['gpufield'],d:'The `prev` arrays exist only for `life`, `temp` and `ice`. Generalising to a ring of two atlases makes the previous item free and unlocks motion vectors for temporal reprojection.',k:'SIM',e:'M',i:2},
{c:'field',t:'Mipmap the field atlas with seam-correct downsampling',n:['seamfix'],d:'`LINEAR` with no mips means the atlas aliases badly when the planet is small on screen — which is exactly the orrery-table view. Generate mips per face, never across faces.',k:'EYE',e:'M',i:2},
{c:'field',t:'Anisotropic filtering at grazing angles',n:['seamfix'],d:'Near the limb a screen pixel covers a long thin footprint on the surface and isotropic filtering blurs it in both directions. `EXT_texture_filter_anisotropic` is near-universal and costs one `texParameterf`.',k:'EYE',e:'S',i:1},
{c:'field',t:'Publish the tangent frame to the GPU',g:'gpubasis',d:'`EAST` and `NORTH` exist per cell on the CPU and drive `flowviz`. The shader has no way to express a direction, so no vector field can be drawn, no anisotropic material can be oriented, and wave direction cannot exist. Two more channels, written once per resolution change.',k:'SIM',e:'S',i:3},
{c:'field',t:'A vector atlas for wind and current',n:['gpubasis','floatfield'],d:'`windU/windV` reach the shader as a single magnitude in `F1.a`. With the basis on the GPU, carry the pair and every direction-aware effect below this line becomes possible in one texture fetch.',k:'SIM',e:'S',i:3},
{c:'field',t:'Carry sea surface temperature as its own channel',n:['floatfield'],d:'`refreshColours` reads `W.oceanSurf` and bakes a warm shift into the vertex colour. As a channel it can drive the ocean colour continuously, the fog over cold water, the sea ice edge and the instrument overlay from one source.',k:'SIM',e:'S',i:2},
{c:'field',t:'Carry salinity',n:['floatfield'],d:'A grep for `salinity` across `vr/` returns nothing outside `ocean.js` internals. Salinity is what makes a river plume visible from orbit, what sets where sea ice forms, and what a colour ramp of the North Atlantic actually shows.',k:'SIM',e:'M',i:2},
{c:'field',t:'Carry crust age and thickness',d:'`platesPanel` reads both and the globe cannot show either. Ocean floor age is the single most explanatory field in plate tectonics — the stripes either side of a ridge are the evidence — and it exists in memory already.',k:'SIM',e:'S',i:2},
{c:'field',t:'Carry rock type, not one overwritten byte',d:'`rock` is a single byte per cell that gets overwritten by whatever happened last. A four-channel fraction — igneous, sedimentary, metamorphic, evaporite — lets the surface shader pick a material instead of a colour.',k:'SIM',e:'M',i:3},
{c:'field',t:'Carry soil depth and moisture separately from atmospheric moisture',d:'`W.moist` is used for both the air and the ground; the shader reads it as `moistF` and darkens soil with it. They have completely different time constants and the confusion is why the ground never looks like it dried out after rain.',k:'SIM',e:'M',i:2},
{c:'field',t:'Carry snow separately from ice',d:'`W.ice` is sea ice, land ice and snow cover at once. Snow melts in a season and an ice sheet does not; painting them the same white is why the seasonal cycle is invisible from orbit.',k:'SIM',e:'M',i:3},
{c:'field',t:'Carry burned fraction',d:'`extinction.js` and the disaster layer both know about fire and nothing on the surface records it. A burn scar that fades over decades is one of the most legible marks a biosphere leaves.',k:'SIM',e:'M',i:2},
{c:'field',t:'Carry a per-cell random seed channel',d:'Every noise-driven effect in the shader currently derives its variation from `vObj`, which is smooth and continuous. A stable per-cell hash lets a cell have a persistent identity — this valley is always sandier than that one — without the CPU writing a colour.',k:'SIM',e:'S',i:2},
{c:'field',t:'Validate every channel range in a test',n:['imgtest'],d:'A field that silently saturates is invisible until someone screenshots it. The headless probe already computes area-weighted means; add min/max/saturated-fraction assertions for every channel with a stated expected range, and cloud pinning at 1.0 stops being something you find by rendering the alpha channel to the screen.',k:'PLAY',e:'S',i:3},
{c:'field',t:'A field inspector in the Lab tab',d:'Pick a channel, see it as a raw greyscale on the globe with the actual byte value under the cursor. Every artefact chased in this pass would have taken minutes instead of hours with this tool.',k:'PLAY',e:'M',i:3},
{c:'field',t:'Bilinear cell sampling helper shared by both views',d:'`sampleFaceField` exists in `sphere.js` and is used by `rebuildGeometry` and now by the cloud mesh. `localview.js` reads `W.x[c]` directly everywhere, which is why the pixel map is blocky at cell edges while the globe is smooth. One shared sampler, both consumers.',k:'SIM',e:'M',i:3},
{c:'field',t:'Retire the vertex colour attribute',n:['gpucolour'],d:'`vDat` is `GNV * 4` bytes re-uploaded on every colour refresh — at N=64, subd 2, that is 786,432 vertices and 3 MB a tick. Once colour is computed in the fragment shader from the atlas, the attribute and the entire `spreadVertexDat` bilinear spread go away.',k:'SIM',e:'M',i:2},
{c:'field',t:'Deterministic field hashes in the golden run',d:'`headless.mjs --golden` hashes `h`, `temp`, `life`, `ice` and `moist`. Add every channel the renderer reads, so a change that alters the picture cannot pass the reproducibility gate silently.',k:'PLAY',e:'S',i:2},
{c:'field',t:'A budget for the atlas',d:'Three RGBA8 atlases at N=64 is 295 KB and nobody is counting. Write the number into the debug overlay alongside the vertex count and the draw call count, so adding a channel is a visible decision.',k:'PLAY',e:'S',i:1},
{c:'field',t:'Make N a first-class visual quality control',d:'`setResolution` exists and `remeshPlanet` handles it. Nothing in the UI says that N=96 makes coastlines twice as fine, or what it costs. This is the highest-leverage quality lever in the whole renderer and it is hidden.',k:'PLAY',e:'S',i:2},
/* ------------------------------------------------------------- surface -- */
{c:'surface',t:'A material identity per cell, not a colour',g:'material',n:['nopack'],d:'The surface picks an RGB and applies one roughness heuristic: `mix(0.85, 0.08, waterMask)` then two corrections. Replace it with a small material table — basalt, granite, sand, loam, laterite, limestone, salt, ice, snow, canopy, water — each carrying albedo, roughness, a specular level and a noise character, selected per cell from rock type, soil and life.',k:'EYE',e:'L',i:3},
{c:'surface',t:'Detail noise that fades before it aliases',d:'Landed in this pass: two octaves of object-space value noise, faded by `smoothstep(0.06, 0.20, px * freq)` where `px = length(fwidth(vObj))`. The first attempt faded on absolute pixel size and produced per-pixel speckle at close range; the criterion has to be periods-per-pixel, not pixels.',k:'EYE',e:'M',i:3},
{c:'surface',t:'Sun-direction relief instead of a screen-space bump',d:'Also landed here. The obvious approach — Mikkelsen surface-gradient bump from `dFdx`/`dFdy` of the noise — scales with zoom because the derivative step is a pixel and the height is unitless, so the perturbation amplitude changes with distance and turns into speckle. One extra fbm sample a half-period along the sun-tangential direction gives a finite-difference slope that is stable at every distance and swings correctly as the terminator moves.',k:'EYE',e:'M',i:3},
{c:'surface',t:'A third and fourth detail octave for the standing-on-it range',n:['material'],d:'Two octaves cover roughly 250 km down to 5 km. The local map claims about 25 km per side. The gap between the finest globe octave and the coarsest thing the eye can resolve when you zoom all the way in is still two decades wide.',k:'EYE',e:'M',i:2},
{c:'surface',t:'Replace value noise with gradient noise',d:'`vnoise` is trilinear-interpolated hash on a lattice, which has visible axis alignment — the blocky character in the first attempt at grain was partly this. Simplex or gradient noise costs slightly more and has no preferred direction.',k:'EYE',e:'S',i:2},
{c:'surface',t:'Domain-warp the detail the way the terrain generator already does',d:'`naturalizeHypsometry` uses domain-warped fBm and it works. The surface shader uses plain fBm. Warping the detail lookup by a low-frequency vector field is two extra noise calls and turns uniform mottling into something with grain and lineation.',k:'EYE',e:'M',i:2},
{c:'surface',t:'Slope-aware materials',n:['material'],d:'The gradient of `heightF` is one texture-fetch pair away and nothing uses it. Steep cells are bare rock, gentle cells hold soil, and the transition is where scree and talus live. This is the single most recognisable land pattern there is.',k:'EYE',e:'M',i:3},
{c:'surface',t:'Aspect-aware materials',n:['material','gpubasis'],d:'With the tangent frame on the GPU, the compass direction a slope faces becomes available. North-facing slopes in the northern hemisphere hold snow and moss; south-facing ones are dry. Every mountain photograph shows this and no rendering of this planet can.',k:'EYE',e:'M',i:2},
{c:'surface',t:'Altitude bands: tree line, snow line, bare rock',n:['material'],d:'`heightF` and `temp` together give a lapse-rate elevation for both lines and neither is drawn. A mountain whose flanks change three times between the valley and the summit reads as tall; a uniformly green cone does not.',k:'EYE',e:'M',i:3},
{c:'surface',t:'Latitude-consistent lapse rate rather than a fixed one',n:['material'],d:'If the tree line and snow line are drawn from `temp - lapse * elevation`, the lapse rate has to be moist-adiabatic where the air is wet and dry-adiabatic where it is not. `W.moist` is there.',k:'SIM',e:'S',i:1},
{c:'surface',t:'Dunes with a wind direction',n:['gpubasis'],d:'The desert biome in the local map draws four wavy horizontal lines. On the globe there is nothing. Transverse dune fields are anisotropic noise oriented perpendicular to the prevailing wind, which the vector atlas will carry — one of the cheapest recognisable landforms.',k:'EYE',e:'M',i:2},
{c:'surface',t:'Alluvial fans where rivers leave mountains',n:['material'],d:'`erosionTick` deposits into one downhill cell and saturates sediment at 1. The place where a steep reach meets a flat one is where a fan builds, and it is a bright lobe visible from orbit.',k:'SIM',e:'M',i:2},
{c:'surface',t:'Salt pans in closed basins',n:['material'],d:'`computeRivers` marks local minima as `lake[c] = 1`. A closed basin in a dry climate is not a lake, it is an evaporite flat — the brightest natural surface on a planet and a strong contrast anchor.',k:'SIM',e:'M',i:2},
{c:'surface',t:'Loess and dust mantling downwind of deserts',n:['gpubasis'],d:'`W.ash` advects and dust lofts on Ares. On Earth the same transport builds pale wind-blown soil hundreds of kilometres downwind of every arid basin, and it changes the colour of whole regions.',k:'SIM',e:'M',i:1},
{c:'surface',t:'Permafrost and patterned ground',n:['material'],d:'Between the tundra biome and the ice sheet there is a band where the ground itself is a texture — polygons, pingos, thermokarst. It is a distinctive look and it is a direct read of a temperature threshold the model already has.',k:'EYE',e:'M',i:1},
{c:'surface',t:'Volcanic terrain that looks volcanic',n:['material'],d:'An eruption raises `h` and dumps ash. A shield volcano has radial lava channels, a stratovolcano has gullied flanks, a caldera has a floor at a different level than its rim. None of that is shape the current model can express, and all of it is recognisable at a glance.',k:'SIM',e:'L',i:2},
{c:'surface',t:'Impact craters as terrain, not a marker',d:'`selene` is a ruleset about impact history. A crater has a rim, a bowl, a central peak above a size threshold, an ejecta blanket and a ray system, and the ray system is what makes a moon look like a moon. The small-body shader added here fakes it with noise; the terrain should carry it.',k:'SIM',e:'M',i:3},
{c:'surface',t:'Glacial landforms after an ice sheet retreats',d:'Ice comes and goes in deep time and the ground it leaves is unmistakable: U-valleys, fjords, moraine arcs, drumlin fields, thousands of lakes. Recording maximum ice extent per cell would let the surface remember an ice age after it ends.',k:'SIM',e:'L',i:2},
{c:'surface',t:'Karst where limestone meets rain',n:['material'],d:'A rock-type field plus a precipitation field gives dissolution terrain for free — sinkholes, towers, dry valleys. It is the clearest case in the document of a landform that falls out of two existing numbers.',k:'SIM',e:'M',i:1},
{c:'surface',t:'Wet ground that dries',d:'Rain now darkens and desaturates the surface through the new `precipF` channel. It has no memory: the moment precipitation stops, the ground is dry. A soil-moisture channel with a multi-day time constant is the whole fix.',k:'SIM',e:'S',i:2},
{c:'surface',t:'Vegetation that shades its own soil',n:['material'],d:'`lifeGreen` tints the cell green. Real canopy occludes the ground beneath it, so the albedo of a forested cell is dominated by leaves and its roughness by the canopy, not by an average. Model the cell as a fractional cover mix and the colour stops being a lerp.',k:'SIM',e:'M',i:2},
{c:'surface',t:'Snow under canopy',n:['material'],d:'A snow-covered forest is much darker than a snow-covered field, because the trees stick out. Painting `iceF` white over `lifeGreen` gets this exactly backwards and it is one of the largest albedo errors in the picture.',k:'SIM',e:'S',i:3},
{c:'surface',t:'Shoreline that knows which side is land',n:['gpubasis'],d:'The intertidal band is `smoothstep` on `heightF`, so it paints symmetrically either side of sea level. A real strandline is asymmetric — wet sand and wrack on the land side, surf on the water side — and needs the gradient direction the basis will provide.',k:'EYE',e:'M',i:2},
{c:'surface',t:'Beaches only where there is sediment and wave energy',d:'The ochre intertidal band is painted wherever elevation is near sea level. A cliffed coast has no beach at all. `W.sediment` and the wave field decide, and both exist.',k:'SIM',e:'M',i:2},
{c:'surface',t:'Cliffs on the silhouette',n:['lodmesh'],d:'The Earth relief cap is 0.028 and cell-to-cell height is smoothed 60% toward the neighbour mean, so no coast is ever steep. At the zoom where you can see a coastline, a vertical face is what tells you the scale of what you are looking at.',k:'EYE',e:'L',i:2},
{c:'surface',t:'A settlement that reads as a settlement',d:'`stampBuildings` in the local map draws boxes and `buildAmp` lifts the globe by 0.0035. From orbit a city is a grey-brown patch with a road network radiating from it and cropland around it, all of which are patterns rather than heights.',k:'EYE',e:'M',i:2},
{c:'surface',t:'Field patterns around settlements',d:'Agriculture is the most geometric thing on the surface of the Earth and the most obvious sign from orbit that something is farming. Straight edges at a scale nothing natural produces.',k:'EYE',e:'M',i:2},
{c:'surface',t:'Roads and rail between settlements',d:'`city.js` places settlements and nothing connects them. A least-cost path over the height field, drawn as a thin line, is the cheapest possible way to make a civilisation look like a network rather than a scatter.',k:'SIM',e:'M',i:1},
{c:'surface',t:'A material debug view',n:['material'],d:'Flat-shade the surface by material index with a legend. Every item in this category is unverifiable without it.',k:'PLAY',e:'S',i:2},
{c:'surface',t:'Reference photographs beside the render',d:'The document that says what good looks like. Six paired images — a delta, a dune sea, a boreal forest in autumn, a calving front, a caldera, a night city — with the render beside each, kept in `briefs/` and updated when the renderer changes.',k:'PLAY',e:'S',i:2},
/* --------------------------------------------------------------- water -- */
{c:'water',t:'A GGX sun glint with wave-slope roughness',d:'Landed here. The old lobe was `pow(dot(N,H), gloss)` with `gloss` capped at 96 and a second wide lobe added on top, which blew out to a white disc at every sun angle. It is now a microfacet lobe whose roughness is `0.055 + windF * 0.34`, energy-clamped, so calm water gives a tight glitter point and a gale gives a broad glitter path.',k:'EYE',e:'M',i:3},
{c:'water',t:'Fresnel sky reflection at grazing angles',d:'Also landed. `0.02 + 0.98 * pow(1 - ndv, 5)` mixed toward the atmosphere colour. It is the single reason a real ocean is not a flat tinted disc, and it was entirely absent.',k:'EYE',e:'S',i:3},
{c:'water',t:'Depth-dependent extinction with a real spectrum',g:'watercol',d:'`refreshColours` lerps two hand-picked RGB triples by `clamp((sea - h) * 1.9, 0, 1)`. Water absorbs red at about 0.4 per metre and blue at about 0.002, so the colour of shallow water over sand and the colour of deep water are the *same* pigment at two path lengths. Three per-channel extinction coefficients replace the entire ramp and get the turquoise-to-indigo transition right for free.',k:'SIM',e:'M',i:3},
{c:'water',t:'Subsurface scattering in the shallows',n:['watercol'],d:'Above a bright sand bottom, light goes down, scatters and comes back up. That is why a lagoon glows. A single-scatter approximation using bottom albedo and depth is four lines and it is the most beautiful thing water does.',k:'EYE',e:'M',i:2},
{c:'water',t:'Chlorophyll and CDOM in the water colour',n:['watercol'],d:'`oceanLifeRGB` already picks a guild-tinted bloom colour and it is lerped in at up to 55%. Doing it as an absorption modification instead of a colour blend means a productive ocean gets *greener and darker* the way it does, rather than getting a green wash painted over it.',k:'SIM',e:'M',i:2},
{c:'water',t:'A wave normal map oriented by wind',n:['gpubasis'],d:'The specular lobe is the only thing that knows the sea is rough, and it knows it as a scalar. Two octaves of anisotropic noise aligned to the wind direction, animated, give per-pixel wave normals — and everything downstream, from the glint shape to the foam, becomes correct rather than approximated.',k:'EYE',e:'M',i:3},
{c:'water',t:'Swell that travels away from where it was made',g:'swell',n:['gpubasis'],d:'Wind waves are local; swell is the long-period remnant that crosses an ocean basin and arrives days later on a coast where the wind is calm. It is a separate field with its own direction and it is what makes a shoreline feel connected to a storm you can see somewhere else.',k:'SIM',e:'L',i:2},
{c:'water',t:'Refraction of swell around headlands',n:['swell'],d:'Waves bend toward shallow water, which is why they arrive parallel to almost every beach regardless of where they came from. It is the visible signature of bathymetry.',k:'SIM',e:'M',i:1},
{c:'water',t:'Surf where swell meets the shelf',n:['swell'],d:'A white line along every coast, brighter where the shelf is steep, absent in a sheltered bay. The most reliable visual cue that a shoreline is a real boundary rather than a colour change.',k:'EYE',e:'M',i:3},
{c:'water',t:'Whitecaps from wave steepness rather than wind speed',d:'`col = mix(col, white, waterish * pow(windF, 3.0) * 0.45)` is a cube of the wind field. Whitecap fraction is a known function of wind speed *and* the difference between air and water temperature — cold air over warm water breaks far more.',k:'EYE',e:'S',i:2},
{c:'water',t:'Foam that persists and drifts',d:'Foam appears and vanishes with the instantaneous wind. Real foam has a lifetime of minutes and is carried by the current, which is why it forms streaks and windrows rather than a uniform sprinkle.',k:'SIM',e:'M',i:2},
{c:'water',t:'A visible current boundary',n:['gpubasis'],d:'`W.oceanU`/`oceanV` exist and reach the picture only as 1600 one-frame line segments. The edge of a western boundary current is a sharp colour and temperature front hundreds of kilometres long — the most striking thing in a satellite SST image and completely invisible here.',k:'EYE',e:'M',i:3},
{c:'water',t:'Eddies shed from that boundary',n:['gpubasis'],d:'Rings peeling off a boundary current and drifting away are the ocean equivalent of weather. With a velocity field and a vorticity diagnostic they are extractable as objects with positions and lifetimes.',k:'SIM',e:'M',i:2},
{c:'water',t:'Sediment plumes that follow the flow',d:'This pass gated the sediment tint to shallow water, which stopped it painting contours across the abyss. What it still does not do is advect: a river plume should be a comma-shaped feature bending downstream in the coastal current, not a symmetric blob at the river mouth.',k:'SIM',e:'M',i:2},
{c:'water',t:'River plumes with a salinity front',n:['gpubasis'],d:'Fresh water floats on salt. The edge of a plume is a visible line with a different colour, different roughness and often a foam line along it.',k:'SIM',e:'M',i:1},
{c:'water',t:'Sea state that reads at every zoom',d:'From orbit sea state is texture and glint; from the local map it should be individual waves. Right now the transition between the two is a hard cut between a shader and a canvas stamp routine with nothing shared between them.',k:'EYE',e:'M',i:2},
{c:'water',t:'Tidal flats that flood and drain',d:'`W.intertidal` and `W.tideWet` are computed every tick by `updateShoreCell` and neither drives anything in the picture beyond a static ochre band. A flat that is water at one phase and mud at another, twice a day, is the clearest demonstration of a tide there is.',k:'SIM',e:'M',i:3},
{c:'water',t:'A tide that visibly moves the shoreline',d:'`basinRange` amplifies range to 2.4x in a funnel. Nothing redraws the coast. Moving `localSeaLevel` by the tide height and letting the shoreline follow is the payoff for the entire tidal subsystem.',k:'SIM',e:'M',i:3},
{c:'water',t:'Tidal bores and races in the narrows',d:'`W.tideU`/`tideV` are computed as proxies and read by nothing. A strait between two basins at different tidal phase runs like a river and reverses.',k:'SIM',e:'M',i:1},
{c:'water',t:'Lakes with a level',d:'`lake[c] = 1` is a flag on a local minimum. A lake with a volume fills, spills, carves an outlet and drains — and a lake that has drained leaves a shoreline terrace that is visible for millennia.',k:'SIM',e:'L',i:3},
{c:'water',t:'Rivers as lines on the globe',d:'Landed partly: discharge now reaches the surface shader as a log-compressed channel and the largest trunks are drawn as darker threads with a specular. What is missing is the geometry — a river should be a polyline with a width, not a threshold on a per-cell field, or it will always be a cell wide.',k:'EYE',e:'M',i:3},
{c:'water',t:'Deltas with lobes',d:'One downhill neighbour per cell means a river cannot split. A delta is defined by splitting.',k:'SIM',e:'L',i:2},
{c:'water',t:'Meanders and oxbows',d:'Steepest-descent routing produces straight channels. Real lowland rivers wander, cut off, and leave crescent lakes — a pattern so distinctive it is how you recognise a floodplain from the air.',k:'SIM',e:'L',i:2},
{c:'water',t:'Waterfalls at knickpoints',d:'A large discharge crossing a large elevation step in one cell is a waterfall, and it is audible before it is visible. `audio.js` already has a river term.',k:'SIM',e:'S',i:1},
{c:'water',t:'Ice-free polynyas that are not a hash threshold',d:'The sea-ice lead pattern is now object-space fBm rather than a world-normal hash, which stops it swimming. A real polynya is opened by wind or by upwelling warm water and stays in the same geographic place all winter.',k:'SIM',e:'M',i:2},
{c:'water',t:'Sea fog over cold water',d:'The single most atmospheric thing a coast does and there is no fog anywhere in the model. It forms where warm moist air crosses cold water, which is two existing fields and a threshold.',k:'SIM',e:'M',i:2},
{c:'water',t:'Bioluminescence that is a bloom, not a wash',d:'`col += vec3(0.05, 0.65, 0.42) * uNight * night * max(lifeGreen, lifeF * waterMask)` paints the whole productive ocean. Real bioluminescent blooms are patchy, seasonal, and follow the current — a milky sea is an event, not a background.',k:'EYE',e:'S',i:2},
{c:'water',t:'Underwater terrain visible through clear shallow water',n:['watercol'],d:'With a real extinction model the bottom shows through where it is shallow, which means bathymetry becomes visible exactly where it matters — reefs, shelves, banks and the shape of a drowned river valley.',k:'EYE',e:'M',i:3},
{c:'water',t:'A water quality panel',d:'Turbidity, chlorophyll, salinity and SST at the inspected cell, with units and a note on which are modelled and which are proxies. `PURPOSE.md` says stated limits beat implied precision.',k:'PLAY',e:'S',i:1},
{c:'water',t:'A calibration target for ocean colour',d:'`calibrate.mjs` checks modern Earth tolerances for climate. Add three: open-ocean blue, coastal green and a bloom, each with a reference chromaticity and a tolerance, so the water colour cannot drift.',k:'PLAY',e:'M',i:2},
/* ----------------------------------------------------------------- sky -- */
{c:'sky',t:'A cloud shell at the grid resolution, sampled bilinearly',d:'Landed here. Coverage was read with `dirToCell` onto a `6 x 17 x 17` lattice — nearest neighbour at a quarter of the sim resolution — and then displaced radially by coverage, so every band edge was a hard terrace with a ledge on the limb. The shell now matches N and uses `sampleFaceField`, and the lift comes from convective type rather than raw coverage.',k:'EYE',e:'M',i:3},
{c:'sky',t:'Cloud top height as its own field',g:'cloudtop',d:'`W.clouds` is one coverage scalar. A cumulonimbus tops out at 15 km and a stratus deck at 1 km, and the difference is the whole visual character of a sky. Without a top height there is no anvil, no shadow length, no limb profile and no way for a storm to look like a storm.',k:'SIM',e:'M',i:3},
{c:'sky',t:'Cloud base as well as top',n:['cloudtop'],d:'Base height sets where the shadow lands and how dark the underside is. It is also the number that decides whether a mountain is in cloud.',k:'SIM',e:'S',i:2},
{c:'sky',t:'Separate the deck into layers',n:['cloudtop'],d:'Low, mid and high cloud have different colours, different transparencies and different motions, and a sky with two of them visible at once immediately reads as deep. Three coverage channels instead of one.',k:'SIM',e:'M',i:3},
{c:'sky',t:'Ice cloud versus water cloud',n:['cloudtop'],d:'Cirrus is thin, fibrous, and scatters forward hard; cumulus is dense and bright. `temp` at the cloud top decides which, and the two should not share a shader path.',k:'SIM',e:'M',i:2},
{c:'sky',t:'Raymarch the shell with real coverage, not a hash',d:'The cloud fragment shader marches ten steps through `densAt`, which is `cov * (0.45 + 0.35 * hash + 0.2 * hash)`. The hash has no spatial coherence at the scale of a cloud, so the result is grain rather than form. Feed the march from a 3D-ish noise anchored to the coverage field and the same ten steps produce cauliflower.',k:'EYE',e:'M',i:3},
{c:'sky',t:'Advect the cloud noise with the wind',n:['gpubasis'],d:'`boil` is `0.005 * sin(uTime * 0.7 + aPos.x * 18 + aPos.z * 14)` — a standing wave in object space. Clouds move downwind. Offsetting the noise lookup by the accumulated wind displacement is the difference between a texture and weather.',k:'EYE',e:'M',i:3},
{c:'sky',t:'Powder-sugar darkening at cloud edges',d:'The shell brightens toward the sun and never darkens where it should. Multiple scattering makes the thin edges of a cloud *darker* than the body under back-lighting — the effect that reads as depth in every convincing cloud render.',k:'EYE',e:'S',i:2},
{c:'sky',t:'An ITCZ that looks like an ITCZ',d:'`cloudsTick` adds `itczBand * moist * 0.55` with a Gaussian in latitude. The real feature is a broken chain of individual convective clusters, not a smooth band, and the difference is visible from orbit at a glance.',k:'SIM',e:'M',i:2},
{c:'sky',t:'Cyclones with an eye and spiral bands',d:'`storms.js` paints into `clouds` and `precip` after `cloudsTick` has already run, so the cloud of a named cyclone is overwritten the following tick. A tropical cyclone is the most recognisable single object on the Earth from space and this model has all the ingredients and no picture.',k:'SIM',e:'M',i:3},
{c:'sky',t:'Frontal cloud bands in mid-latitudes',d:'The comma-shaped cloud of an extratropical low is what a mid-latitude sky looks like from orbit. It requires a front, which requires a temperature gradient and a wind field that can tilt it.',k:'SIM',e:'L',i:2},
{c:'sky',t:'Lee waves and wave clouds downwind of mountains',n:['gpubasis'],d:'A stack of parallel bars downwind of a range, stationary while the air moves through them. Cheap to fake convincingly from elevation gradient plus wind direction, and instantly legible as "there is a mountain there".',k:'EYE',e:'M',i:1},
{c:'sky',t:'Cloud streets in the boundary layer',n:['gpubasis'],d:'Parallel rows of cumulus aligned with the wind over a heated surface. Another anisotropic-noise effect that reads as a physical process rather than a texture.',k:'EYE',e:'M',i:1},
{c:'sky',t:'Fog and low stratus that hug the terrain',d:'A separate near-surface layer that pools in valleys and clears over ridges. It is the effect that makes terrain look like terrain from the air.',k:'SIM',e:'M',i:2},
{c:'sky',t:'Contrails, if there is a civilisation',d:'`build` exists. A world with industry gets thin straight lines that no natural process makes, and they persist and spread. One of the most unambiguous fingerprints there is.',k:'EYE',e:'S',i:1},
{c:'sky',t:'Volcanic plumes that rise, spread and drift',d:'An eruption sets `ash[c]`. The plume of a large eruption is vertical for 20 km, spreads at the tropopause into an umbrella and then trails downwind for a thousand kilometres. `god/disaster.js` writes a receipt and the sky does nothing.',k:'SIM',e:'M',i:3},
{c:'sky',t:'A stratospheric aerosol veil after a big one',d:'`W.gases.sulphate` feeds `uAerosol` and reddens the limb. It should also whiten the whole sky, mute the surface contrast and give spectacular sunsets for two years — a thing you notice without being told.',k:'SIM',e:'M',i:2},
{c:'sky',t:'Dust storms that eat a hemisphere',d:'Ares has `signature: dust` and a lofting term. The picture never becomes opaque. A global dust storm is the defining event of that world and it should make the surface unreadable.',k:'SIM',e:'M',i:2},
{c:'sky',t:'Precipitation visible as shafts, not as a darker cell',d:'`precipF` now darkens and desaturates the ground it falls on. What it does not do is exist between the cloud and the ground. A rain shaft under a convective cell, slanted by the wind, is the single most legible weather image at the local scale.',k:'EYE',e:'M',i:3},
{c:'sky',t:'Snow that falls differently from rain',d:'One `precip` field for both. Snow falls slower, drifts further, accumulates and changes the albedo for months. The distinction is a temperature threshold.',k:'SIM',e:'S',i:2},
{c:'sky',t:'A humidity haze near the ground',d:'`uHaze` is driven by `W.hazeAntiGreenhouse` — a Titan-like organic haze. Ordinary humid air also scatters, which is why a tropical horizon is white and a desert horizon is sharp.',k:'EYE',e:'S',i:2},
{c:'sky',t:'Rainbows',d:'Sun behind, rain shaft in front, 42 degrees. Entirely computable from what is on screen and one of very few optical phenomena people can immediately date-stamp as correct or wrong.',k:'EYE',e:'M',i:1},
{c:'sky',t:'Halos and sun dogs in ice cloud',n:['cloudtop'],d:'22-degree halo through cirrus. The signature that the cloud above you is ice, which matters on a cold world.',k:'EYE',e:'M',i:1},
{c:'sky',t:'Noctilucent cloud at the summer terminator',d:'Thin, high, and lit from below after the surface is dark. The airglow term is already there; this is a different, better-motivated version of the same look.',k:'EYE',e:'S',i:1},
{c:'sky',t:'Give cloud cover a target and check it',d:'`cloudsTick` carries a comment that Earth mean cloud fraction is about 0.67 and that the previous coefficients locked it near 0.80 and whitened the globe. There is no assertion anywhere that the current coefficients hit 0.67. Add it to `calibrate.mjs` with a tolerance.',k:'PLAY',e:'S',i:3},
{c:'sky',t:'Check the other saturating fields too',d:'A 120-tick probe of the terra ruleset returns `moist` with an area-weighted mean of 0.775 and 69% of cells at or above 0.985. A field that is pinned at its ceiling over two thirds of the planet cannot express a gradient, which means every effect downstream of moisture — cloud, vegetation, soil colour, haze — is running on a constant.',k:'SIM',e:'M',i:3},
{c:'sky',t:'Cloud opacity from optical depth, not coverage',n:['cloudtop'],d:'`a = smoothstep(0.03, 0.48, dens) * mix(0.38, 0.95, ...)` conflates how much of the sky is covered with how thick the cover is. They are different numbers and only one of them makes it dark underneath.',k:'SIM',e:'M',i:2},
{c:'sky',t:'The sky as seen from the ground, in the local map',d:'The pixel map has a weather overlay that draws rain and cloud from above. Standing in a place, the sky is half of what you see, and its colour is the strongest single cue for time of day, latitude and air quality.',k:'EYE',e:'M',i:3},
{c:'sky',t:'A synoptic chart that is not index arithmetic',d:'`synopticChartSVG` samples cells as `(j * cols + i) * stride` into a 36 x 18 grid. That is a scrambled slice of cube-sphere memory with an ITCZ line drawn across it. Resample properly through `dirToCell` on a real lat-lon grid.',k:'PLAY',e:'S',i:3},
{c:'sky',t:'A cloud-cover instrument with a real number',d:'Area-weighted global cloud fraction, its trend, and the split by layer once layers exist — beside the value for modern Earth. Every teaching claim about albedo depends on this number and it is not on screen anywhere.',k:'PLAY',e:'S',i:2},
/* -------------------------------------------------------------- relief -- */
{c:'relief',t:'Level of detail on the planet mesh',g:'lodmesh',d:'`buildLatticeArrays` builds `6 * (N * GLOBE_SUBD + 1)^2` vertices — 786,432 at N=64 and subd 2 — and draws all of them at every distance. From the orrery table that is a hundred vertices per pixel; standing on a coast it is not enough. A per-face quadtree with distance-selected levels fixes both ends at once and is the precondition for every shape item below.',k:'EYE',e:'L',i:3},
{c:'relief',t:'Stop rebuilding the whole mesh on the main thread',n:['lodmesh'],d:'`rebuildGeometry` displaces every vertex, zeroes and re-accumulates every normal over the full index buffer, welds twelve edges and re-uploads two megabyte-scale buffers — synchronously, whenever geometry is dirty. On a phone that is a visible hitch every time a plate moves.',k:'SIM',e:'M',i:2},
{c:'relief',t:'Displace on the GPU from the height texture',n:['floatfield','lodmesh'],d:'With height in a float atlas the vertex shader can do the displacement and the CPU never touches positions again. Normals come from the texture gradient in the fragment shader, which is also higher quality than smoothed vertex normals.',k:'SIM',e:'M',i:3},
{c:'relief',t:'Remove the 60% piecewise-constant term from the height blend',d:'`e = e * 0.4 + (sum of five cell-centre values) / 5 * 0.6` mixes a bilinear vertex sample with a per-cell average, so 60% of the displacement is a terrace field at cell resolution. It was added to soften cliffs and it works by quantising the terrain.',k:'EYE',e:'S',i:2},
{c:'relief',t:'Uncap Earth relief and fix the scale honestly',d:'`relief = min(W.rule.relief, 0.028)` on Earth. True Earth relief is about 0.0014 of the radius — the cap is already a 20x exaggeration and it is presented as if it were the shape. State the exaggeration factor in the UI and let it be adjustable.',k:'PLAY',e:'S',i:2},
{c:'relief',t:'Vertical exaggeration as a visible control',d:'Every planetary visualisation exaggerates relief and the honest ones say by how much. A slider with a readout, defaulting to the current value, converts an unstated fudge into a stated one.',k:'PLAY',e:'S',i:2},
{c:'relief',t:'Silhouette detail at the limb',n:['lodmesh'],d:'The horizon of the planet is a polygon fan at the lattice resolution and it is the one place where the mesh resolution is unarguable. Extra tessellation weighted by `1 - abs(dot(N, V))` puts the vertices where they show.',k:'EYE',e:'M',i:2},
{c:'relief',t:'Fix the visible geometry seam at cube-face boundaries',d:'`weldGroups` averages normals across the twelve edges, which handles shading. It does not handle the `warp` distortion: cells near a face corner are stretched by roughly 30% relative to face centres, so any fixed-frequency detail changes scale as you cross a corner.',k:'EYE',e:'M',i:2},
{c:'relief',t:'Area-weight everything that averages neighbours',d:'`AREA[c]` varies by about 30% across a face and every diffusion, smoothing and normal computation in the renderer treats the four neighbours as equal. It quietly biases everything toward face centres.',k:'SIM',e:'M',i:2},
{c:'relief',t:'Crustal thickening during a run, not only at generation',d:'All continental thickening lives in `generateTectonics`: `crust[c] = min(1.6, crust[c] + 0.35)`. `tectonicsTick` touches `crust` only under a volcano. Two continents can converge for a billion years and not raise a metre, because nothing re-runs isostasy while the model runs.',k:'SIM',e:'M',i:3},
{c:'relief',t:'Isostatic rebound after ice',d:'An ice sheet 3 km thick depresses the crust by about a kilometre and it takes ten thousand years to come back. It is the reason for raised beaches, and it is a direct read of `ice` history against `crust`.',k:'SIM',e:'M',i:2},
{c:'relief',t:'Mountain belts with a strike',d:'A collision produces a linear belt perpendicular to the convergence direction, not a blob. The plate velocity field has the direction; nothing uses it to orient the uplift.',k:'SIM',e:'M',i:3},
{c:'relief',t:'Rift valleys with shoulders',d:'A continental rift is a trough between two uplifted flanks and it is the most recognisable extensional landform. Divergent boundaries currently lower the crust and nothing raises the shoulders.',k:'SIM',e:'M',i:2},
{c:'relief',t:'Ocean trenches at subduction zones',d:'The deepest features on the planet and the clearest evidence of subduction. A boundary classified as convergent-oceanic should carve one.',k:'SIM',e:'M',i:3},
{c:'relief',t:'Mid-ocean ridges with a median valley and transform offsets',d:'The ridge is the single most characteristic pattern on the ocean floor: a continuous crest, offset every few hundred kilometres by transforms, with symmetric age stripes either side. Every part of this is derivable from what tectonics already tracks.',k:'SIM',e:'M',i:3},
{c:'relief',t:'Age-depth subsidence of ocean floor',d:'Ocean floor sinks as the square root of its age — a law simple enough to be one line and strong enough to produce the entire abyssal hypsometry correctly.',k:'SIM',e:'S',i:3},
{c:'relief',t:'Hotspot tracks',d:'A chain of volcanoes getting older along the plate motion direction is the cleanest possible demonstration that plates move. It needs a mantle-fixed hotspot and a plate velocity, both of which exist.',k:'SIM',e:'M',i:3},
{c:'relief',t:'Erosion that respects rock hardness',n:['material'],d:'`erosionTick` applies the same rate everywhere. Differential erosion is why there are cuestas, hogbacks, mesas and inselbergs, and it is the mechanism that turns a rock-type field into landscape.',k:'SIM',e:'M',i:2},
{c:'relief',t:'Drainage that reorganises',d:'Steepest-descent routing recomputed from scratch each tick means the network has no history. River capture, divide migration and antecedent drainage are what make a real map look like it has a past.',k:'SIM',e:'L',i:2},
{c:'relief',t:'Terraces from base-level change',d:'When sea level falls, every river cuts down and leaves its old floodplain as a bench. A staircase of terraces along a valley is a legible record of the last five glacial cycles.',k:'SIM',e:'M',i:1},
{c:'relief',t:'A quarter-cut sphere showing the interior',d:'`render.js` already draws a layered stack for ice-shell moons and the X-ray mode discards front-facing fragments. A proper quarter cut, with core, mantle, convection cells, slabs and plumes visible inside, is the single most explanatory image a geodynamics model can produce.',k:'EYE',e:'M',i:3},
{c:'relief',t:'A vertical section along a drawn line',d:'Draw a great-circle segment on the globe, get the crust, mantle, ocean and atmosphere in section beneath it. Every geology textbook is made of this figure and the model has all the numbers.',k:'PLAY',e:'M',i:3},
{c:'relief',t:'Hypsometric curve as an instrument',d:'The bimodal distribution of Earth elevation — continents and abyssal plains with little between — is the signature of two crust types. Plot it live against Earth and any world that gets it wrong shows immediately.',k:'PLAY',e:'S',i:2},
{c:'relief',t:'Contour lines as an optional overlay',d:'The cell grid exists as a wireframe. Real contours at a stated interval, following the height field rather than the mesh, would make relief readable at a glance and would be the honest version of the terracing this pass just removed.',k:'PLAY',e:'M',i:1},
{c:'relief',t:'Shaded relief with a chosen light direction',d:'Cartographic hillshade from the north-west, independent of the sun, as a view mode. It is the standard way to read terrain and it does not fight the day-night cycle.',k:'PLAY',e:'S',i:2},
{c:'relief',t:'A slope map',d:'One number per cell, already implicit in the height gradient, and the fastest way to see whether the terrain generator is producing plausible landscapes or noise.',k:'PLAY',e:'S',i:1},
{c:'relief',t:'Keep the mesh honest with a vertex budget readout',n:['lodmesh'],d:'`globeVertexCount()` is exported and shown nowhere. Vertex count, index count, draw calls and the current LOD distribution belong in a debug corner.',k:'PLAY',e:'S',i:1},
{c:'relief',t:'A terrain regression against real hypsometry',d:'`refineEarthHypsometry` and `earthTerrain.js` are careful work with no test. Committing the target elevation histogram and asserting against it stops the shape from drifting when the erosion coefficients are next tuned.',k:'PLAY',e:'M',i:2},
/* ----------------------------------------------------------------- ice -- */
{c:'ice',t:'Ice thickness, not ice fraction',g:'icethick',d:'`W.ice[c]` is one number in 0..1 doing the work of sea ice concentration, land ice thickness and snow depth. A 3 km ice sheet and a 2 cm skim of sea ice are the same value. Everything in this category is blocked on separating them.',k:'SIM',e:'M',i:3},
{c:'ice',t:'Sea ice with an age',n:['icethick'],d:'First-year ice is grey and salty; multi-year ice is thicker, whiter and fresher. The colour difference is visible from orbit and the mechanical difference decides whether it survives a summer.',k:'SIM',e:'M',i:2},
{c:'ice',t:'Floes that drift with wind and current',n:['gpubasis'],d:'`iceSea[c]` grows and melts in place. Real pack ice is pushed, piles into ridges, opens leads, and exports out of the Arctic through one strait at a rate that matters to the whole North Atlantic.',k:'SIM',e:'M',i:2},
{c:'ice',t:'Leads and ridges that stay put',d:'This pass replaced the world-normal hash — which made the floe pattern swim across the ocean as the planet turned — with object-space fBm, and added a pressure-ridge highlight. The pattern is now stable but still arbitrary; leads should open where the ice is diverging.',k:'EYE',e:'S',i:2},
{c:'ice',t:'Melt ponds in summer',n:['icethick'],d:'The albedo of Arctic sea ice halves when it ponds, which is one of the strongest short-timescale feedbacks on the planet. Visually it turns a white sheet into a blue mosaic.',k:'SIM',e:'M',i:2},
{c:'ice',t:'Blue ice where snow is scoured away',n:['material'],d:'Bare glacier ice is deep blue-green because it absorbs red over metres. It appears in ablation zones, in crevasse walls and in wind-scoured patches, and it is the visual proof that ice is not white paint.',k:'EYE',e:'S',i:2},
{c:'ice',t:'Firn and the snow line on a glacier',n:['icethick'],d:'The boundary between the accumulation zone and the ablation zone is a visible line that moves up the glacier in a warm year. It is the single clearest indicator of glacier health.',k:'SIM',e:'M',i:1},
{c:'ice',t:'Crevasse fields where the ice is stretching',n:['icethick'],d:'Crevasses form where the strain rate exceeds a threshold, so they map the flow. Drawn as oriented line texture they turn an ice sheet into something that is obviously moving.',k:'EYE',e:'M',i:2},
{c:'ice',t:'Ice streams inside the sheet',n:['icethick'],d:'Most of the mass leaving an ice sheet goes through a few fast corridors with sharp shear margins. They are visible in every satellite velocity map and they are what makes an ice sheet a system rather than a lump.',k:'SIM',e:'L',i:2},
{c:'ice',t:'A shelf front with a real edge',n:['icethick'],d:'Where a sheet goes afloat it becomes a flat shelf ending in a cliff a hundred metres high and hundreds of kilometres long. It is the boundary that calving happens at, and the model has no concept of grounded versus floating.',k:'SIM',e:'M',i:3},
{c:'ice',t:'Icebergs as objects',n:['icethick'],d:'Calved, drifting, melting, seeding fresh water into the surface ocean where they go. Tabular ones from shelves, irregular ones from glaciers. They are also the cheapest way to make a polar sea look alive.',k:'SIM',e:'M',i:2},
{c:'ice',t:'Snow that accumulates and melts on a seasonal clock',d:'Snow cover is the largest seasonal change in the Earth albedo and the model cannot express it because snow shares a field with permanent ice. Half the planet changing colour twice a year is the most watchable thing a temperate world does.',k:'SIM',e:'M',i:3},
{c:'ice',t:'A snow line that follows the terrain',n:['material'],d:'Above the freezing level, everything is white; below it, nothing is. On a mountain that line is a contour and it is how you read altitude from a photograph.',k:'EYE',e:'S',i:3},
{c:'ice',t:'Sastrugi and wind crust on the plateau',d:'The interior of an ice sheet is not smooth: it is carved into parallel ridges by the katabatic wind, and it is the reason the surface has any texture at all at low sun.',k:'EYE',e:'M',i:1},
{c:'ice',t:'Katabatic wind off the ice',d:'Cold dense air draining off a plateau is the strongest persistent wind on the planet, and it drives the polynyas, the sea ice export and the ridge patterns above.',k:'SIM',e:'M',i:1},
{c:'ice',t:'Frost and rime at the small scale',d:'In the local map, a cold morning should look different from a cold afternoon. `paintIce` draws a fixed number of white squares scaled by `desc.ice`.',k:'EYE',e:'S',i:1},
{c:'ice',t:'Ice albedo that depends on grain size and sun angle',d:'Fresh snow reflects about 0.85, old snow 0.5, and both fall off at high solar zenith. `refreshColours` uses two constants, 0.82 and 0.95 by way of a lerp to `[230, 238, 248]`.',k:'SIM',e:'M',i:2},
{c:'ice',t:'Dirty ice from dust and ash',d:'`W.ash` advects and settles and never darkens ice. Volcanic ash on a snowfield accelerates melt dramatically and is a visible grey stain that persists for years.',k:'SIM',e:'S',i:2},
{c:'ice',t:'Cryoconite and algal snow',d:'Red snow from algae and dark cryoconite holes are the biosphere colonising ice. On a world where life is the subject, life growing on the ice is worth drawing.',k:'SIM',e:'M',i:1},
{c:'ice',t:'A snowball transition that looks like one',d:'`iceTick` floors `iceLand` above 0.86 and `iceSea` above 0.88 to stop the caps disappearing, which is a hard clamp compensating for missing circulation. A runaway to a global ice cover should be a thing you watch happen, cell by cell, not a number crossing a threshold.',k:'SIM',e:'M',i:3},
{c:'ice',t:'Remove the polar clamps once circulation carries heat',d:'The two floors above are stated in the code as stabilisers. They are also why the caps never respond correctly to obliquity or to a change in ocean heat transport. They should be deleted the moment the ocean can do the job.',k:'SIM',e:'M',i:2},
{c:'ice',t:'Ice shells rendered as ice, not as a stack',d:'The three-layer mantle/ocean/lid stack for Europa-class moons is a schematic drawn with `healthProg`, the flat-colour shader. The actual surface of such a moon — chaos terrain, double ridges, lenticulae, a nearly craterless plain — is one of the most distinctive looks in the solar system.',k:'EYE',e:'M',i:3},
{c:'ice',t:'Tidal fracture patterns on a locked moon',d:'`iceshell.js` computes tidal heating. The stress field from a diurnal tide on a synchronous satellite produces the cycloid cracks that are the signature of Europa, and they are derivable from the same numbers.',k:'SIM',e:'L',i:2},
{c:'ice',t:'A cryovolcanic plume',d:'Enceladus is in the catalogue. A plume from a south polar fissure, backlit, is the single image that made that moon famous.',k:'EYE',e:'M',i:2},
{c:'ice',t:'An ice budget instrument',d:'Total ice volume, split into sea, land and shelf, with sea level equivalent and rate of change. The mass balance is the number that matters and there is nowhere to read it.',k:'PLAY',e:'S',i:2},
{c:'ice',t:'Calibrate ice extent against modern Earth',d:'`calibrate.mjs` checks temperature and gases. Sea ice extent by hemisphere and season, and land ice area, have well-known values and no assertion.',k:'PLAY',e:'S',i:2},
/* ---------------------------------------------------------------- life -- */
{c:'life',t:'Leaf area index rather than a green multiplier',g:'lai',d:'`lifeGreen` is `lifeF` masked by land and ice and multiplied by `0.75 + 0.35 * nppF`. Real canopy has a density that changes the albedo, the roughness, the shadowing and the colour independently, and one scalar in 0..1 cannot carry any of that.',k:'SIM',e:'M',i:3},
{c:'life',t:'Canopy colour from pigment, not from the biome table',n:['lai'],d:'`lifeColour.js` already picks guild pigments and the shader mixes toward three fixed tints by `guildF`. Deriving the colour from the actual dominant pigment of the actual dominant guild is a change from decoration to consequence, and it is what makes a purple retinal world look different for a reason.',k:'SIM',e:'M',i:3},
{c:'life',t:'A seasonal green wave',n:['lai'],d:'The most watchable annual signal on Earth is the northern hemisphere greening up over six weeks and browning again. `W.season` and `npp` exist; the shader multiplies by NPP and calls it phenology, which is a static consequence, not a wave that travels.',k:'EYE',e:'M',i:3},
{c:'life',t:'Deciduous autumn colour',n:['lai'],d:'A whole biome changing to orange and red for a month. The biome table already distinguishes `tempDeciduous` from `boreal`.',k:'EYE',e:'S',i:2},
{c:'life',t:'Burn scars that fade',d:'Fire exists in the extinction and disaster layers and leaves no mark. A black scar going grey then green over a decade is one of the clearest signs that time is passing.',k:'SIM',e:'M',i:2},
{c:'life',t:'Ecotones instead of hard biome edges',d:'`BIOMES` assigns one label per cell, so the boundary between savanna and forest is a cell edge. Real transitions are gradients tens of kilometres wide, and drawing them is mostly a matter of blending the two neighbours by their climatic distance.',k:'EYE',e:'M',i:3},
{c:'life',t:'Riparian corridors',d:'A green line following a river across a desert is visible from orbit and is the most legible interaction between two subsystems the model has. Discharge now reaches the shader; the vegetation response does not.',k:'SIM',e:'S',i:2},
{c:'life',t:'Mangrove, salt marsh and the vegetated intertidal',d:'The intertidal field is drawn as bare ochre mud everywhere. On a warm coast it is forest standing in salt water, and it is where a lot of the carbon burial the redox tower depends on actually happens.',k:'SIM',e:'M',i:2},
{c:'life',t:'Reefs that build structure',d:'`W.reef` tints the water. A reef is a physical body that shallows the water, breaks the swell, makes a lagoon behind it and dies visibly white when the water is too warm.',k:'SIM',e:'M',i:3},
{c:'life',t:'Bleaching as an event you watch',d:'`refreshColours` already turns reef cells near-white when `temp > 0.74` and life is low. Making it a timed event with a recovery period, rather than an instantaneous function of temperature, turns a colour rule into a story.',k:'SIM',e:'S',i:2},
{c:'life',t:'Phytoplankton blooms with a shape',d:'A bloom is an eddy-shaped filament following the current, not a circular patch on a cell. It is the clearest visual link between the ocean physics and the biosphere.',k:'SIM',e:'M',i:3},
{c:'life',t:'Microbial mats and stromatolites at the right zoom',d:'`stampMats` and `stampStromatolites` exist in the local map only. For three billion years of the run these are the entire biosphere, and from orbit the planet should look subtly, unmistakably different because of them.',k:'EYE',e:'M',i:3},
{c:'life',t:'A land surface that is bare before land plants',d:'Deep-time runs paint the same green on the continents at 3 Ga as at 300 Ma. Before land plants the continents were rock and microbial crust, and the colour difference is the single most important visual fact about the Palaeozoic.',k:'SIM',e:'M',i:3},
{c:'life',t:'Individuals in the local map with real positions',d:'`ENT.meta[i].cell` plus a hash jitter. A being should have a position that moves continuously, a heading it turns toward, and a reason to be where it is.',k:'SIM',e:'M',i:3},
{c:'life',t:'Herds, flocks and shoals',d:'Entities are drawn independently. Grouping is the most legible behaviour an animal has and it is a two-rule flocking model.',k:'SIM',e:'M',i:2},
{c:'life',t:'Tracks and trails left behind',d:'`noteWear` and `wearAt` exist in `present.js` and decay at 0.965 a frame. Paths worn between a water hole and a grazing ground are how a landscape shows it is inhabited.',k:'EYE',e:'S',i:2},
{c:'life',t:'Predation visible as an event',d:'The ecology model has trophic levels. Seeing one animal catch another, once, is worth more than any diversity chart for making the biosphere feel real.',k:'PLAY',e:'M',i:2},
{c:'life',t:'Morphology that follows the body plan',d:'`morphology.js` and the eight-slot body plan exist and `drawSprite` picks from a fixed sprite table by `m.kind`. A creature with a evolved plan should be drawn from that plan, so two runs produce visibly different animals.',k:'EYE',e:'L',i:3},
{c:'life',t:'Size that follows mass',d:'`planScale` is `0.55 + plan.size * 0.35`, capped at 1.35. Body mass across a real fauna spans six orders of magnitude and the difference between a beetle and a sauropod should be unmistakable at a glance.',k:'EYE',e:'S',i:2},
{c:'life',t:'Colour that follows habitat',d:'`KIND_RGB` is a fixed table. Countershading, cryptic colouring against the local substrate and warning colours are all selectable traits and all immediately readable.',k:'SIM',e:'M',i:2},
{c:'life',t:'A canopy from above in the local map',d:'`paintBiomeTexture` draws eight ellipses for rainforest. Seen from directly above, a forest is a packed field of crowns with gaps and shadow between them, and it is one of the most recognisable textures there is.',k:'EYE',e:'M',i:3},
{c:'life',t:'Shadows cast by vegetation in the local map',d:'`castShadow` is applied to entities only. Trees casting shadows in the direction the globe says the sun is would tie the two views together instantly.',k:'EYE',e:'S',i:3},
{c:'life',t:'Life that is visible in the water column, not just on the surface',d:'`stampOceanLife` draws at the surface. Depth is what an ocean has that a land surface does not, and a silhouette below the surface is a strong cue.',k:'EYE',e:'M',i:1},
{c:'life',t:'Dead things',d:'Nothing decays. A carcass, a fallen tree, a shell bed, a bone — the evidence that the previous state of the world existed is what makes a place feel continuous rather than generated.',k:'SIM',e:'M',i:2},
{c:'life',t:'A biosphere legend that reads as a food web',d:'The local map has a colour legend of guilds. What it does not show is who eats whom, which is the structure the model actually simulates.',k:'PLAY',e:'M',i:2},
{c:'life',t:'A Whittaker plot with the current world plotted on it',d:'`instruments.js` has a Whittaker biome diagram. Marking every cell of the current world as a point on it, live, is the fastest way to see whether a world has a plausible climate space or a degenerate one.',k:'PLAY',e:'S',i:2},
{c:'life',t:'Compare against the Earth curve at the same age',d:'`earthRecord.js` carries the real diversity curve. Overplotting a run against it, with the deviation called out, is the honest version of the claim that the model is right in kind.',k:'PLAY',e:'M',i:2},
{c:'life',t:'A rendered-life regression',n:['imgtest'],d:'Four reference frames — a Precambrian ocean, a Carboniferous swamp, a Pleistocene steppe, a modern coast — diffed against committed images. Life is the subject of the product and it has no visual test.',k:'PLAY',e:'M',i:2},
/* --------------------------------------------------------------- pixel -- */
{c:'pixel',t:'Give the pixel map a visual hierarchy',g:'hierarchy',d:'Every layer draws at roughly the same alpha and the same density: the base fill, then `paintCellDetail`, `paintBiomeTexture`, `stampLife`, `stampBuildings`, then a full-patch grid, rivers, weather and plumes on top. A savanna cell, a river and a herd all put down about the same amount of ink, so nothing reads as figure and nothing reads as ground. Assign every layer an explicit tier and an alpha budget.',k:'EYE',e:'M',i:3},
{c:'pixel',t:'Cut the density of the biome hatch stamps',n:['hierarchy'],d:'`savanna` draws 6 to 14 strokes per cell, `grassland` 10 rects, `tundra` 9, `tempDeciduous` up to 14, and the default case up to 40. At a 17-cell patch that is up to 11,000 canvas operations of texture alone, and the visual result at a distance is uniform noise.',k:'EYE',e:'S',i:3},
{c:'pixel',t:'A shared lighting model between the two views',g:'sharedlight',d:'The globe computes light in a fragment shader from `uSun` and the surface normal; the map calls `cellLight` and `applyLight`. They disagree on direction, on colour and on the terminator, so the same place looks lit differently in the two panels that are on screen at the same time.',k:'EYE',e:'M',i:3},
{c:'pixel',t:'One shared description of a cell',n:['sharedlight'],d:'`describeCell` in `present.js` is the closest thing and the globe does not use it. The renderer computes colour in `refreshColours`, the map computes it again in `describeCell` plus `mixGuild` plus `applyLight`, and the two drift every time either is touched.',k:'SIM',e:'M',i:3},
{c:'pixel',t:'Aerial perspective across the patch',n:['hierarchy'],d:'The patch is drawn flat and uniformly sharp. Even at 25 km across, the far edge of a view should be slightly hazier and cooler than the near edge, and that single cue is what converts a texture into a landscape.',k:'EYE',e:'M',i:2},
{c:'pixel',t:'A horizon',n:['hierarchy'],d:'The map is a top-down square. The metaphor is that you shrank and walked in, and nothing in the frame acknowledges that you are standing on a sphere. Even a slight perspective tilt with a horizon band at the top would change what the panel means.',k:'EYE',e:'L',i:3},
{c:'pixel',t:'Relief shading from the height field',d:'`paintSlope` draws a shade on one edge of a cell. The patch has a full height field available through `cells`, and a proper hillshade with the same sun direction the globe is using would make the terrain legible instantly.',k:'EYE',e:'M',i:3},
{c:'pixel',t:'Sub-cell interpolation of the base colour',n:['sharedlight'],d:'Every cell is `ctx.fillRect` of one flat colour, which is why the map is visibly blocky while the globe is smooth. Bilinear interpolation between the four neighbouring cell colours, drawn into an `ImageData` once per frame, is both faster and better looking than the current per-cell fill plus stamps.',k:'EYE',e:'M',i:3},
{c:'pixel',t:'Draw through ImageData, not through hundreds of fillRect calls',g:'imgdata',d:'The inner loop is `fillRGB` then `ctx.fillRect(x, y, cellPx, cellPx)` per cell, plus a stroke for the focus, plus a hover stroke, plus every stamp. Compositing into a typed array and blitting once is an order of magnitude cheaper and makes per-pixel effects — interpolation, noise, shading, dithering — possible at all.',k:'SIM',e:'M',i:3},
{c:'pixel',t:'Cache the static layers',n:['imgdata'],d:'The base colour, the relief and the biome texture of a cell change on the sim tick, not on the frame. Render them to an offscreen canvas keyed by the patch and the tick, and redraw only the moving layers every frame.',k:'SIM',e:'M',i:3},
{c:'pixel',t:'Stop rebuilding the patch every frame',d:'`unwrapPatch` is memoised in `_unwrap`, but `drawLocalView` still calls `describeCell` for every cell of the patch on every frame, along with `cellLight`, `mixGuild`, `applyLight` and `legendKeyAt`. At a 57-cell patch that is 3,249 full descriptions at 60 Hz.',k:'SIM',e:'M',i:3},
{c:'pixel',t:'Honest handling of the cube-corner holes',d:'A BFS unwrap of a cube sphere cannot tile a square, so `cells[i] < 0` cells are drawn as a dark box with an ochre outline. It is honest and it is also eight visible holes in the middle of the picture. A radial or hexagonal patch layout would have none.',k:'EYE',e:'M',i:2},
{c:'pixel',t:'A patch that is not a square of cells',d:'The square comes from the unwrap, not from anything about the place. A disc of constant radius on the sphere is both more natural to look at and free of corner holes.',k:'EYE',e:'M',i:2},
{c:'pixel',t:'Water drawn as water',d:'`paintWater` is 77 lines of stamps. With `imgdata` in place it could be a real surface: depth-graded colour, a reflected sky at the edges, an animated normal, and the same GGX glint the globe now uses.',k:'EYE',e:'M',i:3},
{c:'pixel',t:'A shoreline with surf and wet sand',d:'`paintCoast` draws an edge. The strandline is the most detailed part of any coastal view — surf, foam, wrack, wet sand darker than dry, and all of it moving with the tide the model already computes.',k:'EYE',e:'M',i:3},
{c:'pixel',t:'Rivers as continuous polylines across cells',d:'`paintRivers` builds segments per cell and strokes them. The result is a chain of dashes with mitred corners rather than a continuous channel with a width that grows downstream.',k:'EYE',e:'M',i:2},
{c:'pixel',t:'Weather that sits between the viewer and the ground',d:'`weatherOverlay` paints after everything else at full patch scale. Rain, cloud shadow and snow are between the eye and the ground and should occlude accordingly, with a parallax that says the cloud is above.',k:'EYE',e:'M',i:2},
{c:'pixel',t:'A day cycle you can feel',d:'`cellLight` and `dayPhase` exist. What is missing is the *colour* of the light: long shadows and warm light at low sun, short shadows and neutral light at noon, blue shadow fill at dusk.',k:'EYE',e:'M',i:3},
{c:'pixel',t:'Moonlight that reads as moonlight',d:'`status.moonlit` is computed and shown as a word. A moonlit night is not a dark day: it is dim, blue, low in contrast, and the shadows are soft.',k:'EYE',e:'S',i:2},
{c:'pixel',t:'Sprites that are lit from the same direction as the ground',d:'`drawSprite` takes `flip` and `lean` and no light. A sprite with a lit side and a shaded side, matching `cellLight`, would sit in the scene instead of on top of it.',k:'EYE',e:'M',i:3},
{c:'pixel',t:'Contact shadows on every sprite, not only above cellPx 8',d:'`castShadow` runs when `hiFi && cellPx >= 8`. Below that the beings float. A single dark pixel under each is enough.',k:'EYE',e:'S',i:2},
{c:'pixel',t:'Depth sorting within a cell',d:'Entities are drawn in `ENT` order with a hash jitter, so a creature at the back of a cell can be drawn over one at the front. Sorting by y within the patch is one line.',k:'EYE',e:'S',i:2},
{c:'pixel',t:'Scale that is legible without the bar',d:'`drawScaleBar` says 1,632 km. Nothing in the picture is a known size, so the number has nothing to attach to. A recognisable object at a known scale — a tree, a herd, a settlement — does more than the bar.',k:'EYE',e:'M',i:2},
{c:'pixel',t:'A zoom rung between the globe and the patch',d:'`localFrameIndex` offers 7, 11, 17, 25, 37, 57. Going from a whole planet to a 25 km square is a jump of four orders of magnitude in one click, and there is nothing in between.',k:'PLAY',e:'M',i:3},
{c:'pixel',t:'A continuous zoom rather than six rungs',d:'The rungs exist because the patch is rebuilt per radius. With a cached, interpolated base the zoom could be continuous, and the transition from orbit to ground could be one gesture.',k:'PLAY',e:'L',i:3},
{c:'pixel',t:'Match the palette between the two views',d:'Set the globe and the map side by side on the same cell and the colours do not match — different lighting, different guild mixing, different biome interpretation. It is the most visible inconsistency in the product.',k:'EYE',e:'M',i:3},
{c:'pixel',t:'Antialias the things that should be smooth',d:'`ctx.imageSmoothingEnabled = false` is set for the base pass and toggled per stamp. Terrain and water should be smooth; sprites and the grid should be crisp. Right now the switch is made per call and inconsistently.',k:'EYE',e:'S',i:2},
{c:'pixel',t:'A deliberate pixel-art grid, if that is the intent',d:'The map is called a pixel map and is drawn at `cellPx` up to 20-odd device pixels with smoothing sometimes on. Either commit to a pixel grid with a fixed palette and hard edges, or commit to a continuous image. The current halfway is why it reads as noisy.',k:'EYE',e:'M',i:3},
{c:'pixel',t:'A palette with a stated number of colours',n:['hierarchy'],d:'Every stamp routine invents its own `rgba(...)` literal — there are more than sixty in `localview.js`. A named palette derived from the biome and guild tables would make the map coherent and would make a change to it a one-line change.',k:'EYE',e:'M',i:3},
{c:'pixel',t:'Dither instead of blend',n:['imgdata'],d:'`ditherCell` exists and is used only for low-fidelity life. Ordered dithering between two palette colours is the classic way to get gradients in a limited palette and it would suit the map far better than alpha compositing sixty different translucent colours.',k:'EYE',e:'M',i:2},
{c:'pixel',t:'Show the same event in both views at once',d:'An eruption, a flood, a bloom or a first snowfall should be visible on the globe and in the patch simultaneously, with the rim on the globe pulsing where the patch is. The rim exists; the shared event does not.',k:'PLAY',e:'M',i:3},
{c:'pixel',t:'A tooltip that names what is under the cursor',d:'`patch.status` computes biome, guild, place sentence, water stage, day phase and a chronicle whisper, and the panel shows a compressed strip of it. Hovering a specific *thing* — this animal, this river, this settlement — should name that thing.',k:'PLAY',e:'M',i:2},
{c:'pixel',t:'Let the patch be pinned, followed or free',d:'`pickFocusCell` already supports pin and a life-seeking mode with a tour. What it does not support is following one individual as it moves, which is the most natural thing a person will want to do.',k:'PLAY',e:'M',i:2},
{c:'pixel',t:'A performance budget for the map',d:'The map runs from the render loop and can issue tens of thousands of canvas calls a frame. Instrument it, show the number, and cap the stamp count by frame time rather than by `cellPx >= 6`.',k:'PLAY',e:'S',i:2},
/* -------------------------------------------------------------- motion -- */
{c:'motion',t:'Give the globe the presentation clock the map already has',g:'globeclock',d:'`presentAdvance` and `presentTime` decouple the view from the 10 kyr sim tick and `localview.js` uses them for stamp phase, wind sway and gait. The globe gets `uTime` and uses it for exactly two things: the lightning hash and the aurora pulse. Nothing else on the planet moves between two frames.',k:'EYE',e:'S',i:3},
{c:'motion',t:'Interpolate every field the shader reads',n:['globeclock'],d:'`life`, `temp` and `ice` are lerped between `prev` and current. Cloud, moisture, NPP, wind, sediment, precipitation and discharge all snap on the tick. On a slow tick that snap is the loudest motion in the frame.',k:'EYE',e:'S',i:3},
{c:'motion',t:'Advect the cloud texture, not just the coverage',n:['globeclock','gpubasis'],d:'Even with a perfect coverage field, the detail noise inside a cloud is anchored to object space. Offsetting the lookup by the integrated wind makes the sky flow.',k:'EYE',e:'M',i:3},
{c:'motion',t:'Flow streaks with a lifetime and a taper',d:'`fillFlowStreaks` emits `prev -> pos` for 1600 particles, one frame long, drawn as `gl.LINES` at a constant alpha with no width and no taper. A tracer needs a trail of several segments fading to nothing at the tail, and a lifetime so that particles do not all collapse onto the same handful of streamlines.',k:'EYE',e:'M',i:3},
{c:'motion',t:'Sample the velocity between cells, not at the cell centre',d:'`stepFlow` takes `W.oceanU[dirToCell(pos)]`, so every particle entering a cell moves in exactly the same direction. That is what makes tracer paths collapse onto a small number of shared polylines with visible corners at cell boundaries.',k:'SIM',e:'S',i:3},
{c:'motion',t:'Draw the streaks as ribbons with width',d:'`gl.lineWidth` is capped at 1 in almost every WebGL implementation, so a line overlay is always one pixel and always aliased. A triangle-strip ribbon with a width in world units is the only way to get a readable flow line.',k:'EYE',e:'M',i:2},
{c:'motion',t:'A residence-time or dye tracer',d:'Release dye in one place and watch where it goes. It is the single clearest way to show that a circulation exists, and it doubles as a teaching instrument for the conveyor.',k:'PLAY',e:'M',i:3},
{c:'motion',t:'Waves that travel',n:['swell'],d:'The only wave in the model is `tsunamiTick`, which walks all cells per tsunami per tick computing an `acos` each and marking anything near an expanding radius. Nothing else propagates.',k:'SIM',e:'M',i:2},
{c:'motion',t:'Vegetation that sways',d:'`windSway` exists in `present.js` and is used by the local map only. At the zoom where a canopy is visible on the globe, it should move.',k:'EYE',e:'S',i:1},
{c:'motion',t:'A day that turns',d:'`S.sunAng` advances and `S.dayWatch` speeds the presentation clock. What is missing is the sense that this is a rotation: no terminator sweep you can watch, no shadows lengthening, no city lights coming on along a line.',k:'EYE',e:'M',i:3},
{c:'motion',t:'City lights that switch on at dusk',d:'`col += vec3(1.0, 0.72, 0.35) * uNight * night * vD.b * 0.14` fades with the night factor. Real lights come on at a threshold and go off at dawn, and the wave of that crossing the planet is unmistakable.',k:'EYE',e:'S',i:2},
{c:'motion',t:'A tide that visibly rises and falls',d:'`tidePhase` is computed every tick and reported as a word. Twice a day is far faster than the sim tick, so this is a presentation-clock effect: the shoreline should breathe against the presentation clock, phase-locked to the moon position the renderer already draws.',k:'EYE',e:'M',i:3},
{c:'motion',t:'Separate the presentation clock from the sim clock properly',d:'`dtYr` ranges from 10 to tens of thousands of years and `presentTime` runs in seconds. Every animated effect needs to declare which clock it is on, and right now some are on neither — `boil` in the cloud shader runs off `S._t * 0.001`, a raw millisecond counter.',k:'SIM',e:'M',i:3},
{c:'motion',t:'Time-lapse mode for the slow fluids',d:'Mantle convection, plate motion and the Wilson cycle are invisible at any real playback rate. A dedicated fast-forward that renders accumulated motion as trails is how those systems become watchable at all.',k:'PLAY',e:'M',i:2},
{c:'motion',t:'Motion blur on the fast-forward',d:'At high time compression everything strobes. Even a two-frame accumulation would make a fast-forward legible instead of flickering.',k:'EYE',e:'M',i:1},
{c:'motion',t:'Ease the camera, do not snap it',d:'The local map has a pan easing with a hold canvas for far jumps. The globe camera has none, so switching worlds or jumping to a chronicle event is a cut.',k:'EYE',e:'S',i:2},
{c:'motion',t:'Respect reduced motion everywhere',d:'`reducedMotion()` is checked in `flowviz`, in the pan easing and in a couple of stamps. The cloud boil, the aurora pulse, the lightning flash, the rim pulse and the storm animation do not check it.',k:'PLAY',e:'S',i:2},
{c:'motion',t:'Frame-rate independence for every animated term',d:'`stepFlow` clamps `dt` to 0.08 and multiplies by 0.55; the pan uses wall-clock; `boil` uses a raw counter. A dropped frame changes the result of some of these and not others.',k:'SIM',e:'S',i:2},
{c:'motion',t:'A settle animation when a world is generated',d:'Generation is instantaneous and the world appears fully formed. Watching the ocean fill, the first ice form and the first green appear over three seconds would make the beginning of a run an event.',k:'PLAY',e:'M',i:2},
{c:'motion',t:'Transitions between worlds',d:'The catalogue switch is a cut. A crossfade, or better a morph through the shared parameter space, would make comparing two real planets a felt thing rather than two screenshots.',k:'PLAY',e:'M',i:2},
{c:'motion',t:'Camera shake on impact',d:'A meteor sets a crater and the picture does not react. One of the very few places where a violent camera response is both cheap and correct.',k:'PLAY',e:'S',i:1},
{c:'motion',t:'Let a chronicle entry take you there',d:'`W.chron` records events with cells. Clicking one should fly the camera and the patch to that place and that time, easing all the way.',k:'PLAY',e:'M',i:3},
{c:'motion',t:'A timeline scrubber that previews',d:'The Holocene Earth strip at the bottom of the screen jumps between epochs. Scrubbing it with a live preview of the globe is the interaction the strip is asking for.',k:'PLAY',e:'M',i:2},
{c:'motion',t:'Record a run as a video',d:'`finale.js` exports an artefact and `exportPng.js` exports charts. A time-lapse of a whole run, rendered offline at a fixed frame rate, is the thing anyone would actually want to share.',k:'PLAY',e:'M',i:2},
{c:'motion',t:'A frame-time graph',d:'Every item in this document costs milliseconds and nothing displays them. A small rolling graph with the per-pass breakdown is the difference between tuning and guessing.',k:'PLAY',e:'S',i:2},
{c:'motion',t:'Golden animation frames in the test suite',n:['imgtest'],d:'Static reference images will not catch a broken animation. Render three frames at fixed presentation times and hash all three.',k:'PLAY',e:'M',i:2},
/* --------------------------------------------------------------- night -- */
{c:'night',t:'Emissive sources that do not scale with exposure',d:'City lights, lava, bioluminescence and aurora are all added before `tonemap(col * uExposure)`, so turning the exposure up for a dim star also brightens the cities. They should be composited after the curve or carried in a separate emissive buffer.',k:'EYE',e:'S',i:2},
{c:'night',t:'City lights with a geography',d:'`vD.b` is the blue channel of the biome colour standing in for build density. Real night lights follow coasts, rivers and roads, cluster into a few very bright points, and have a colour that changes with technology.',k:'EYE',e:'M',i:3},
{c:'night',t:'Light colour that dates the civilisation',d:'Sodium orange, mercury blue-green and LED white are three distinct eras and the model has a time axis. It is one of the cheapest ways to make a century visible.',k:'EYE',e:'S',i:2},
{c:'night',t:'Skyglow above the cities',d:'A city seen from orbit at an angle has a dome of scattered light above it. It is also the mechanism by which light pollution is a thing, which matters if the model ever wants to say something about it.',k:'EYE',e:'M',i:1},
{c:'night',t:'Fires and flares distinct from settlements',d:'Gas flares and wildfires are the other two things visible at night and both are much redder and much more variable than a city.',k:'EYE',e:'S',i:2},
{c:'night',t:'Lava that glows through the ash',d:'`col += vec3(1.0, 0.35, 0.08) * uNight * night * smoothstep(0.7, 1.0, vD.a) * 0.08` keys off the climate channel of the vertex colour. Active lava should be its own field, glowing at a temperature, dimming as it crusts over.',k:'SIM',e:'M',i:3},
{c:'night',t:'Aurora on a real magnetic field',d:'`oval = exp(-pow(magLat - 0.72, 2.0) * 80.0) * uMag` with the dipole tilted by `uMagTilt`. The oval expands and brightens during a storm, and `star.js` knows about stellar activity.',k:'SIM',e:'M',i:2},
{c:'night',t:'Aurora with structure',d:'The current oval is a smooth Gaussian ring. Real aurora is curtains, rays and folds, and it moves on a timescale of seconds.',k:'EYE',e:'M',i:2},
{c:'night',t:'Aurora on the shell and on the surface should agree',d:'`atmoProg` and `planetProg` each compute their own oval with different constants — `70.0` versus `80.0` in the exponent, and the shell version ignores `uMagTilt` entirely. They are the same phenomenon drawn twice.',k:'EYE',e:'S',i:2},
{c:'night',t:'Airglow as a limb ring, not a night wash',d:'`airglow = night * rim2 * (0.3 + uOzone * 0.5)` paints the whole night limb. Real airglow is a thin green ring at a specific altitude and it is one of the most recognisable features of a night Earth photograph.',k:'EYE',e:'S',i:2},
{c:'night',t:'Moonlight with the right colour and the right softness',d:'Moonlight is sunlight and is not blue; it looks blue because of how the eye behaves at low light. Rendering it as a dim neutral and applying a Purkinje shift in the tone curve is both more correct and better looking than `vec3(0.14, 0.19, 0.34)`.',k:'EYE',e:'M',i:2},
{c:'night',t:'A moon with a real phase and a real terminator',d:'Landed here: the moon was drawn with `healthProg`, whose whole fragment shader is `o = vec4(uCol, 0.85)` — an unlit disc whose brightness came from a scalar `lit`. It now has a lit sphere, maria, craters, Lommel-Seeliger backscatter, an opposition surge and limb darkening. What it still lacks is a real surface and a real libration.',k:'EYE',e:'M',i:3},
{c:'night',t:'Multiple moons',d:'The catalogue includes systems with several. `W.moon` is one object with a mass and a distance.',k:'SIM',e:'M',i:1},
{c:'night',t:'Moonrise and moonset as events',d:'The moon is drawn on a circle around the planet at a fixed radius. Whether it is up at a given place at a given hour is a fact the tidal code already computes.',k:'PLAY',e:'S',i:1},
{c:'night',t:'A starfield that is the actual sky',d:'`NSTAR` 1400 points from a seeded RNG, uniform on the sphere. For a real catalogued system the sky has a real appearance, and for any system the Milky Way is a band, not an absence.',k:'EYE',e:'M',i:2},
{c:'night',t:'Stars occluded by the atmosphere near the limb',d:'The starfield is drawn before the planet with depth write off. Stars should extinguish through the air as they set, not vanish at a hard edge.',k:'EYE',e:'S',i:1},
{c:'night',t:'The night side in the local map',d:'The map dims and cools at night and that is all. A night landscape has almost no colour, high contrast at point sources, and a completely different set of visible things.',k:'EYE',e:'M',i:3},
{c:'night',t:'Nocturnal fauna',d:'`isOutNow(kind, cell, id)` already gates which entities are visible by time of day. The night shift should be visibly a different set of animals, not the same ones at lower alpha.',k:'SIM',e:'S',i:2},
{c:'night',t:'Bioluminescence at the scale you can see it',d:'On the globe it is a wash over the productive ocean. In the map it should be individual points in the water and a glow in the wake of anything that moves.',k:'EYE',e:'M',i:2},
{c:'night',t:'Thermal emission on a hot world',d:'A lava world or a hot Jupiter is self-luminous in the visible. `exophysics.js` computes equilibrium temperature and nothing glows.',k:'SIM',e:'M',i:2},
{c:'night',t:'A synchronous rotator has a permanent night side',d:'`Mercury 3:2` and tidal locking are in the test suite. A locked world has one hemisphere that never sees the sun and a terminator that never moves, and that is the defining visual fact about most planets in the catalogue.',k:'SIM',e:'M',i:3},
{c:'night',t:'The eyeball ocean of a locked world',d:'A tidally locked ocean world has open water under the substellar point and ice everywhere else. It is the most striking image in exoplanet science and the model has all the physics for it.',k:'SIM',e:'M',i:3},
{c:'night',t:'A night-side instrument',d:'What is emitting, how much, and where. It is the observable a real telescope would get from a phase curve, which ties the picture to the transit spectrum instrument that already exists.',k:'PLAY',e:'M',i:2},
{c:'night',t:'A night reference frame in the image test',n:['imgtest'],d:'Every reference frame in a test suite tends to be a day frame. Half the planet is not.',k:'PLAY',e:'S',i:1},
/* ---------------------------------------------------------------- body -- */
{c:'body',t:'A shader per world class, not one shader with an uEarth switch',g:'worldshader',d:'`planetProg` carries `uEarth`, `uDaisy`, `uXRay`, `uMoon`, `uHaze` and a dozen more branches, and every world in a 120-body catalogue goes through it. A rocky world, an ice world, an airless world and a gas giant have almost nothing in common at the material level.',k:'EYE',e:'L',i:3},
{c:'body',t:'Gas giants are not representable at all',n:['worldshader'],d:'The catalogue contains them and the renderer has a solid surface with a height field. A banded, differentially rotating fluid envelope with zonal jets, vortices and no surface is a completely different object.',k:'EYE',e:'L',i:3},
{c:'body',t:'Zonal bands with the right number of jets',n:['worldshader'],d:'The number of bands on a giant scales with rotation rate and radius through the Rhines scale, which `worldRecord` has the inputs for. Getting the count right is what makes Jupiter look like Jupiter and Neptune look like Neptune.',k:'SIM',e:'M',i:2},
{c:'body',t:'A long-lived vortex',n:['worldshader'],d:'The Great Red Spot is the single most recognisable feature on any planet other than Earth.',k:'EYE',e:'M',i:2},
{c:'body',t:'Rings',d:'Several catalogued bodies have them and there is no ring geometry anywhere. A ring needs a disc, a shadow cast onto the planet, a shadow received from the planet, and forward scattering when backlit — and it is one of the highest impact-per-line features available.',k:'EYE',e:'M',i:3},
{c:'body',t:'The ring shadow on the planet and the planet shadow on the ring',n:['terrshadow'],d:'The two shadows are what make a ringed planet read as a three-dimensional object rather than a decal.',k:'EYE',e:'M',i:2},
{c:'body',t:'Airless surfaces that look airless',n:['worldshader'],d:'`selene` is the same surface shader with `atmoStrength` low. An airless body has a knife-edge terminator, no aerial perspective, strong opposition brightening, and shadows that are absolutely black because there is no scattered light to fill them.',k:'EYE',e:'M',i:3},
{c:'body',t:'Regolith photometry, not Lambert',d:'The small-body shader added here uses Lommel-Seeliger, which is the right family. The full Hapke model adds a shadow-hiding opposition term and a macroscopic roughness term, and it is what makes a rendered moon match a photograph.',k:'SIM',e:'M',i:2},
{c:'body',t:'Crater rays',d:'Bright radial streaks from young craters are the most distinctive thing about a heavily cratered surface and they are also a direct read of relative age.',k:'EYE',e:'M',i:2},
{c:'body',t:'A cratering record that accumulates',d:'`selene` is a ruleset about impact history and the surface remembers none of it. Crater density by size is the clock that dates every surface in the solar system.',k:'SIM',e:'M',i:3},
{c:'body',t:'Maria: flood basalt that fills the low ground',d:'The dark plains of a moon are lava that ponded in impact basins. It is a two-step process the model has both halves of.',k:'SIM',e:'M',i:2},
{c:'body',t:'Ice shells rendered from the outside',d:'The three-layer stack is a cutaway diagram. What Europa looks like from orbit — a bright, nearly craterless plain criss-crossed by reddish double ridges and broken into chaos terrain — is a completely different picture.',k:'EYE',e:'M',i:3},
{c:'body',t:'Chaos terrain',d:'Blocks of crust rafted and refrozen. It is the visible evidence of an ocean beneath, which is the entire scientific interest of those moons.',k:'SIM',e:'L',i:2},
{c:'body',t:'Non-ice contaminants that give the ridges their colour',d:'Europa is reddish along its cracks because of salts and sulphur brought up from below. The colour is the evidence.',k:'SIM',e:'M',i:2},
{c:'body',t:'A hot rocky world with a magma ocean',d:'`exophysics.js` classifies lava worlds. The day side of one is molten and glowing and the night side is solid, and the boundary between them is a shoreline of rock.',k:'SIM',e:'M',i:3},
{c:'body',t:'Titan-class haze that hides the surface',d:'`uHaze` reddens the limb. A thick organic haze makes the surface invisible in the visible band entirely, which is a fact worth showing rather than approximating.',k:'SIM',e:'M',i:2},
{c:'body',t:'Venus-class: an opaque atmosphere with a hidden surface',d:'The strongest greenhouse in the solar system and the model can render it only as a warm Earth. Showing the cloud deck by default with a radar-style surface view as a toggle is exactly how the real observations work.',k:'EYE',e:'M',i:3},
{c:'body',t:'Mars-class polar caps of CO2',d:'A cap that sublimes into the atmosphere and back changes the surface pressure by 30% over a year. `ares` has the chemistry and not the cap.',k:'SIM',e:'M',i:2},
{c:'body',t:'Planet radius that is visibly different',d:'`worldRecord` carries `pl_rade` and the globe is always the same size on screen. Two planets side by side at true relative scale is the fastest way to convey what a super-Earth is.',k:'PLAY',e:'S',i:3},
{c:'body',t:'Surface gravity that shows in the terrain',d:'Low gravity means higher mountains, steeper slopes and deeper craters — Olympus Mons exists because Mars is small. The relief scale should come from gravity rather than from a per-ruleset constant.',k:'SIM',e:'M',i:2},
{c:'body',t:'Oblateness from rotation',d:'A fast rotator is visibly flattened. The lattice is a perfect sphere on every world and the rotation period is known for all of them.',k:'SIM',e:'S',i:2},
{c:'body',t:'Obliquity that shows in the seasons and the caps',d:'`W.obliquity` drives `sunY`. A world at 90 degrees has poles that alternately face the sun for half a year and its ice distribution is unrecognisable.',k:'SIM',e:'M',i:2},
{c:'body',t:'Eccentric orbits with a visible seasonal asymmetry',d:'`pl_orbeccen` is in the archive snapshot. A world at e=0.3 has a year with two very different halves.',k:'SIM',e:'M',i:2},
{c:'body',t:'The host star as an object in the sky',d:'`star.js` computes type, mass and luminosity and nothing is drawn. Standing on a world and seeing its actual sun, at its actual angular size and colour, is the payoff for the whole real-parameters programme.',k:'EYE',e:'M',i:3},
{c:'body',t:'Binary hosts',d:'The catalogue has them. Two suns, two shadows, and a day length that is not periodic.',k:'SIM',e:'M',i:2},
{c:'body',t:'Sibling planets visible in the sky',d:'`systemRecord.js` knows the system. In a compact system like TRAPPIST-1 the neighbours are resolved discs, which is the single most extraordinary fact about that system and is impossible to convey with a diagram.',k:'EYE',e:'M',i:3},
{c:'body',t:'A free-floating planet with no star',d:'The test suite already covers a free-floater with a null orbit. What that world looks like — lit only by its own interior heat and the galaxy — is a picture nobody has.',k:'EYE',e:'M',i:2},
{c:'body',t:'A world comparison view',d:'Two or three catalogued bodies side by side, same scale, same lighting, same overlay. The catalogue is a claim about diversity and there is no way to see the diversity.',k:'PLAY',e:'M',i:3},
{c:'body',t:'A visual honesty label per world',d:'`param-coverage.json` records which parameters are measured and which are assumed. The renderer should say, on the world itself, which parts of what you are looking at are measured, which are modelled and which are invented.',k:'PLAY',e:'M',i:3},
{c:'body',t:'A reference frame per world class in the image test',n:['imgtest'],d:'One rocky, one ocean, one ice, one airless, one giant. Five frames that fail loudly if a shader change breaks a class nobody was looking at.',k:'PLAY',e:'M',i:2},
/* --------------------------------------------------------------- instr -- */
{c:'instr',t:'Every overlay gets a legend with units',g:'legend',d:'`setOverlayMode` has more than twenty modes and each maps one scalar to one ramp with no scale, no units and no numbers. An overlay without a legend shows that something varies and not what it is.',k:'PLAY',e:'M',i:3},
{c:'instr',t:'Perceptually uniform, colour-blind-safe ramps',n:['legend'],d:'The ramps are hand-picked RGB stops. A rainbow ramp creates boundaries in the data that are not there and is unreadable to about one viewer in twelve.',k:'EYE',e:'S',i:3},
{c:'instr',t:'Diverging ramps for anomalies, sequential for magnitudes',n:['legend'],d:'Temperature anomaly and temperature need different ramps. Using a sequential ramp for a signed quantity hides the sign, which is the interesting part.',k:'EYE',e:'S',i:2},
{c:'instr',t:'A fixed scale option so two moments are comparable',n:['legend'],d:'Overlays autoscale, so a field that halves looks identical. Locking the scale is what turns an overlay into a measurement.',k:'PLAY',e:'S',i:3},
{c:'instr',t:'Direction shown as direction',n:['gpubasis'],d:'The `wind` and `upwell` overlays map speed and a scalar to colour. Neither shows which way anything is going, which is the only thing anybody wants to know about a fluid.',k:'EYE',e:'M',i:3},
{c:'instr',t:'A line integral convolution overlay',n:['gpubasis'],d:'LIC renders a vector field as directional smearing of noise. It is the single most readable way to show a flow field on a curved surface, it needs no particles, and it works at any zoom.',k:'EYE',e:'M',i:3},
{c:'instr',t:'Contours with labels',n:['legend'],d:'Isotherms, isobars and isohyets are how every weather map ever printed communicates a field, and they survive being printed in black and white.',k:'PLAY',e:'M',i:2},
{c:'instr',t:'Two overlays at once',n:['legend'],d:'Temperature as colour with pressure as contours is the standard synoptic combination and it says more than either alone.',k:'PLAY',e:'M',i:2},
{c:'instr',t:'A difference mode against another moment',d:'`serializeRun` exists. Comparing now against a bookmarked earlier state, cell by cell, is how you see what a god act actually did.',k:'PLAY',e:'M',i:3},
{c:'instr',t:'A difference mode against another world',d:'Same overlay, two bodies, one image. The catalogue is a comparison and there is no comparison tool.',k:'PLAY',e:'M',i:2},
{c:'instr',t:'A Hovmoller diagram',d:'Latitude on one axis, time on the other. It is how you see a signal propagate, and it is the instrument that would make ENSO legible.',k:'PLAY',e:'M',i:2},
{c:'instr',t:'A zonal mean profile beside the globe',d:'Any field averaged along latitude, plotted against latitude. It is the cheapest possible instrument and it immediately shows whether the circulation is producing the right structure.',k:'PLAY',e:'S',i:3},
{c:'instr',t:'A vertical section along a drawn great circle',d:'Shared with the relief category. Ocean temperature and salinity in section is the standard oceanographic figure and it is the only way to show the deep ocean at all.',k:'PLAY',e:'M',i:3},
{c:'instr',t:'A tide gauge trace at a chosen cell',d:'`tideHeight` is computed per cell per tick and there is nowhere to see it as a time series. A trace with the spring-neap envelope on it is the whole tidal system in one picture.',k:'PLAY',e:'S',i:2},
{c:'instr',t:'A hydrograph at a chosen river cell',d:'Discharge against time, with the storm that caused each peak marked. It is how a river is actually understood.',k:'PLAY',e:'S',i:2},
{c:'instr',t:'Time series for anything, by clicking it',d:'The instruments each read a scalar field at the present moment. Nothing in the build can show the same place twice.',k:'PLAY',e:'M',i:3},
{c:'instr',t:'An energy budget diagram',d:'In, out, reflected, absorbed, greenhouse, per component. It is the diagram that explains climate and the model computes every term in it.',k:'PLAY',e:'M',i:3},
{c:'instr',t:'A water budget diagram',d:'`assertBudgets` already checks water conservation every 32 ticks. Showing the reservoirs and the fluxes turns a test into a teaching tool.',k:'PLAY',e:'S',i:2},
{c:'instr',t:'A carbon budget diagram',d:'Same argument. The redox tower and the Keeling curve exist; the box model behind them is not drawn.',k:'PLAY',e:'M',i:2},
{c:'instr',t:'Attribution: what changed this, and when',d:'The god layer has receipts. Hovering any number should say which act, which feedback and which tick moved it.',k:'PLAY',e:'M',i:3},
{c:'instr',t:'Uncertainty shown, not implied',d:'`PURPOSE.md` says stated limits beat implied precision. Every instrument shows a crisp number. A band, a note, or a greyed-out region where the model is out of its range would honour the stated principle.',k:'PLAY',e:'M',i:3},
{c:'instr',t:'Say which overlay fields are diagnostic and which are prognostic',d:'`press` is recomputed from scratch every tick from temperature, elevation and ice; `temp` is integrated. An overlay that does not distinguish a state variable from a derived one teaches the wrong thing about what a model is.',k:'PLAY',e:'S',i:2},
{c:'instr',t:'A glossary link on every instrument',d:'`glossary.js` exists. Every term on every panel should reach it in one click.',k:'PLAY',e:'S',i:1},
{c:'instr',t:'Export every instrument as data, not only as PNG',d:'`exportPng.js` exports charts as images. CSV of the underlying series is what makes the thing usable as an instrument rather than an illustration.',k:'PLAY',e:'S',i:2},
{c:'instr',t:'Overlays in the local map too',d:'The globe has twenty and the patch has none. The patch is where a field can be shown at a scale where its structure is visible.',k:'PLAY',e:'M',i:3},
{c:'instr',t:'A cursor readout that is always on',d:'`patch.status` computes a dozen quantities and the strip under the map shows a compressed subset. A persistent readout of the cell under the cursor, on the globe as well as the map, is table stakes for an instrument.',k:'PLAY',e:'S',i:2},
{c:'instr',t:'Keyboard access to every overlay',d:'Twenty-odd modes reachable only by clicking chips in a drawer. Number keys and bracket cycling would make comparison fast enough to be a way of thinking.',k:'PLAY',e:'S',i:1},
{c:'instr',t:'A screenshot mode with the legend baked in',d:'The in-app screenshots in the README have no legend, so they cannot be read outside the app. A capture that includes scale, legend, seed and tick makes every screenshot self-documenting.',k:'PLAY',e:'S',i:2},
{c:'instr',t:'Print the seed and the tick on every frame in debug',d:'Reproducing anything visual starts with knowing which run it was.',k:'PLAY',e:'S',i:1},
{c:'instr',t:'An overlay conformance test',n:['imgtest'],d:'Every overlay rendered once against a fixed world, hashed. Twenty modes is twenty ways for a field change to break a picture nobody checks.',k:'PLAY',e:'M',i:2},
/* ---------------------------------------------------------------- perf -- */
{c:'perf',t:'Measure the cost of every pass',g:'gputime',d:'`EXT_disjoint_timer_query_webgl2` gives per-pass GPU time. Nothing in the renderer is measured, so every quality decision in this document is being made blind. This is the first item because it makes the rest arguable.',k:'PLAY',e:'M',i:3},
{c:'perf',t:'Detect a device tier and pick defaults from it',g:'tier',n:['gputime'],d:'`recommendGlobeSubd` scales one number by N. There is no notion of a phone, a laptop, a desktop or a standalone headset, and the difference in fill rate between the extremes is two orders of magnitude.',k:'PLAY',e:'M',i:3},
{c:'perf',t:'A frame budget with automatic quality fallback',n:['tier','gputime'],d:'When the frame time exceeds the budget, drop the detail octaves, then the cloud raymarch steps, then the globe subdivision, in a stated order, and say so in the debug overlay rather than silently.',k:'SIM',e:'M',i:3},
{c:'perf',t:'Expose the quality ladder to the user',n:['tier'],d:'`uGrain` was added in this pass and `GLOBE_SUBD` exists. Neither is in the UI. A three-step quality control with a description of what each step costs is more useful than any automatic heuristic.',k:'PLAY',e:'S',i:2},
{c:'perf',t:'Move refreshColours off the main thread',n:['gpucolour'],d:'A 320-line per-cell loop over 24,576 cells, called on every sim tick and again for interpolation. Until it moves to the GPU it should at least move to `worker.js`, which already exists.',k:'SIM',e:'M',i:2},
{c:'perf',t:'Cost out the detail noise',d:'`fbm3` is three octaves of trilinear value noise, eight `sin`-hash calls each, and the shader can evaluate it up to four times per fragment — the mid layer, the fine layer, the sea-ice pattern and the cloud break-up, plus one more for the sun-relief finite difference. That is up to 120 transcendental calls per pixel of planet at close range and nobody has measured it.',k:'SIM',e:'M',i:3},
{c:'perf',t:'Replace the sin-hash with an integer hash',d:'`fract(sin(dot(p, k)) * 43758.5453)` is the classic GLSL hash and it is both slow and precision-dependent — it produces visibly different patterns on different GPUs. An integer bit-mix hash is faster and identical everywhere.',k:'SIM',e:'S',i:3},
{c:'perf',t:'Precompute the noise into a texture',n:['gputime'],d:'A tiling 3D noise texture turns every fbm octave into a texture fetch. It costs memory and bandwidth instead of ALU, which is the right trade on most mobile GPUs and the wrong one on some desktops — which is why the measurement item comes first.',k:'SIM',e:'M',i:2},
{c:'perf',t:'Branch on the detail fade, do not just multiply',d:'The shader already guards `if (midFade > 0.004)`. Several other effects — the aurora, the storm flash, the moonlight, the intertidal band — compute their full cost and then multiply by zero.',k:'SIM',e:'S',i:2},
{c:'perf',t:'Cull the far hemisphere properly',d:'The planet is drawn as one indexed draw of the whole lattice with back-face culling. Half the vertices are transformed and discarded every frame; per-face frustum and horizon culling would halve the vertex cost.',k:'SIM',e:'M',i:2},
{c:'perf',t:'Instance the entity meshes',d:'`drawEntityMeshes` iterates and issues per-entity draws with per-entity uniforms. `ANGLE_instanced_arrays` semantics are core in WebGL2 and the entity data is already a flat array.',k:'SIM',e:'M',i:2},
{c:'perf',t:'Do not upload the flow streak buffer with bufferData every frame',d:'`gl.bufferData` reallocates. `bufferSubData` into a pre-sized buffer avoids a driver allocation 60 times a second.',k:'SIM',e:'S',i:1},
{c:'perf',t:'Batch the local rim, the grid and the streaks into one program',d:'Three separate `useProgram` and attribute rebinds for three line draws that share a shader and a matrix.',k:'SIM',e:'S',i:1},
{c:'perf',t:'Do not rebuild the cloud coverage array in JavaScript',n:['gpufield'],d:'`sampleFaceField` per vertex over a `6 x (N+1)^2` lattice every upload — at N=64 that is 25,350 bilinear samples on the CPU, and the field it is sampling is already on the GPU when the GPGPU path is active.',k:'SIM',e:'M',i:2},
{c:'perf',t:'Keep the local map off the render loop when it has not changed',d:'`drawLocalView` runs from the frame callback unconditionally. Most frames nothing in the patch has changed except the entity positions.',k:'SIM',e:'M',i:3},
{c:'perf',t:'A resolution scale for the canvas',d:'The canvas runs at device pixel ratio. On a 3x phone that is nine times the fragment cost of 1x for a picture nobody is inspecting at that density. A scale factor, with the option to render the globe at 0.75 and the UI at 1, is the standard fix.',k:'SIM',e:'S',i:3},
{c:'perf',t:'Temporal reprojection for the expensive layers',n:['hdrbuf'],d:'Clouds and detail noise change slowly relative to the camera. Rendering them at half rate and reprojecting with motion vectors halves their cost.',k:'SIM',e:'L',i:2},
{c:'perf',t:'A stable memory budget',d:'Three field atlases, a vertex colour array, positions, normals, a cloud mesh, a cell grid, a scatter LUT pair and an entity buffer, reallocated on every `setResolution`. Nothing tracks the total and nothing frees the old ones explicitly.',k:'SIM',e:'S',i:2},
{c:'perf',t:'Handle context loss without asking for a reload',d:'`webglcontextlost` shows a message telling the user to reload. On mobile a backgrounded tab loses context routinely and every state in the run is lost with it.',k:'PLAY',e:'M',i:3},
{c:'perf',t:'Precision qualifiers that are honest',d:'`F_HEAD` declares `precision highp float` for every fragment shader. On mobile GPUs `highp` is often half the throughput of `mediump`, and most of what these shaders compute — colour mixes, masks, fades — does not need it.',k:'SIM',e:'M',i:2},
{c:'perf',t:'Shader compilation off the critical path',d:'Eight programs compile synchronously in `initGL` before the first frame. `KHR_parallel_shader_compile` lets them compile concurrently and lets the app show something in the meantime.',k:'SIM',e:'S',i:2},
{c:'perf',t:'A first-frame budget',d:'`PURPOSE.md` says delight in the first ninety seconds beats feature count. Nothing measures how long it takes to get to the first frame, and the answer on a mid-range phone is the number that decides whether anyone sees any of this.',k:'PLAY',e:'M',i:3},
{c:'perf',t:'A visual regression harness that actually runs',g:'visreg',n:['imgtest'],d:'Headless WebGL2 in CI is genuinely awkward, which is why no project like this has visual tests. A software rasteriser via `swiftshader`, or a stored framebuffer hash from a real device run committed as the baseline, are both workable and both better than nothing.',k:'PLAY',e:'L',i:3},
{c:'perf',t:'Perceptual diffing, not exact pixels',n:['visreg'],d:'A tolerance in a perceptual colour space with a maximum fraction of changed pixels. Exact-match image tests fail on every driver update and get disabled within a month.',k:'PLAY',e:'M',i:2},
{c:'perf',t:'A performance regression test',n:['gputime'],d:'Frame time for a fixed scene on a fixed device, committed. Every item in this document adds cost and there is currently no way to notice.',k:'PLAY',e:'M',i:2},
{c:'perf',t:'A shader lint step',d:'`prog()` throws on a compile error at runtime, in the browser, on the user. Compiling every shader in CI through a validator catches the errors that only appear on one vendor.',k:'PLAY',e:'M',i:2},
{c:'perf',t:'Document the render order',d:'`drawScene` is 500 lines of sequential passes with state changes interleaved. A comment block at the top listing the passes, their blend modes and their depth behaviour would have made every compositing bug in this pass obvious on sight.',k:'PLAY',e:'S',i:3},
{c:'perf',t:'A debug overlay that shows all of it at once',n:['gputime'],d:'Frame time, per-pass GPU time, vertex count, draw calls, texture memory, active LOD, quality tier, seed, tick, and the detail fade values at the cursor. One key to toggle. Everything above is unarguable once it is on the screen.',k:'PLAY',e:'M',i:3},
];

const PASS2 = [
/* ------------------------------------------------------------- marble -- */
{c:'marble',t:'A true-colour Earth look, not a biome map',g:'bluemarble',d:'`landTerra` plus `lifeGreen` plus `uEarth * 0.82` is a diagram of climate belts. A Blue Marble is a photograph of materials: dark ocean, dark forest, pale desert, white ice, white cloud. Build one look-target that a still of the terra ruleset can be compared against, and stop treating the biome table as the picture.',k:'EYE',e:'L',i:3},
{c:'marble',t:'Stop using uEarth as a dimmer',n:['bluemarble'],d:'`pop = lifeGreen * (1.0 - uEarth * 0.65)` and `mix(..., lifeGreen * mix(0.58, 0.30, uEarth))` make Earth quieter than every other world. Quiet is not true. Drive Earth from materials and exposure; if the headset needs a lift, that is `uExposure`, not a flag that turns the biosphere down.',k:'EYE',e:'S',i:3},
{c:'marble',t:'Vegetation that is dark, the way a forest is dark',n:['bluemarble','truecolor'],d:'Conifer canopy albedo is about 0.08 and tropical forest about 0.12. `lifeGreen` tints toward a mid green that reads as grass from orbit. From DSCOVR the Amazon is nearly black, which is why cloud and river are visible against it. Darken the canopy and the planet gains contrast for free.',k:'EYE',e:'M',i:3},
{c:'marble',t:'Open ocean that is nearly black before the sky reflects',n:['bluemarble','watercol'],d:'`ocean(d) => [10+42d, 48+72d, 96+100d]` is a bright blue at every depth. Real open-ocean albedo is about 0.06; the blue is almost all sky. Paint the water dark and let Fresnel and the atmosphere do the colour, the way every satellite composite does.',k:'EYE',e:'M',i:3},
{c:'marble',t:'The Sahara–Amazon–Siberia triad',n:['bluemarble'],d:'Three patches make Earth instantly recognisable: a pale subtropical desert, a dark equatorial forest, a dark-green boreal belt that stops at a snow line. `seedEarthBiosphere` paints by `|lat|` and moisture, so the triad exists as climate and not as geography. The picture needs those three to sit in the right places at the right sizes, even on a generated continent.',k:'EYE',e:'M',i:3},
{c:'marble',t:'Deserts that are not one tan',n:['truecolor'],d:'`paintCellDetail` has a desert branch and the globe has a sand-ish land colour. Sahara is pale yellow, Australia is red, Gobi is grey-brown, Atacama is almost white. Rock type plus dust plus iron oxide is three numbers the geology already has, and they are the difference between a desert belt and a named desert.',k:'EYE',e:'M',i:2},
{c:'marble',t:'Ice that is the brightest thing, cloud that is the next',n:['bluemarble'],d:'On a true-colour Earth, nothing man-made outshines snow and nothing natural outshines thick cloud except snow. The current ice is `[230, 238, 248]` and the cloud shell is a translucent white, so they compete. Separate their brightness and the poles stop looking like overcast ocean.',k:'EYE',e:'S',i:3},
{c:'marble',t:'A land fraction you can see is 29 percent',d:'`fitSeaLevel` targets 0.29 and `calibrate.mjs` allows 0.22 to 0.38. From orbit the question is whether the eye agrees. If the continents read as half the disc, the hypsometry is lying even when the scalar passes.',k:'PLAY',e:'S',i:3},
{c:'marble',t:'Continents with cratons, not climate blobs',d:'`refineEarthHypsometry` adds `fbm` at 1.15 and a ridged craton term for `age > 400`. The result is lumpy land, not the shield-and-belt collage that makes Africa look like Africa. Carry craton identity as a field and let it show: low, old, red interiors with young mountains only at the edges.',k:'SIM',e:'L',i:3},
{c:'marble',t:'A recognisable Earth silhouette with no labels',n:['bluemarble'],d:'The test is: freeze a random camera, hide the UI, ask a person if it is Earth. Today the answer is "a planet". The silhouette of ice, desert and forest against a thin blue limb is the whole product in one still, and it is not passing.',k:'EYE',e:'M',i:3},
{c:'marble',t:'Island arcs as strings of dots',d:'Subduction already classifies a boundary. The Aleutians, Japan, Tonga are the most distinctive coastlines on Earth and they are one cell wide at N=64, which means they have to be drawn as a chain of highlights on the boundary, not as filled land. Without them the Pacific is a blank disc.',k:'EYE',e:'M',i:2},
{c:'marble',t:'The Himalaya as a white line, not a green cone',n:['material'],d:'Collision thickens crust in `generateTectonics` and never again, and `lifeGreen` paints whatever is cold-and-high the same as a meadow. A range that high is snow, rock and a rain shadow, and it is a line, not a blob. Strike from the plate velocity; snow from the lapse rate.',k:'EYE',e:'M',i:3},
{c:'marble',t:'Continental shelves that read as turquoise',n:['watercol'],d:'`refreshColours` already has a shallow-depth path and a sediment mix. The Bahamas, the Arafura and the Siberian shelf are the brightest water on Earth and they are how you read bathymetry from a photograph. Gate the turquoise on depth, sand and low chlorophyll, not on a single depth lerp.',k:'EYE',e:'M',i:3},
{c:'marble',t:'Western boundary currents as colour, not streaks',n:['gpubasis'],d:'The Gulf Stream, Kuroshio and Agulhas are visible in true colour as a temperature and turbidity front. The globe draws 1600 one-frame line segments. A warm, slightly green ribbon hugging the western edge of a basin is the photograph of a gyre, and it needs no overlay.',k:'EYE',e:'M',i:3},
{c:'marble',t:'An ITCZ that is a broken chain, not a white band',d:'`cloudsTick` adds `itczBand * moist * 0.55` as a Gaussian in latitude. DSCOVR shows a dashed line of convective clusters with holes you can see the ocean through. Break the band with the same convective-type field the cloud shell already uses for lift.',k:'EYE',e:'M',i:3},
{c:'marble',t:'Sunglint as a path, not a blob',d:'The GGX lobe is in. From orbit the glint is a long glitter path along the equator of the illumination, broken by swell and cloud. Shape it with the wind-roughness already driving the lobe and it becomes a photograph of sea state.',k:'EYE',e:'M',i:2},
{c:'marble',t:'Cyclones as the most recognisable object on Earth',d:'`storms.js` paints into `clouds` and `precip` after `cloudsTick`, so a named cyclone is overwritten the next tick. A Blue Marble without an eye-and-bands storm is missing the one weather object a child can name from space.',k:'SIM',e:'M',i:3},
{c:'marble',t:'The terminator as orange, then blue, then black',n:['limbvol'],d:'`term = smoothstep(-0.18 - uAerosol * 0.25, 0.22 + uAtmoK * 0.12, nl)` is a brightness ramp. A real Earth terminator is a colour sequence: land goes gold, sky goes Chappuis-blue, then the night is city-lights and airglow. That sequence is how you know the air is Earth air.',k:'EYE',e:'M',i:3},
{c:'marble',t:'No neon, no lime, no toy ocean',n:['bluemarble'],d:'Guild tints, bloom lerps and `oceanLifeRGB` all push toward saturated greens and cyans that read as a game. Cap chroma against a measured Earth gamut — even a loose one from a Blue Marble JPEG — and the palette stops advertising itself.',k:'EYE',e:'S',i:3},
{c:'marble',t:'Cloud fraction 0.67 that also looks like 0.67',d:'A comment in `cloudsTick` cites 0.67 and there is no assertion. Hitting the number with a uniform haze still looks like a snowball. The photograph is: clear deserts, broken trades, solid storm tracks, empty poles in winter. Distribution is the look; the mean is the check.',k:'SIM',e:'M',i:3},
{c:'marble',t:'Polar night as a place, not a dimmer',d:'Winter high latitudes on Earth are dark for months. `uNight` is a function of `nl`, so a pole at solstice is only as dark as the terminator math. A real polar winter is a black disc with aurora and a faint ice sheen, and it is how you read the date from orbit.',k:'EYE',e:'S',i:2},
{c:'marble',t:'Earthshine on the moon from this Earth, this phase',d:'The moon shader has a constant 0.055 floor. Mean Earth albedo is 0.306 and it changes with cloud and ice. A full Earth in the lunar sky is several times brighter than a cloud-free one, and the moon is the only place the player can see that number as light.',k:'SIM',e:'S',i:2},
{c:'marble',t:'Bond albedo 0.306 as a rendered quantity',d:'`worldRecord` and calibrate know the number. Integrate the framed image — or the atlas — and print Bond albedo live. If the picture is too bright, this is how you find out, and it is also the number SimEarth put on a gauge.',k:'PLAY',e:'M',i:3},
{c:'marble',t:'A still that can sit next to NASA Blue Marble 2002',n:['eoref'],d:'Same geometry: Africa and Arabia centred, 0° sun azimuth, cloud as photographed that day or as a typical field. The gap between the two stills is the backlog. Keep both in `briefs/` and update the render when the look changes.',k:'PLAY',e:'M',i:3},
{c:'marble',t:'The pale blue dot at orrery distance',n:['holdfeel'],d:'From the table the planet is a bright marble. From a few metres of simulated distance it should collapse toward a pale disc with a blue hint — Sagan scale — because that is what Earth is when you stop filling the frame. Exposure and the limb have to survive that shrink.',k:'EYE',e:'M',i:2},
{c:'marble',t:'A generated Earth that is still obviously Earth-class',d:'Deep-time and random seeds will never produce our coastlines. They must still produce the class: bimodal hypsometry, desert belts, polar ice, a dark wet tropics, white storm tracks. A class-resemblance test against a library of Earth stills is the honest substitute for a coastline lock.',k:'PLAY',e:'M',i:3},
{c:'marble',t:'Lock a modern-Earth coastline mode as an option',d:'`earthTerrain.js` shapes hypsometry; it does not reconstruct the actual continents. A seeded "this is Earth, 2026" mode with a low-resolution continent mask — even at N=64 — is the calibration planet the rest of the catalogue borrows credibility from. SimEarth had a Earth map; the modern one should too, and it should be clearly labelled as a reconstruction.',k:'SIM',e:'L',i:3},
{c:'marble',t:'Match the phase: a DSCOVR-class full disc',n:['eoref'],d:'EPIC at L1 sees the full dayside. The prototype camera is a three-quarter studio light. Add a "full disc, sun behind camera" preset so the stills people compare against are the stills we actually produce.',k:'PLAY',e:'S',i:2},
{c:'marble',t:'Name the look in the View tab',d:'True colour, vegetation-boosted, and biome-diagram are three different pictures and the player cannot tell which they are in. SimEarth was honest about being a diagram. A toggle that says "photograph" versus "diagram" is the difference between a teaching tool and a muddle.',k:'PLAY',e:'S',i:3},
{c:'marble',t:'A cloud-free Earth as a materials exam',n:['bluemarble'],d:'Turn weather off and the disc should still be Earth: dark forest, pale desert, indigo gyre, white ice. If it only looks right with cloud covering the mistakes, the photograph is a costume.',k:'EYE',e:'M',i:3},
/* --------------------------------------------------------------- limb -- */
{c:'limb',t:'A volume with a scale height, not a glow on a sphere',g:'limbvol',d:'The atmosphere shell is displaced coverage plus an analytic rim in `planetProg` / `atmoProg`. Real Earth air is an exponential with H about 8.5 km — `scatter.js` already takes `scaleHeight: 8500`. March the shell through that exponential so the limb is a thin bright line and the disc has air in front of it, not a halo.',k:'EYE',e:'L',i:3},
{c:'limb',t:'The limb thickness must match radius',n:['limbvol'],d:'At relief 0.028 the air is thicker than Everest. Scale height over radius is 8.5 / 6371, about 0.0013. The shell radius and the rim falloff both have to come from that ratio or every other world inherits an Earth halo at the wrong size.',k:'SIM',e:'S',i:3},
{c:'limb',t:'Use the transmittance LUT for the view path, not only muV',n:['limbvol'],d:'`buildTransmittanceLUT` is 32x32 in view-zenith and sun-zenith. The surface samples it for the ground; the limb mostly ignores it. Sample along the actual view ray through the shell and the blue line becomes a calculation instead of a mix.',k:'SIM',e:'M',i:3},
{c:'limb',t:'Multiple scattering that fills the disc, not just the edge',n:['limbvol'],d:'`MS * uAtmoK * (0.08 + 0.12 * wrap)` is a grey fill. Bruneton-style multiple scattering is why the Earth disc is pale blue even in the centre, and why a photograph does not look like a black planet with a glowing ring.',k:'EYE',e:'M',i:3},
{c:'limb',t:'Ozone as a Chappuis ring, not a mix toward navy',n:['limbvol'],d:'`atmoCol = mix(uAtmo, vec3(0.06, 0.14, 0.62), uOzone * 0.65)` tints everything. The deep blue lives in a narrow slant-path ring just past the terminator. Put it there and the rest of the sky can stay Rayleigh.',k:'SIM',e:'M',i:2},
{c:'limb',t:'Mie forward scatter as a white sunward core',n:['limbvol'],d:'The Mie term is `vec3(1.0,0.82,0.55) * sunEdge * rim`. On a hazy Earth day the sunward limb goes milky, not orange, because aerosol scatters forward. Drive it from `uAerosol` with a real Henyey–Greenstein `MIE_G` of 0.76, which is already a constant in `scatter.js`.',k:'EYE',e:'S',i:2},
{c:'limb',t:'Aerosol from volcanoes and cities as a local optical depth',n:['limbvol'],d:'`uAerosol` is one scalar. A Pinatubo year and a clean preindustrial year are different photographs; so is a megacity plume off China. Carry optical depth as a field and the limb can go brown in one sector without dirtying the whole planet.',k:'SIM',e:'M',i:2},
{c:'limb',t:'The night limb is airglow, not leftover day',n:['limbvol'],d:'`airglow = night * rim2 * (0.3 + uOzone * 0.5)` washes the whole night edge. ISS photographs show a thin green line at about 90 km and a redder line above it. Two thin shells, two colours, and the night Earth stops looking like a dim day Earth.',k:'EYE',e:'M',i:3},
{c:'limb',t:'Stars extinguished through the air, not clipped by a disc',n:['limbvol'],d:'The starfield is drawn before the planet with depth write off. A setting star goes orange, then dies in the limb, then is gone. That sequence is how you feel the air has thickness.',k:'EYE',e:'S',i:2},
{c:'limb',t:'Cloud sitting inside the air, not on top of it',n:['limbvol','cloudtop'],d:'The cloud shell is a separate mesh with its own blend. Edge-on, real cloud is embedded in the blue line: anvils poke out, stratus sits in the well-mixed layer. Parent the cloud volume to the same exponential so a storm has a height in the limb profile.',k:'EYE',e:'M',i:3},
{c:'limb',t:'A crescent Earth with a luminous limb',n:['limbvol'],d:'From the moon, or from a high orrery camera past terminator, Earth is a crescent with a faint back-scattered limb all the way around. That ring is the single most Earth-like thing a crescent can do, and the current terminator math blacks it out.',k:'EYE',e:'M',i:2},
{c:'limb',t:'Rayleigh that is actually lambda^-4',n:['limbvol'],d:'`RAYLEIGH = [5.8e-6, 13.5e-6, 33.1e-6]` is in `scatter.js` and the planet shader uses a hand-tuned `uAtmo`. Use the coefficients. An M-dwarf Earth then gets a different sky for free, which is the point of carrying `st_teff`.',k:'SIM',e:'M',i:3},
{c:'limb',t:'The sky from the ground must match the limb from orbit',n:['limbvol','groundcam'],d:'One atmosphere, two views. If the ground sky is `#2a6a8a` and the orbit limb is a different blue, neither is Earth. Share the LUT; the local map sky is a lookup at muV = 0 and the current sun.',k:'EYE',e:'M',i:3},
{c:'limb',t:'Twilight lasting the right number of degrees',n:['limbvol'],d:'Civil twilight is 6° of solar depression; astronomical is 18°. The smoothstep terminator is a visual guess. Drive twilight from optical depth along the sun path so a thick atmosphere holds dusk and an airless body does not.',k:'SIM',e:'S',i:2},
{c:'limb',t:'Specular Earth as a pale marble in a dark sky',n:['limbvol'],d:'Out of the atmosphere looking back, the disc is bright and the sky is black. Inside the atmosphere looking up, the sky is bright and the ground is darker. The two exposures are different and `uExposure` is one number. A view-path optical depth should pick the exposure, or the orrery and the walk-in can never both be right.',k:'EYE',e:'M',i:3},
{c:'limb',t:'No fat blown ring on the sunward limb',d:'The first pass tonemapped the shell; the sunward limb can still clip where Mie and the disc add. Pre-expose the shell against the same HDR target as the surface so the famous blue line cannot go white.',k:'EYE',e:'S',i:3},
{c:'limb',t:'A measured limb width in the debug overlay',n:['limbvol'],d:'Print scale height, shell radius in km, and the on-screen width of the 50-percent limb in pixels. When someone thickens the halo to make it "pop", the number argues back.',k:'PLAY',e:'S',i:2},
{c:'limb',t:'Compare the limb against a DSCOVR edge crop',n:['eoref'],d:'A 64-pixel crop of the actual Earth limb is a better spec than any paragraph. Store one, render one, diff the blue.',k:'PLAY',e:'M',i:2},
{c:'limb',t:'Dipole aurora that respects the limb altitude',d:'The oval is drawn on the surface shader and again on the shell with different constants. Real aurora is at 100–250 km, above the weather, inside the airglow. One height, one oval, two views.',k:'EYE',e:'S',i:2},
{c:'limb',t:'Crepuscular rays that start in the limb',n:['limbvol'],d:'`crep` is a colour with no rays. When the cloud shell is edge-on at terminator, shafts should originate in the limb gaps and fall onto the disc. That is the photograph people mean by "Earth from space at dusk".',k:'EYE',e:'M',i:2},
{c:'limb',t:'A hazy world must hide its own limb structure',n:['limbvol'],d:'Venus and Titan are in the catalogue. If the same limb code that makes Earth a thin blue line also makes Venus a thin blue line, the code is a decal. Optical depth of tens should turn the limb into an opaque cream crescent.',k:'SIM',e:'M',i:3},
{c:'limb',t:'Rain shafts visible in the limb of a storm',n:['limbvol'],d:'Edge-on convective towers show a dark core and a bright anvil. That silhouette is how you read weather from a million kilometres, and it needs cloud top, cloud base and a density that is not a hash.',k:'EYE',e:'M',i:2},
{c:'limb',t:'The atmosphere has a colour temperature from the host',n:['limbvol'],d:'`skyFromStarAtmosphere` exists and the globe uses `R.atmo`. Wire it. A G2 Earth is blue; the same air under 2566 K is not; that is the TRAPPIST-1 teaching moment hiding in a helper nobody calls from the shader.',k:'SIM',e:'S',i:3},
{c:'limb',t:'Document the limb as a teaching overlay',n:['limbvol'],d:'A mode that labels Rayleigh, Mie, ozone, airglow and cloud in the limb stack — mute, not rainbow — turns the most beautiful pixel in the product into a lesson. SimEarth would have put this on a button called Atmosphere.',k:'PLAY',e:'M',i:2},
{c:'limb',t:'Keep the limb stable under camera roll',n:['limbvol'],d:'Analytic rims keyed to `N.y` or view-space hacks swim when the camera banks. Object-space height and a true view-ray optical depth do not. XR will bank constantly.',k:'EYE',e:'S',i:2},
{c:'limb',t:'A first-frame limb that is already thin',d:'Before LUTs upload, the shell should not flash a fat halo. Either block the first present until `scatter.js` is resident, or start with a conservative exponential that is already Earth-thin.',k:'PLAY',e:'S',i:1},
{c:'limb',t:'Limb darkening of the disc from air, not from a fake',n:['limbvol'],d:'The planet disc is slightly darker at the edge because you look through more air at the surface. That is not the same as stellar limb darkening and it is not `pow(nl, 1.15)`. It falls out of the view-path transmittance.',k:'EYE',e:'S',i:2},
{c:'limb',t:'The blue line must survive a thumbnail',n:['limbvol'],d:'At orrery distance the atmosphere is a few pixels. If those pixels go white or vanish, Earth is a rock. Bias the last pixel of the disc toward Rayleigh even when the shell is sub-pixel. This is the pale-blue-dot contract.',k:'EYE',e:'M',i:3},
{c:'limb',t:'No second atmosphere from the bloom pass',n:['limbvol','hdrbuf'],d:'Bloom on the HDR target will halo the limb and fake a fatter air. Gate bloom by luminance of sun glint and lights, not of the Rayleigh ring, or the thin line becomes a glow again.',k:'EYE',e:'S',i:2},
/* -------------------------------------------------------------- coast -- */
{c:'coast',t:'A coastline that is fractal below the cell',g:'coastline',d:'At N=64 a cell is 157 km; at N=96 it is 104 km. Every real coast is rough at 10 km, 1 km and 100 m. Domain-warp the land/sea mask in the shader with object-space noise faded by `fwidth`, and the contour stops looking like a province border.',k:'EYE',e:'M',i:3},
{c:'coast',t:'Asymmetric strand: wet sand landward, surf seaward',n:['coastline','gpubasis'],d:'The ochre intertidal is `smoothstep` on `heightF`, symmetric about sea level. A real strand is wet and dark on the land side, white and moving on the water side. The height gradient already points which way is up the beach.',k:'EYE',e:'M',i:3},
{c:'coast',t:'Beaches only with sediment and wave energy',n:['coastline'],d:'Cliffed coasts have no beach. `W.sediment` and `W.waveHt` exist; paint ochre only where both exceed a threshold and the slope is gentle. The rest is rock meeting water, which is a different photograph.',k:'SIM',e:'M',i:3},
{c:'coast',t:'Estuaries where rivers meet tide',n:['coastline'],d:'`computeRivers` and `tideHeight` never meet in the picture. A drowned river valley is the most common temperate coast and it is a branched water surface, not a cell of ocean. Where discharge crosses the tide line, widen the water inland.',k:'SIM',e:'M',i:2},
{c:'coast',t:'Deltas as bright fans, not a mouth cell',n:['coastline'],d:'One downhill neighbour cannot split. Fake the photograph anyway: where a large `flow` meets the sea on a low slope, fan sediment into the two shoreward neighbours. The Nile and the Mississippi are how you read a continent from orbit.',k:'SIM',e:'M',i:3},
{c:'coast',t:'Fjords after ice',n:['coastline'],d:'A U-valley drowned by sea level is a fjord: steep, deep, branching. If the cell remembers maximum ice, the coast can keep that shape after the ice leaves. Norway is a climate history, not a noise type.',k:'SIM',e:'L',i:2},
{c:'coast',t:'Barrier islands and lagoons',n:['coastline'],d:'A low sandy coast with moderate wave energy grows a bar and a quiet lagoon. At this resolution it is a one-pixel bright line and a darker strip behind it — cheap, and instantly Atlantic-coast.',k:'EYE',e:'M',i:2},
{c:'coast',t:'Mangrove and salt marsh instead of universal mud',d:'`W.intertidal` is bare ochre. Warm wet coasts are green to the waterline; temperate ones are grass; arctic ones are mud and ice. Temperature and NPP already decide, and the vegetated intertidal is a carbon sink the redox tower claims to model.',k:'SIM',e:'M',i:2},
{c:'coast',t:'A tide that moves the waterline against the presentation clock',n:['coastline'],d:'`localSeaLevel` adds `tideHeight` and the globe does not follow it between ticks. Twice a day the strand should breathe. This is the payoff of `coast.js` existing at all.',k:'EYE',e:'M',i:3},
{c:'coast',t:'Spring–neap as a visible envelope',d:'`W.tidePhase === "springs"` already feeds `coastDeskSnapshot`. The player should see a wider wet band at springs without opening a panel. A faint high-water stain that updates on the fortnightly cycle is enough.',k:'EYE',e:'S',i:2},
{c:'coast',t:'Surf as a white line that knows the shelf',n:['swell','coastline'],d:'A steep shelf pounds; a wide shelf dissipates. Bathymetry is `sea - h`. Brightness of the surf line is the cheapest readable bathymetry overlay that still looks like a photograph.',k:'EYE',e:'M',i:3},
{c:'coast',t:'Sea fog on cold eastern-boundary coasts',d:'California, Peru, Namibia: cold current, warm air, a white blanket that hugs the water and burns off inland. Two fields and a threshold, and the desert-next-to-ocean photograph suddenly makes sense.',k:'SIM',e:'M',i:2},
{c:'coast',t:'Rias and drowned valleys when sea level rises',d:'`updateSeaLevel` moves `seaLevel` from ice and thermal. The coast should keep its last few shorelines as terraces and flooded valleys, not jump. That is how you see a meltwater pulse instead of reading it.',k:'SIM',e:'M',i:2},
{c:'coast',t:'Harbours as a coastal landform, not a flag',d:'`coast.js` counts `x.harbour`. A harbour is a shape: a sheltered bight with a settlement on the slope. Draw the bight from local coastline curvature and the city reads as a port rather than a grey pixel that happens to be wet.',k:'EYE',e:'M',i:1},
{c:'coast',t:'Surge as dirty water over the flats',d:'`W.surgeField` tints storm cells. A real surge is the sea in the streets: brown water, a new shoreline, a receding stain. Paint it on land cells that are normally dry, and `floodScore` becomes a picture.',k:'EYE',e:'M',i:2},
{c:'coast',t:'Coral reefs as a turquoise structure, not a tint',d:'`W.reef` lerps water toward a guild colour. A reef is a shallow ring or ribbon with a lagoon, breaking swell on the outside. Structure first, colour second, bleach as a later event.',k:'SIM',e:'M',i:3},
{c:'coast',t:'Sea ice that has a coast of its own',n:['icethick'],d:'The ice edge is a second coastline, and in winter it is longer than the land one. It should be a sharp, lead-broken margin, not a smoothstep of `iceF`. That edge is the Arctic photograph.',k:'EYE',e:'M',i:3},
{c:'coast',t:'Match the cube-sphere coast to the pixel-map coast',n:['coastline'],d:'The globe bilinearly samples height; the map tests `h < seaLevel` per cell. The same bay is a smooth curve in one panel and a staircase in the other. Share `isSubmerged` at a sub-cell sample or the pairing is two planets.',k:'EYE',e:'M',i:3},
{c:'coast',t:'Coastline length as an instrument',d:'Fractal dimension and length at a stated scale. When the noise amplitude changes, this number moves. It is also a teaching hook: Norway versus Australia, same grid, different roughness.',k:'PLAY',e:'S',i:1},
{c:'coast',t:'A shelf break you can see',d:'The step from 0–200 m to the abyss is the other coastline, underwater. With extinction colour it becomes a hue step a few cells offshore. Without it the ocean is a flat fill to the horizon.',k:'EYE',e:'S',i:2},
{c:'coast',t:'Tidal flats that flood and drain in the local map',n:['coastline'],d:'`paintCoast` draws an edge. The map is where twice-daily water is actually watchable: mud, sheen, birds, then water. `W.tideWet` is already computed per cell.',k:'EYE',e:'M',i:3},
{c:'coast',t:'Hold the last high-water mark',d:'A dark wrack line above the current wet is how a beach shows a spring tide after it has gone. One extra threshold on recent `tideHeight` max, decaying over days of presentation time.',k:'EYE',e:'S',i:1},
{c:'coast',t:'Cliffs on the silhouette of a steep coast',n:['lodmesh'],d:'The 0.028 relief cap and the 60% neighbour blend forbid a vertical face. At walk-in distance a cliff is the scale cue; from orbit it is a hard shadow line. Allow a coastal slope cap that is steeper than interior terrain.',k:'EYE',e:'L',i:2},
{c:'coast',t:'Inlet noise that does not swim as the planet turns',n:['coastline'],d:'If the fractal coast is hashed from world-space, it will crawl like the old ice did. Object space, same as the grain pass, or the most watched edge in the picture will betray the grid.',k:'EYE',e:'S',i:3},
{c:'coast',t:'River mouths that stain the sea',n:['coastline'],d:'The sediment plume is a CPU colour lerp at the mouth cell. It should be a comma pointing down-current, paler and browner than the sea, visible from orbit the way the Amazon is visible from orbit.',k:'SIM',e:'M',i:3},
{c:'coast',t:'A coast desk that is a picture, not a paragraph',d:'`coastDeskSnapshot` returns percents and a note. Show the wet band, the range, the drowned camps on the globe. The panel can keep the numbers; the planet has to carry the meaning.',k:'PLAY',e:'M',i:2},
{c:'coast',t:'Calibrate coastline against a real Earth mask',n:['eoref'],d:'Even a 1-degree land mask, reconstructed onto the cube sphere, gives a target length, a target island count and a target shelf area. `fitSeaLevel` would then have something to fit besides 0.29.',k:'PLAY',e:'M',i:2},
{c:'coast',t:'Let the player sculpt a coast and see the photograph change',d:'Raise/Lower already edits height. The consequence should be an immediate new strand, new surf, new estuary — not a vertex colour shift five ticks later. Coast is the god-game gesture that most looks like Earth-making.',k:'PLAY',e:'S',i:2},
/* ------------------------------------------------------------- season -- */
{c:'season',t:'A green wave that actually travels',g:'phenology',n:['lai'],d:'Northern leaf-out runs from the subtropics to the tundra over about ten weeks. `W.season` and `npp` exist; the shader multiplies them and the wave never moves. Delay NPP by latitude and you get the most alive orbit video Earth produces.',k:'EYE',e:'M',i:3},
{c:'season',t:'Autumn colour as a latitude front',n:['phenology'],d:'`tempDeciduous` is a biome label. For four weeks it should go yellow then bare, sweeping south in the north and north in the south. One ramp keyed to first frost, visible from orbit as a moving band.',k:'EYE',e:'S',i:3},
{c:'season',t:'A snow line that walks up and down mountains',n:['phenology'],d:'Seasonal snow is the largest albedo change on Earth. Separate it from `W.ice` and let the white contour follow `temp - lapse * elevation` as the year turns. A still of July versus January should be two planets.',k:'SIM',e:'M',i:3},
{c:'season',t:'Sea ice that grows and dies on a calendar',n:['phenology','icethick'],d:'Arctic minimum in September, Antarctic in February. `seedPolarIce` paints caps and `iceTick` floors them so they cannot disappear. Let them breathe. The pulse is how you read the poles from a year of stills.',k:'SIM',e:'M',i:3},
{c:'season',t:'The ITCZ following the sun',n:['phenology'],d:'The real ITCZ lags insolation by weeks and does not cross the equator evenly — it sits north, pinned by land. A Gaussian on `lat - itcz` is a start only if `itcz` moves and if land heat can hold it. That motion is the tropical year.',k:'SIM',e:'M',i:3},
{c:'season',t:'Monsoon cloud as a switch, not a constant',n:['phenology'],d:'`W._monsoon = W._monsoon ?? 0.5` never changes. India and West Africa go from brown to green in a month under a new cloud deck. Moisture convergence plus a seasonal wind reversal is the picture; the tipping element is the name.',k:'SIM',e:'M',i:3},
{c:'season',t:'Keeling, but as a colour of the land',n:['phenology'],d:'The Keeling sawtooth is drawn in Lab. The cause is the northern biosphere inhaling. If the green wave is visible, the CO2 trace is a caption, not a miracle. Show both, same clock.',k:'PLAY',e:'S',i:2},
{c:'season',t:'A year of stills as a product feature',n:['phenology'],d:'Twelve frames, same camera, one per month. This is how NASA proves phenology and it is how we prove the season code. Export it from finale; hang it in the README.',k:'PLAY',e:'M',i:3},
{c:'season',t:'Obliquity that you can see in the caps',n:['phenology'],d:'`W.obliquity` drives `sunY`. At 23.44° the Arctic melts; at 0° it does not; at 90° the poles take turns frying. Three stills, one slider, the SimEarth tilt lever finally paid off in a photograph.',k:'SIM',e:'M',i:3},
{c:'season',t:'Day length on the ground matching the orbit sky',n:['phenology','groundcam'],d:'A June night in the map at 60°N should be short and blue. `dayPhase` exists; polar summer does not. When the player walks in, the year has to still be the year.',k:'EYE',e:'M',i:2},
{c:'season',t:'Harvest and senescence in the human layer',n:['phenology'],d:'Cropland that is green in May and gold in August is the Anthropocene phenology. `W.build` does not farm. A seasonal crop tint around settlements is the cheapest civilisation-is-alive cue from orbit.',k:'EYE',e:'S',i:2},
{c:'season',t:'Melt ponds in June, freeze-up in October',n:['phenology'],d:'Summer sea ice is a blue mosaic; autumn ice is grey and growing. The calendar is the texture. Do not use the same floe fBm all year.',k:'EYE',e:'M',i:2},
{c:'season',t:'A storm track that shifts with the jet',n:['phenology'],d:'Mid-latitude cloud is a comma train under the jet, and the jet moves with the season. Without that shift, January and July are the same weather map in different light.',k:'SIM',e:'L',i:2},
{c:'season',t:'Dust in the dry season, green in the wet',n:['phenology'],d:'Sahel and northern Australia: a brown plume off the land half the year, a flush the other half. `W.ash` and lofted dust should respect a moisture calendar, not only volcanoes.',k:'SIM',e:'M',i:1},
{c:'season',t:'Phytoplankton spring bloom',n:['phenology'],d:'The North Atlantic goes jade in April along the ice edge and the shelf. NPP already has a temperature and light response; let it overshoot in spring instead of sitting at a mean. That bloom is the ocean equivalent of leaf-out.',k:'SIM',e:'M',i:2},
{c:'season',t:'The presentation year versus the sim year',n:['phenology','globeclock'],d:'`dtYr` can be 10 kyr. Seasons then smear into a mean and the photograph dies. Bind phenology to `presentTime` modulo the orbital period when the sim is in deep time, and to `W.season` when it is in Holocene. Declare which clock on the overlay.',k:'SIM',e:'M',i:3},
{c:'season',t:'A season scrubber on the Holocene strip',n:['phenology'],d:'The ICS ribbon jumps epochs. Inside an epoch, a month slider is the missing gesture. Scrub January to July and watch the cap shrink. That is the teaching.',k:'PLAY',e:'S',i:3},
{c:'season',t:'Calibrate month-by-month ice and NDVI',n:['phenology','earthcal'],d:'`calibrate.mjs` has one iceFrac band. Add monthly sea-ice extent and a coarse NDVI by latitude. A year that cannot reproduce the pulse is not modern Earth, even if the means pass.',k:'PLAY',e:'M',i:3},
{c:'season',t:'First frost as an event on the map',n:['phenology'],d:'One night the stamps go rime and the deciduous colour ticks. `chronicle.js` can log it. A person standing in the patch should notice winter arriving, not read it off a gauge.',k:'PLAY',e:'S',i:1},
{c:'season',t:'The antiphase of the two hemispheres',n:['phenology'],d:'When the north is green the south is brown, and the Keeling curve knows which hemisphere has more land. If both hemispheres green together, the season code is a global tint and not a planet.',k:'SIM',e:'S',i:3},
{c:'season',t:'Lake ice-on and ice-off',n:['phenology'],d:'`lake[c] = 1` never freezes. Temperate lakes going white in November and black in April are a local-map seasonal cue with a well-known date, which makes them a calibration gift.',k:'SIM',e:'S',i:1},
{c:'season',t:'A "year in 12 seconds" time-lapse mode',n:['phenology'],d:'NASA does this for every Earth-observing satellite. One key, twelve seconds, the green wave and the ice pulse. It is the demo that sells the modern SimEarth in a tweet.',k:'PLAY',e:'M',i:3},
{c:'season',t:'Perennial versus seasonal biomes drawn differently',n:['phenology'],d:'Rainforest should barely change; savanna should flip; tundra should almost vanish in winter. Right now NPP scales all of them the same way, so the tropics flicker and the taiga does not sleep.',k:'EYE',e:'S',i:2},
{c:'season',t:'Earth at solstice as two reference frames',n:['imgtest','phenology'],d:'June and December, same seed, same camera. If a shader change kills the cap asymmetry, the test fails. Half the planet is a season.',k:'PLAY',e:'S',i:2},
{c:'season',t:'Let tilt and orbit rewrite the calendar live',n:['phenology'],d:'God-layer tilt and eccentricity already exist as levers. The year picture has to reorganise the same day: longer polar night, stronger perihelion summer, a monsoon that jumps hemisphere. Otherwise the levers are numbers.',k:'SIM',e:'M',i:3},
{c:'season',t:'A legend that says what month it is',n:['phenology'],d:'The globe implies a date and prints a year. Print the month, the solar longitude, and which pole is in night. People read Earth by the date without noticing they do.',k:'PLAY',e:'S',i:2},
{c:'season',t:'Fire season as a second pulse',n:['phenology'],d:'Africa and Australia light up on a calendar that is not the green wave. If night fires exist, they should peak in the dry months. A year of stills with a July Africa that is dark is the wrong planet.',k:'EYE',e:'M',i:2},
{c:'season',t:'The subsolar point as a moving highlight',n:['phenology'],d:'A faint warm disc of illumination walking the tropics is how you read the date from a full-disc still without a caption. `uSun` already has the direction; show it as a soft hot spot on cloud and sea, not as a studio key light from the side.',k:'EYE',e:'S',i:2},
/* ------------------------------------------------------------- anthro -- */
{c:'anthro',t:'City lights that follow coasts, rivers and roads',g:'lights',d:'`vD.b` standing in for build is a random scatter of warm pixels. VIIRS night is a map of infrastructure: coasts, valleys, a dark interior. Place lights from `city.js` plus `W.build`, then along least-cost paths between them, or the night side will never look like a civilisation.',k:'EYE',e:'M',i:3},
{c:'anthro',t:'A few very bright cores, not a uniform sprinkle',n:['lights'],d:'Night Earth is a power law: a handful of megalopolises, then nothing. Cap city intensity with a heavy tail and let the rest of the land stay black. The current wash makes every settlement a village of the same size.',k:'EYE',e:'S',i:3},
{c:'anthro',t:'Light colour that dates the century',n:['lights'],d:'Sodium orange, mercury, LED white. The model has a time axis and a civilisation. A 1890 night and a 2020 night should not be the same warm vector `vec3(1.0, 0.72, 0.35)`.',k:'EYE',e:'S',i:2},
{c:'anthro',t:'Lights that switch on as a dusk wave',n:['lights','globeclock'],d:'They currently fade with `uNight`. Real lights come on at a threshold along the terminator. That wave crossing a continent is the Anthropocene day cycle.',k:'EYE',e:'S',i:3},
{c:'anthro',t:'Cropland as geometry around settlements',n:['lights'],d:'Agriculture is straight edges at a scale nothing natural produces. A cadastral noise — rectangles, centre-pivot circles — in a ring around `W.build` is the daytime partner of city lights.',k:'EYE',e:'M',i:3},
{c:'anthro',t:'Roads and rail as thin dark lines',n:['lights'],d:'`city.js` places settlements and nothing connects them. A least-cost path over height and ice, drawn sub-pixel on the globe and as stamps on the map, turns a scatter into a network.',k:'SIM',e:'M',i:2},
{c:'anthro',t:'Reservoirs: bright geometric water',d:'Dams make polygons of water at elevations nature would not. Where `W.build` is high on a river cell, a rectangular lake is an unmistakable human mark and a hydrology change.',k:'SIM',e:'M',i:1},
{c:'anthro',t:'Contrails on a living industrial world',d:'Thin straight lines that no cloud process makes, persistent in moist upper air. `build` is the switch. They are also the first thing a 2026 Earth has that SimEarth 1990 did not.',k:'EYE',e:'S',i:2},
{c:'anthro',t:'A night-lights overlay that is the real product',n:['lights'],d:'VIIRS is how the public knows the human planet. Offer it as a view mode with a legend in nW/cm²/sr or an honest proxy, not as a side effect of the night shader.',k:'PLAY',e:'M',i:3},
{c:'anthro',t:'Skyglow domes over the largest cities',n:['lights'],d:'From orbit at an angle a city is a dome of scattered light. It is also how light pollution becomes a thing you can point at. A few additive hemispheres, nothing more.',k:'EYE',e:'M',i:1},
{c:'anthro',t:'Fires distinct from cities',n:['lights'],d:'Wildfire and gas flare are redder, flicker, and do not follow roads. `extinction.js` and the disaster layer know fire; the night shader does not. A week of African agricultural burning is a photograph.',k:'EYE',e:'S',i:2},
{c:'anthro',t:'Shipping lanes as sparse moving lights',n:['lights'],d:'The ocean at night has a faint grid of vessels on great-circle routes. Presentation-clock particles on a few lanes are enough to say the sea is used.',k:'EYE',e:'M',i:1},
{c:'anthro',t:'Cap Earth build so cities do not grow into megastructures',d:'`W.build[c] = min(earthLike ? 0.55 : 1, ...)` and mesh lift is 0.0035. From orbit a 0.55 city should still be a stain, not a spike. Keep the cap and express density as lights and roofs, not as Himalaya-scale displacement.',k:'EYE',e:'S',i:2},
{c:'anthro',t:'Settlement names that appear at the right zoom',d:'`city.js` already names them. They should fade in on the globe as you approach, the way a map does, and match the patch tooltip. Right now the planet is anonymous and the panel is not.',k:'PLAY',e:'S',i:2},
{c:'anthro',t:'A preindustrial Earth as a first-class look',n:['lights'],d:'SimEarth let you watch civilisation arrive. 1700 Earth at night is almost black; 2020 is not. A year-keyed lights intensity, zero before a threshold, is the Anthropocene as a time-lapse.',k:'SIM',e:'M',i:3},
{c:'anthro',t:'Air quality over the industrial belt',d:'Sulphate and dust already redden the limb globally. A regional brown haze downwind of `W.build` — the Gangetic plain, the North China Plain — is the daytime human planet.',k:'SIM',e:'M',i:2},
{c:'anthro',t:'Deforestation fronts as a hard edge',d:'A satellite can date the Amazon by the sawtooth of clearings. Where life drops next to high build, draw a hard geometric edge against intact canopy. It is an ugly photograph and it is Earth.',k:'EYE',e:'M',i:2},
{c:'anthro',t:'The local map must show a city as streets, not boxes',d:'`stampBuildings` draws boxes. At walk-in, a settlement is a grid, plots, a river port, smoke. The globe can stay a stain; the patch cannot.',k:'EYE',e:'M',i:3},
{c:'anthro',t:'Population as a number you can believe',d:'`x.pop` exists on cities. Sum it, show it, and do not let it exceed what `W.build` and agriculture can feed. A toy Earth with 80 billion people is not modern; it is a bug wearing a civilisation.',k:'PLAY',e:'S',i:2},
{c:'anthro',t:'Let night lights fail in a blackout',n:['lights'],d:'A disaster or a god-act that drops power should darken a region for a presentation-time night. The VIIRS archive of the 2003 blackout is the reference. Consequence as a photograph.',k:'PLAY',e:'S',i:1},
{c:'anthro',t:'Do not paint lights on uninhabited ice and ocean',n:['lights'],d:'If `vD.b` is biome-blue, Antarctica and the gyres will glitter. Mask lights by land, by `build`, by not-ice. The night photograph is mostly black water. Honour that.',k:'EYE',e:'S',i:3},
{c:'anthro',t:'A civilisation legend: what era, what energy',n:['lights'],d:'Foraging, agrarian, fossil, electric. SimEarth had a technology slider. Show which one the lights imply, and let a god-act move it with a visible lag.',k:'PLAY',e:'M',i:2},
{c:'anthro',t:'Compare the night side to a VIIRS composite',n:['eoref','lights'],d:'Store a downsampled night Earth. Hash the render. This is the Anthropocene equivalent of the Blue Marble still, and it will catch every `vD.b` mistake instantly.',k:'PLAY',e:'M',i:3},
{c:'anthro',t:'Fisheries and night boats on the shelves',n:['lights'],d:'The other night ocean lights are squid fleets on shelves. Tiny, seasonal, off river mouths. A handful of points, and the sea is worked.',k:'EYE',e:'S',i:1},
{c:'anthro',t:'The human planet should be optional',n:['lights'],d:'A Holocene-without-people mode is the control still. SimEarth could turn civilisation off. If you cannot hide the lights, you cannot teach what they are.',k:'PLAY',e:'S',i:2},
{c:'anthro',t:'Airports and ports as the brightest non-city points',n:['lights'],d:'A few hard points on coasts and inland hubs, brighter than the sprawl. Night Earth is not only urban fabric; it is nodes. `city.js` stages can pick a harbour and an airstrip analogue.',k:'EYE',e:'S',i:1},
{c:'anthro',t:'A 1950 / 1990 / 2020 night trio',n:['lights','eoref'],d:'Three stills of the same camera. The Anthropocene as a time-lapse SimEarth would have put on a slider. Store them as recipes next to VIIRS.',k:'PLAY',e:'M',i:2},
{c:'anthro',t:'Do not let build lift fight the photograph',n:['lights'],d:'`buildAmp` of 0.0035 on Earth is already a cartoon mountain at orbit. Lights and roofs at walk-in; a stain at ISS; never a Himalaya of downtown. The first-pass settlement item, restated as an Earth-look rule.',k:'EYE',e:'S',i:2},
/* ------------------------------------------------------------- ground -- */
{c:'ground',t:'A ground camera, not only a map',g:'groundcam',d:'The walk-in is a top-down canvas. Give the local view a tilt that can go to a horizon: sky occupying the top third, ground in perspective, the globe still in the other hand. Without a horizon the thesis is a minimap.',k:'EYE',e:'L',i:3},
{c:'ground',t:'The sky as half of what you see',n:['groundcam','limbvol'],d:'`weatherOverlay` paints rain on the map from above. Standing, the sky is colour, cloud, sun disc, and maybe a moon. Its colour is the strongest cue for time of day, latitude and air. Sample the same LUT the limb uses.',k:'EYE',e:'M',i:3},
{c:'ground',t:'A sun you can point at',n:['groundcam'],d:'There is no sun in the scene. From the ground it has an angular size of 0.5°, a colour from `st_teff`, and it casts the same shadows the globe uses. This is the object that makes a day a day.',k:'EYE',e:'S',i:3},
{c:'ground',t:'Long shadows at low sun, short at noon',n:['groundcam','sharedlight'],d:'`cellLight` dims; it does not swing a shadow. Entities, trees and relief have to share one sun vector with the globe or the two panels are different mornings.',k:'EYE',e:'M',i:3},
{c:'ground',t:'Aerial perspective across a few tens of kilometres',n:['groundcam'],d:'Even a 25 km patch has a far edge. Cool, haze, lose contrast with distance. One exponential on view depth converts a texture into a place you could walk.',k:'EYE',e:'M',i:2},
{c:'ground',t:'Footing: a ground plane that meets the shoes',n:['groundcam'],d:'Sprites float; `castShadow` is optional below `cellPx 8`. A contact shadow and a occlusion smudge under every standing thing is the difference between a sticker book and a landscape.',k:'EYE',e:'S',i:3},
{c:'ground',t:'Biome as a place you can recognise at eye height',n:['groundcam'],d:'Fifteen biomes share three textures in `paintCellDetail`. At standing scale a boreal forest is trunks and duff, a desert is stones and heat, a reef is water colour over structure. Author the ground rung or the walk-in is a coloured floor.',k:'EYE',e:'L',i:3},
{c:'ground',t:'Wind you can see in the grass',n:['groundcam'],d:'`windSway` exists and is under-used. A field of grass with a travelling gust is more alive than any fauna stamp, and it is already on the presentation clock.',k:'EYE',e:'S',i:2},
{c:'ground',t:'The smell is sound: a ground soundscape',n:['groundcam'],d:'`audio.js` is a 55 Hz hum, a noise bed, wind and ocean gains. At walk-in the bed should be the biome: surf, insects, canopy drip, dry wind. SimEarth had MIDI; the modern one can spatialize a few loops.',k:'PLAY',e:'M',i:3},
{c:'ground',t:'Weather between you and the ground',n:['groundcam'],d:'Rain shafts, falling snow, fog that hides the far cells. `precip` and `clouds` are fields. Parallax them so they sit in front of the stamps, not as a tint on the fill.',k:'EYE',e:'M',i:3},
{c:'ground',t:'A tide you can hear and watch at the strand',n:['groundcam'],d:'If the patch is coastal, the waterline walks, the surf changes pitch, wet sand darkens. `tidePhase` is a word in a strip. Make it the loudest thing on a beach cell.',k:'PLAY',e:'M',i:2},
{c:'ground',t:'Scale references a body understands',n:['groundcam'],d:'`drawScaleBar` says 1,632 km. A tree, a person, a hut, a cliff. One of those at a known height does more than the bar, and it is how you stop believing the map is a village when it is a country.',k:'EYE',e:'M',i:3},
{c:'ground',t:'Match the palette to the globe cell you are standing on',n:['groundcam','sharedlight'],d:'Side by side, the same cell disagrees. Shared materials, shared sun, shared wetness. The pairing is the product; mismatched colour is a broken lens.',k:'EYE',e:'M',i:3},
{c:'ground',t:'A horizon that curves, slightly',n:['groundcam'],d:'You are on a 6371 km sphere. A hint of dip on a wide patch — even a degree — says this is a planet you shrank onto, not a tiled RPG map.',k:'EYE',e:'M',i:2},
{c:'ground',t:'Night on the ground is not a dark day',n:['groundcam'],d:'Almost no colour, Purkinje-blue, point sources, a different fauna. `isOutNow` already gates entities. The fill, the stamps and the sky have to change species, not alpha.',k:'EYE',e:'M',i:3},
{c:'ground',t:'Heat shimmer on desert noon',n:['groundcam'],d:'A few pixels of refraction over hot ground. Cheap, and it is how a desert reads as hot rather than as tan.',k:'EYE',e:'S',i:1},
{c:'ground',t:'Breath in cold air',n:['groundcam'],d:'A local-map winter morning without vapour from fauna and settlements is a still of a cold colour, not a cold place.',k:'EYE',e:'S',i:1},
{c:'ground',t:'Let the patch camera sit at a chosen height',n:['groundcam'],d:'Eye, hill, kite, balloon. Four rungs between map and orbit, labelled. SimEarth had no in-between; this product promised all of them.',k:'PLAY',e:'M',i:2},
{c:'ground',t:'Picking a thing, not a cell',n:['groundcam'],d:'Hover names the cell biome. At ground scale you want this tree, this animal, this hut. `ENT.meta` has names; the cursor should use them.',k:'PLAY',e:'M',i:2},
{c:'ground',t:'Keep the globe in the peripheral view while standing',n:['groundcam','holdfeel'],d:'XR: one hand holds the planet, the other is on the ground. Desktop: a picture-in-picture of the disc with the patch marked. The descent is a relation, not a replace.',k:'PLAY',e:'M',i:3},
{c:'ground',t:'Do not rebuild 3,249 cell descriptions to draw a gust',n:['groundcam','imgdata'],d:'`drawLocalView` describes every cell every frame. Cache the ground, animate the weather and the fauna. The standing view will not ship if it costs an animation and looks like a photo.',k:'SIM',e:'M',i:3},
{c:'ground',t:'A dirt language: wet, dry, dust, mud',n:['groundcam'],d:'Rain darkens with no memory. Soil moisture with a multi-day constant, puddles in ruts, dust on the windward side of stamps. Ground is mostly dirt, and dirt is a state machine.',k:'SIM',e:'M',i:2},
{c:'ground',t:'Footprints and desire paths',n:['groundcam'],d:'`noteWear` decays at 0.965 a frame, which is theatre. Paths from water to graze, a trampled city square. The ground as a record of this afternoon.',k:'EYE',e:'S',i:2},
{c:'ground',t:'A first-walk tutorial that starts on a beach at golden hour',n:['groundcam'],d:'Do not spawn over a random desert cell. Author one descent: orbit, coast, surf, sky. The photograph people remember is the one you give them first.',k:'PLAY',e:'M',i:3},
{c:'ground',t:'Reduced motion still leaves a place',n:['groundcam'],d:'If sway, rain and shimmer all honour `reducedMotion()`, the standing view must remain readable as a still landscape, not a broken animation. Earth itself is allowed to be quiet.',k:'PLAY',e:'S',i:2},
{c:'ground',t:'Calibrate a ground still against a real biome photo',n:['eoref','groundcam'],d:'Six photos: dune, taiga, reef flat, temperate farm, night city, ice shelf. Six renders. This is the walk-in equivalent of the Blue Marble test.',k:'PLAY',e:'M',i:2},
{c:'ground',t:'A beach that is obviously a beach',n:['groundcam','coastline'],d:'The first-walk tutorial wants golden hour surf. Wet sand darker than dry, a foam line, a dune or a seawall, the disc in the sky. If the standing view cannot do a beach, it cannot do Earth.',k:'EYE',e:'M',i:3},
{c:'ground',t:'Insects and hush as the small end of the chorus',n:['groundcam'],d:'The living backlog asked for a soundscape. At stand-rung, a sparse insect bed in the tropics and a hush on ice are more Earth than a 55 Hz hum. Keep it optional and quiet.',k:'PLAY',e:'S',i:1},
/* --------------------------------------------------------------- hold -- */
{c:'hold',t:'Earth-sized Earth next to Mars-sized Mars',g:'holdfeel',d:'`worldRecord.pl_rade` exists and the globe is always radius 1 on screen. On the orrery table, true relative scale is the fastest fact you can teach with a hand. Earth should dwarf Luna and lose to Jupiter; anything else is a menu of spheres.',k:'PLAY',e:'S',i:3},
{c:'hold',t:'A thumb that can cover the limb',n:['holdfeel'],d:'In XR the planet is a rendering at arm length. If a real thumb cannot occlude the disc and reveal the limb around it, the object is a hologram. Depth, stereo disparity and a true radius in metres are the hold.',k:'EYE',e:'M',i:3},
{c:'hold',t:'Weight as inertia, not as a number',n:['holdfeel'],d:'Earth is heavy; a 0.1 g asteroid is not. Angular inertia from `pl_bmasse` and radius, so throwing and stopping feel different. SimEarth had no hands; this is the whole of the new interface.',k:'PLAY',e:'M',i:2},
{c:'hold',t:'The table is a place with a lamp',n:['holdfeel'],d:'`orreryTable.js` tints slots from meanLife and meanTemp. The table needs a surface, a horizon of the room, and a sun that is the host star. Worlds on a black void are slides; worlds on a table are toys.',k:'EYE',e:'M',i:3},
{c:'hold',t:'Six worlds that you can read without loading',n:['holdfeel'],d:'Shelf markers are coloured beads. A 32-pixel impostor with limb, ice and cloud is enough to pick Earth from Venus from Europa. `tintForEntry` is a climate average; the photograph is the label.',k:'EYE',e:'M',i:3},
{c:'hold',t:'Pinch-scale that is continuous into walk-in',n:['holdfeel','zoomspan'],d:'`scaleXR` clamps 0.07–0.95 and the local map is a separate control. One gesture should go from table to disc to patch to ground. The clamp is why the thesis currently feels like two apps.',k:'PLAY',e:'L',i:3},
{c:'hold',t:'Occlusion: fingers in front of the planet',n:['holdfeel'],d:'Hand meshes exist for XR and do not depth-test against the globe as a solid. A finger in front of Africa is the proof you are holding it.',k:'EYE',e:'M',i:2},
{c:'hold',t:'Earthshine and your own shadow on the disc',n:['holdfeel'],d:'In a lit room, or under the table lamp, the dark hemisphere should catch fill. In XR your head can shadow the planet. Those two lights make it an object.',k:'EYE',e:'M',i:2},
{c:'hold',t:'A grab that does not pick a menu',n:['holdfeel'],d:'Grab to spin is in. Grab should feel like friction on a sphere, with a little lag, not like rotating a gizmo. When you let go it should coast. That is the toy.',k:'PLAY',e:'S',i:2},
{c:'hold',t:'The live slot on the table is the world in your hands',n:['holdfeel'],d:'`slots.push({ id: "live", ... scale: 0.09 })` is a second copy. Highlight, do not duplicate, or the player does not know which Earth is Earth.',k:'PLAY',e:'S',i:2},
{c:'hold',t:'Sound of a held world',n:['holdfeel'],d:'The 55 Hz hum can become a felt bass when the planet is close, a thin hiss when it is a marble. Distance-graded audio is how a silent object gets a body.',k:'PLAY',e:'S',i:2},
{c:'hold',t:'Haptics on events while holding',n:['holdfeel'],d:'A quake, an impact, a superstorm: a tick in the controllers. SimEarth had a screenshot of a flashing continent. The modern one can tap your palm.',k:'PLAY',e:'M',i:2},
{c:'hold',t:'Do not snap scale when entering XR',n:['holdfeel'],d:'Desktop orbit to headset table is a cut. Carry radius and orientation through the session start so the planet you were looking at is the planet you now hold.',k:'PLAY',e:'S',i:2},
{c:'hold',t:'A rest pose: Earth in the palm, night side against the fingers',n:['holdfeel'],d:'Author one beautiful idle: terminator along the thumb, city lights leaking between fingers, moon small. This is the box art, and it should be reachable with one button.',k:'EYE',e:'M',i:3},
{c:'hold',t:'Relative moon distance that is true',n:['holdfeel'],d:'The moon is drawn at a decorative radius. 30 Earth-diameters is a lot; the toy version can be log-scaled but must say so. A moon sitting on the atmosphere is a lie children notice.',k:'PLAY',e:'S',i:3},
{c:'hold',t:'Jupiter cannot be a texture on the same sphere',n:['holdfeel','worldshader'],d:'If every body is radius 1, the table teaches the wrong solar system. Giants overflow the slot; that is correct. Scale the slot or scale the body, but stop hiding the fact.',k:'EYE',e:'M',i:3},
{c:'hold',t:'The host star as a lamp you could burn your hand on',n:['holdfeel'],d:'`starScale: 0.04` on the table. A G2 at true scale would fill the room; a compact table needs a stated miniature with glare. What you cannot do is a white bead that does not light the worlds.',k:'EYE',e:'M',i:2},
{c:'hold',t:'Desktop hold: drag with inertia, scroll with a scale that names kilometres',n:['holdfeel'],d:'The mouse already spins. Show "you are 8,000 km out" as you scroll, then "400 km", then "the patch". Numbers on the gesture are how a 2D screen fakes a hand.',k:'PLAY',e:'S',i:3},
{c:'hold',t:'A planet that fogs under a warm hand is a joke — a planet that responds is not',n:['holdfeel'],d:'Brush tools already paint. Holding should preview the current tool as a warmth or a shadow on the surface, then commit on squeeze. The toy and the god-game are one object.',k:'PLAY',e:'M',i:2},
{c:'hold',t:'Shelf worlds keep turning when you are not looking',n:['holdfeel'],d:'`phase` is a slow orbital drift. They should also rotate on their own periods, night side included, so the table is a room of planets, not a tray of stickers.',k:'EYE',e:'S',i:2},
{c:'hold',t:'Announce the mass when you pick it up',n:['holdfeel'],d:'A spoken or printed "Earth, 5.97 × 10^24 kg" on grab is kitsch unless the inertia matches. Do both or do neither. Stated limits, again.',k:'PLAY',e:'S',i:1},
{c:'hold',t:'Comfort: a seated table and a standing planet',n:['holdfeel'],d:'`height: 0.92` is one number. Seated XR needs a lower table; standing needs the disc at sternum. If the hold is uncomfortable, nobody looks at the Blue Marble.',k:'PLAY',e:'S',i:2},
{c:'hold',t:'A photograph mode from the hands',n:['holdfeel'],d:'Capture what the player is actually seeing — including their hands and the table — with seed, tick and look baked in. The shareable modern SimEarth image is a person holding Earth.',k:'PLAY',e:'M',i:2},
{c:'hold',t:'Do not lose the world on context loss',n:['holdfeel'],d:'Mobile XR will drop the GL context. Restore the same seed, the same orientation, the same scale. Dropping Earth because a tab backgrounded is the opposite of holding it.',k:'PLAY',e:'M',i:3},
{c:'hold',t:'Calibrate IPD and scale so Earth is not a grapefruit for everyone',n:['holdfeel'],d:'A stated default: 12 cm disc at 40 cm, about the Apollo-era desk globe. Let people change it. The hold has a real-world analogue; use it.',k:'PLAY',e:'S',i:1},
{c:'hold',t:'Two-handed scale must not fight the god brush',n:['holdfeel'],d:'Both grips currently scale. One grip plus a tool is paint; two grips is scale. Document it in the first session or people will raze continents trying to zoom.',k:'PLAY',e:'S',i:2},
{c:'hold',t:'The pale blue dot as a hold gesture',n:['holdfeel','bluemarble'],d:'Push Earth out to a point, hold it, bring it back. That zoom is the Sagan demo and it is free once scale is continuous. Put it on a tip.',k:'PLAY',e:'S',i:2},
{c:'hold',t:'A desk-globe default that matches a real 12 cm globe',n:['holdfeel'],d:'The Apollo-era classroom globe is the muscle memory. If XR Earth is a grapefruit for one person and a beach ball for another, the hold never becomes familiar. One published default, then a scale.',k:'PLAY',e:'S',i:2},
{c:'hold',t:'Let go and it coasts on its own night',n:['holdfeel'],d:'Release with velocity already throws a meteor. Release without should leave Earth turning into its own terminator, lights coming on, a toy that continues. That is the idle of the product.',k:'PLAY',e:'S',i:3},
/* ------------------------------------------------------------- chroma -- */
{c:'chroma',t:'Spectral albedo, then a camera, not a palette then a guess',g:'truecolor',d:'`landTerra` and `R.ocean(d)` return 8-bit triples tuned for a headset. Store albedo in linear 0–1 by material, illuminate, then expose. Earth is dark; the camera is what makes it visible. That is how a photograph works and how SimEarth never had to.',k:'EYE',e:'L',i:3},
{c:'chroma',t:'A measured Earth gamut the renderer may not leave',n:['truecolor'],d:'Sample a Blue Marble JPEG into a convex hull in linear Rec.709. If a pixel of terra sits outside it, the pixel is a toy. Guild tints and bloom are the usual offenders.',k:'EYE',e:'M',i:3},
{c:'chroma',t:'Open ocean 0.06, canopy 0.08, desert 0.30, snow 0.85',n:['truecolor'],d:'Those four numbers, as mean albedos of those materials, are the whole look. Print them live from the atlas. If canopy is 0.25, the Amazon will never go dark and the picture will never be Earth.',k:'SIM',e:'S',i:3},
{c:'chroma',t:'sRGB end-to-end, named',n:['truecolor'],d:'Vertex colours are authored as 0–255 bytes that look like sRGB, the shader treats them as if they were linear, then ACES is applied. Pick a space, convert once, document it. Banding and the lime forest are both symptoms of this muddle.',k:'SIM',e:'M',i:3},
{c:'chroma',t:'Vegetation red-edge as a real spectrum',n:['truecolor'],d:'Leaves are modestly green in the visible and jump past 700 nm. The globe only has RGB, but the transit-spectrum instrument already thinks spectrally. A three-band visible plus a NIR channel would let NDVI be a measurement instead of a vibe.',k:'SIM',e:'M',i:2},
{c:'chroma',t:'Water colour from absorption, not from two triples',n:['truecolor','watercol'],d:'`deep = [lerp(48,22,d), lerp(100,45,d), lerp(155,75,d)]` mixed with `R.ocean`. Jerlov absorption — red gone in metres, blue in tens of metres — is the reason a lagoon and an abyss are the same pigment. Replace the ramp.',k:'SIM',e:'M',i:3},
{c:'chroma',t:'Chlorophyll as absorption, CDOM as yellow absorption',n:['truecolor'],d:'`oceanLifeRGB` lerps toward a guild green. Productive water should go darker and greener; gelbstoff should go brown-green. MODIS bands exist so children can be shown a bloom. Match the direction of that change even if the coefficients are toy.',k:'SIM',e:'M',i:2},
{c:'chroma',t:'Soil colour from rock and wetness, not from biome leftover',n:['truecolor','material'],d:'Laterite red, loess pale, peat black, limestone white. `rock` is one overwritten byte; wetness is `W.moist` used for air. Split them and the continents stop being a green-to-tan slider.',k:'SIM',e:'M',i:3},
{c:'chroma',t:'Snow that is blue in the shade and gold at sunrise',n:['truecolor'],d:'Snow is the most faithful reflector of the sky. If ambient is grey, snow is grey, and the poles look like plastic. Hemispheric ambient from `uAtmo` is the whole fix.',k:'EYE',e:'S',i:2},
{c:'chroma',t:'No more uEarth desaturation as colour management',n:['truecolor','bluemarble'],d:'`mix(0.58, 0.30, uEarth)` is a grade pretending to be a planet. Grades belong in a lift/gamma/gain after the photograph is right. Earth is a material; the headset is a display.',k:'EYE',e:'S',i:3},
{c:'chroma',t:'Daisyworld should be two albedos, not a luminance mix',n:['truecolor','daisyviz'],d:'`daisyBW = max(smoothstep(0.72, 0.9, lum), smoothstep(0.32, 0.12, lum))` guesses daisies from brightness. `blackDaisy` and `whiteDaisy` are already fields. Show them as 0.05 and 0.75 albedo patches or the tutorial world is a filter.',k:'SIM',e:'S',i:3},
{c:'chroma',t:'Night as a different observer, not a multiplied day',n:['truecolor'],d:'ACES plus `uNight` is still photopic. Mesopic vision loses red and keeps blue-green. A Purkinje shift in the grade at low luminance is why moonlight feels like moonlight.',k:'EYE',e:'M',i:2},
{c:'chroma',t:'City lights in a separate emissive space',n:['truecolor','lights'],d:'Added before `tonemap(col * uExposure)`, so a bright star washes the cities. Emissive is nits; sunlight is nits; they meet in HDR. One of the first-pass items, restated here because it is also why a night Earth photograph fails.',k:'EYE',e:'S',i:3},
{c:'chroma',t:'A false-colour teaching mode that is labelled false',n:['truecolor'],d:'NDVI, SST, chlorophyll, night lights — Earth observation is mostly false colour. Offer it, name it, never let it be the default. SimEarth was all false colour and said so.',k:'PLAY',e:'M',i:3},
{c:'chroma',t:'White point from the host star',n:['truecolor'],d:'A G2 white point is not an M8 white point. `star.js` has teff. If the camera chromatic-adapts to the star, landscapes stay readable; if it does not, TRAPPIST-1 e is a red muddle. Pick one and state it.',k:'SIM',e:'M',i:2},
{c:'chroma',t:'Clouds are slightly warm-grey, not #ffffff',n:['truecolor'],d:'Earth cloud is 0.5–0.8 albedo and a little yellow from the sun and the path. A 1.0 white shell blows the exposure and steals the snow. Dim them.',k:'EYE',e:'S',i:2},
{c:'chroma',t:'The biome table is not a colour table',n:['truecolor'],d:'`BIOMES` is fifteen ecological names. Mapping each to a unique RGB is why savanna and deciduous can look more different than forest and ocean. Colour from materials; names from ecology; stop using one for the other.',k:'EYE',e:'M',i:3},
{c:'chroma',t:'Guild pigment as a second-order tint, not a wash',n:['truecolor'],d:'`base = mix(base, guildTint, lifeGreen * 0.35)` can purple a continent. Real pigments are a few percent of canopy albedo except on a microbial world. Gate the saturation on biomass structure: mats can be loud; trees cannot.',k:'EYE',e:'S',i:2},
{c:'chroma',t:'Exposure that photographs Earth, not Venus',n:['truecolor','hdrbuf'],d:'`baseExpo` from `W.solar` makes a G2 Earth and a 0.3 AU lava world share a knob. Meter on the disc median, like a camera. Earth should expose for the ground; clouds may clip; that is a photograph.',k:'EYE',e:'M',i:3},
{c:'chroma',t:'A colour-managed PNG export',n:['truecolor'],d:'`exportPng.js` writes whatever the canvas holds. Embed sRGB, or write linear 16-bit. Screenshots in the README are currently untagged, so every comparison with NASA is a lie about gamma.',k:'PLAY',e:'S',i:2},
{c:'chroma',t:'Dither after the grade, not instead of bit depth',n:['truecolor'],d:'Triangular dither before the 8-bit write is already on the first-pass list. Restate it for Earth: the limb gradient is the banding case, and it is the most photographed gradient we have.',k:'EYE',e:'S',i:2},
{c:'chroma',t:'Reference: average Earth chromaticity of ocean, forest, desert, cloud, ice',n:['truecolor','eoref'],d:'Five mean xy values from a Blue Marble, five means from the render, a table in Lab. This is cheaper than a full image test and it catches a lime forest in one line.',k:'PLAY',e:'S',i:3},
{c:'chroma',t:'Do not grade per-ruleset until Earth is right',n:['truecolor'],d:'The first-pass "dusty warm for Ares" item is correct and premature. If Earth is still a biome map, a per-world grade will hide it. Earth is the white balance of the whole catalogue.',k:'EYE',e:'S',i:2},
{c:'chroma',t:'Specular energy that does not become white paint',n:['truecolor'],d:'The GGX lobe is energy-clamped, then added into LDR. In HDR it should bloom; in LDR it should not become a white continent-sized blob. Earth ocean glint is small and extremely bright. That is the look.',k:'EYE',e:'S',i:2},
{c:'chroma',t:'Print whether the current view is true colour',n:['truecolor'],d:'A persistent badge: True colour / Vegetation boost / Overlay: SST. People will screenshot without the UI. The badge belongs in the capture too.',k:'PLAY',e:'S',i:3},
{c:'chroma',t:'Local map palette derived from the same albedos',n:['truecolor','sharedlight'],d:'Sixty `rgba(...)` literals in `localview.js`. Derive them from the material table at the current exposure or the pairing will always fight. Pixel art is allowed; a second physics is not.',k:'EYE',e:'M',i:3},
{c:'chroma',t:'A colourblind-safe photograph still has to be a photograph',n:['truecolor'],d:'Deuteranopia will crush forest and ocean if both are mid-luminance green-blue. Keep the luminance structure of Earth — dark sea, dark trees, bright desert, brighter cloud — and colourblind viewers still get a planet. Do not solve it by going neon.',k:'EYE',e:'M',i:2},
{c:'chroma',t:'Calibrate against a colorimetric Earth, not against taste',n:['truecolor','earthcal'],d:'Pick one composite, publish its mean RGB in linear, assert the render within a stated deltaE. Taste reviews are how the lime forest survived.',k:'PLAY',e:'M',i:3},
{c:'chroma',t:'The glint path is white, the sea is not',n:['truecolor'],d:'If the GGX lobe bleeds into a pale ocean, Earth loses the dark disc. Keep specular in a highlight buffer. The Blue Marble sea is black with a spark, not a cyan fill.',k:'EYE',e:'S',i:3},
/* -------------------------------------------------------------- gaia -- */
{c:'gaia',t:'Show the metabolism, not a resilience number',g:'gaiaface',d:'`W.resilience` is a blend of diversity, meanLife, temperature error and rate stress. Earth as a face is fluxes: carbon in, carbon out, albedo up, ice back. Draw the budget on the planet — greening, browning, freezing — or Gaia is a HUD.',k:'PLAY',e:'M',i:3},
{c:'gaia',t:'Daisyworld as two colours doing work',g:'daisyviz',n:['truecolor'],d:'`daisyNSpeciesTick` runs; `uDaisy` then mixes the Earth shader toward luminance. Black patches should warm, white patches cool, and the bands should crawl with temperature. That is the SimEarth tutorial, and it is currently a filter called `daisyBW`.',k:'SIM',e:'M',i:3},
{c:'gaia',t:'Draw the daisy bands as a map the player can paint',n:['daisyviz'],d:'The daisy-tutorial scenario exists in `god/scenario.js`. Let the brush seed black or white, then watch the temperature field answer. The lesson is the loop, not the label.',k:'PLAY',e:'S',i:3},
{c:'gaia',t:'Ice–albedo as a visible runaway, not a floor',n:['gaiaface'],d:'`iceTick` floors `iceLand` above 0.86 and `iceSea` above 0.88 so the caps cannot die. A snowball should be a thing you watch: white grows, albedo rises, white grows. The clamp hides the most famous Gaia story.',k:'SIM',e:'M',i:3},
{c:'gaia',t:'Weathering as a slow green-to-pale of mountains',n:['gaiaface'],d:'The Walker thermostat in `gaia.js` is a CO2 leak from warm wet land. The picture is mountains going dull and rivers going milky. If CO2 drops with no change on the ground, the thermostat is a cheat code.',k:'EYE',e:'M',i:2},
{c:'gaia',t:'Tipping elements as places, not a list',n:['gaiaface'],d:'`TIPPING` has iceSheet, amoc, amazon, boreal, permafrost, coral, monsoon. Six of seven are geography. Paint their state on the cells they name: a pale Amazon, a still North Atlantic, a dark reef. `W._amoc ?? 0.7` cannot trip and cannot show.',k:'PLAY',e:'M',i:3},
{c:'gaia',t:'AMOC as a colour of the North Atlantic',n:['gaiaface'],d:'When the conveyor is strong, Europe is green in winter relative to Labrador. When it is weak, the difference collapses. That is the photograph of a tipping element, and it needs ocean heat transport the currents backlog already asked for.',k:'SIM',e:'L',i:3},
{c:'gaia',t:'Amazon dieback as a browning you cannot miss',n:['gaiaface'],d:'`_forestFrac` is forest over land. The Amazon is a place. If tropical forest drops, that basin goes tan and the ITCZ should feel it. A global mean going from 0.4 to 0.3 is not a dieback.',k:'EYE',e:'M',i:3},
{c:'gaia',t:'Coral as a bleaching event with a recovery clock',n:['gaiaface'],d:'`refreshColours` already flashes reef white at `temp > 0.74`. Hold the white for presentation-weeks, then either green or bone. The tipping element `coral` reads `meanTemp`, which is the wrong geography.',k:'SIM',e:'S',i:2},
{c:'gaia',t:'Permafrost as a darkening and a bubble',n:['gaiaface'],d:'Thaw is thermokarst texture plus methane the redox tower can take. The list item exists; the ground does not change. A northern coast falling into lakes is the picture.',k:'SIM',e:'M',i:2},
{c:'gaia',t:'Daisyworld and Earth must not share a shader mix',n:['daisyviz'],d:'`lifeShow = max(lifeGreen, daisyBW * uDaisy + ...)` and `col = mix(col, biome * ..., daisyBW * max(uDaisy, 0.35))` mean a daisyworld still contains forests. Two looks, two rulesets. The tutorial is clearer if Earth is off.',k:'EYE',e:'S',i:2},
{c:'gaia',t:'A Gaia meter that is three gauges SimEarth would recognise',n:['gaiaface'],d:'Temperature, biomass, diversity — big, analogue, labelled with the range the model can actually occupy. `W.habitability` versus `W.inhabitance` is a good split and currently a pair of similar scalars.',k:'PLAY',e:'S',i:3},
{c:'gaia',t:'Show carbon breathing as a pulse on the land',n:['gaiaface','phenology'],d:'The Keeling curve is the inhale of the north. A subtle darkening of northern green in summer (more canopy, lower albedo) and a browning in winter is the same pulse. Do not make it neon; make it true.',k:'EYE',e:'M',i:2},
{c:'gaia',t:'Oxygen as a colour of the sky, late',n:['gaiaface','limbvol'],d:'Ozone from O2 is why twilight is blue. Deep time should have a pale, ozone-poor limb until the GOE, then the ring appears. That is Gaia as a history of the photograph.',k:'SIM',e:'M',i:3},
{c:'gaia',t:'Daisyworld report card: did the daisies regulate',n:['daisyviz'],d:'After a perturbation, plot T back toward the sweet spot or not. SimEarth ended with a report. The daisy scenario should too, in one chart, or it is a screensaver.',k:'PLAY',e:'S',i:3},
{c:'gaia',t:'Make tipping hysteresis visible as a scar',n:['gaiaface'],d:'Each `TIPPING` row has hysteresis. Once the Amazon browns, it should stay brown past the original threshold. A recovery that is slower than the collapse is the lesson; a slider snapping back is not.',k:'SIM',e:'M',i:2},
{c:'gaia',t:'Lovelock on the shelf: a one-button Daisyworld Earth',n:['daisyviz'],d:'From the table, a world that is only black and white daisies, grey bare ground, and a sun slider. No biomes, no cities. The modern SimEarth still needs the parable in its pure form.',k:'PLAY',e:'S',i:2},
{c:'gaia',t:'Resilience as a picture of many guilds, not a popcount',n:['gaiaface'],d:'`classBits |= (1 << (W.lifeClass[c] & 7))` then `popcount / 5`. Eight classes cannot show a biosphere. The Whittaker cloud of cells is the picture of resilience: occupied climate space. Draw that on the globe as a glow of unusual biomes.',k:'PLAY',e:'M',i:2},
{c:'gaia',t:'A god-act that the planet fights in view',n:['gaiaface'],d:'Raise CO2 and watch ice, cloud and green answer over presentation-minutes. If the answer is only a receipt, Gaia is a log line. The fight is the game.',k:'PLAY',e:'M',i:3},
{c:'gaia',t:'Do not call it Gaia if the AMOC cannot die',n:['gaiaface'],d:'`W._amoc = W.conveyor ?? W._amoc ?? 0.7` is written every tick from a conveyor that may not exist. Either wire the currents backlog into this gauge or remove the tipping element. A fake vital sign is worse than none.',k:'SIM',e:'S',i:3},
{c:'gaia',t:'Planetary health as a face you can misread',n:['gaiaface'],d:'A green planet can be a monoculture; a brown one can be a healthy desert. Teach the misread: overlay NPP versus life versus diversity, and let them disagree. SimEarth hid that disagreement behind one Health number.',k:'PLAY',e:'M',i:2},
{c:'gaia',t:'The anti-greenhouse haze as a veil with a cause',n:['gaiaface'],d:'`hazeAntiGreenhouse` reddens and cools. Titan and Archean Earth should go orange for a reason you can point at: a photochemical haze that also changes the limb. The veil is the metabolism.',k:'EYE',e:'M',i:2},
{c:'gaia',t:'A closed demo: perturb, wait, photograph the new Earth',n:['gaiaface'],d:'Script: double CO2, run 200 years of presentation time, export before/after discs. This is the modern SimEarth trailer and it is also a test.',k:'PLAY',e:'M',i:3},
{c:'gaia',t:'Name Watson and Lovelock in the daisy scenario copy',n:['daisyviz'],d:'The tutorial body text should say what is being claimed and what is toy. Stated limits. The picture then carries the claim.',k:'PLAY',e:'S',i:1},
{c:'gaia',t:'Connect `W.health` to something you can see',n:['gaiaface'],d:'`health` is already in the calibrate snapshot. If it is a function of ice, life and temperature, the disc should look sick when it is low: more desert, more ice, or a bleach. A healthy number on a lime continent is the old bug.',k:'EYE',e:'M',i:2},
{c:'gaia',t:'Gaia is Earth-specific; do not paste it on lava worlds',n:['gaiaface'],d:'`gaiaTick` runs everywhere. A Mercury with a resilience score is a category error. Gate the face, the tipping list and the daisy mix on a world that has air, water and a biosphere, or say "n/a" on the others.',k:'PLAY',e:'S',i:2},
{c:'gaia',t:'Daisy albedo feeding the climate the same tick it shows',n:['daisyviz'],d:'`bio.js` already updates `blackDaisy` / `whiteDaisy` and an albedo mix. If the globe still lights from biome RGB, the daisies are a texture and the thermostat is off-screen. Drive `refreshColours` from those fields when `daisyworld` is on.',k:'SIM',e:'S',i:3},
{c:'gaia',t:'A sick Earth should look sick in true colour first',n:['gaiaface','bluemarble'],d:'Snowball, hothouse, anoxic — the photograph changes before the gauge. If Health is low and the disc still looks like a Blue Marble, the face is lying.',k:'EYE',e:'M',i:3},
/* -------------------------------------------------------------- photo -- */
{c:'photo',t:'A library of Earth stills the render has to sit beside',g:'eoref',d:'Blue Marble 2002, one DSCOVR EPIC, one VIIRS night, one MODIS chlorophyll, one sea-ice extent map, one Himawari full disc. Keep them in `briefs/ref/` with camera recipes. Without a shelf of photographs, "realism" is an adjective.',k:'PLAY',e:'M',i:3},
{c:'photo',t:'A visual calibrate that asserts colour, not only climate',g:'earthcal',n:['eoref'],d:'`calibrate.mjs` checks meanTemp 0.38–0.62, landFrac 0.22–0.38, iceFrac 0–0.30, O2, CO2, meanLife. Add mean ocean xy, mean land xy, cloud fraction, night-light coverage. A passing climate with a lime ocean is a fail.',k:'PLAY',e:'M',i:3},
{c:'photo',t:'Camera recipes that match the satellites',n:['eoref'],d:'EPIC: sun behind camera, full dayside. Himawari: geostationary, Asia-Pacific. VIIRS: night side, no airglow wash. Store FOV, exposure and grade per still so a human can reproduce the comparison.',k:'PLAY',e:'S',i:3},
{c:'photo',t:'Do not compare a biome diagram to a photograph',n:['eoref','bluemarble'],d:'The default view has to be the photograph look, or the test will "pass" by matching a diagram to a diagram. Overlay modes are exempt and must be tagged.',k:'PLAY',e:'S',i:3},
{c:'photo',t:'Perceptual diff with a mask for unknown weather',n:['eoref','visreg'],d:'Cloud will never match a given day. Mask meteorological cloud, score land, ocean, ice and limb. Otherwise every test is a cloud test and will be disabled in a week.',k:'PLAY',e:'M',i:3},
{c:'photo',t:'A side-by-side Lab panel: NASA | ORRERY',n:['eoref'],d:'Same crop, a slider, seed and tick printed. This is the instrument for the look, and it belongs next to the Keeling curve, not in a markdown file nobody opens.',k:'PLAY',e:'M',i:3},
{c:'photo',t:'MODIS-style chlorophyll as a labelled false colour',n:['eoref'],d:'The bloom already exists as a lerp. Offer the palette people have seen on Wikipedia, with a legend in mg/m³-proxy, and say it is a proxy. Teaching by resemblance.',k:'PLAY',e:'S',i:2},
{c:'photo',t:'Sea-ice extent against NSIDC months',n:['eoref','phenology'],d:'A coarse monthly target by hemisphere. The floors in `iceTick` will fail this until they are removed. Good: the photograph is the argument for deleting the clamp.',k:'PLAY',e:'M',i:3},
{c:'photo',t:'Night lights against a downsampled VIIRS',n:['eoref','lights'],d:'Even a 64x32 equirectangular night Earth is enough to catch lights on Greenland ice and none on Honshu. Hash after a threshold; do not require city identity at N=64.',k:'PLAY',e:'M',i:2},
{c:'photo',t:'The limb crop test',n:['eoref','limbvol'],d:'64 pixels of actual Earth limb versus 64 pixels of ours, deltaE on the blue. This is the thin-line spec as a test, not as a paragraph.',k:'PLAY',e:'M',i:2},
{c:'photo',t:'Hypsometry histogram against ETOPO at cube-sphere N',n:['eoref'],d:'`refineEarthHypsometry` is careful and untested. Bimodal land/ocean peaks, shelf step, trench tail. A generated Earth can miss our continents and still hit this shape; that is the class test.',k:'PLAY',e:'M',i:2},
{c:'photo',t:'A locked-coastline reconstruction, labelled as such',n:['eoref'],d:'For calibration only: project a 1-degree land mask onto the cube sphere. Not the default of a god-game, but the default of a screenshot that claims "Earth". SimEarth shipped a Earth map. Say when you are using it.',k:'SIM',e:'L',i:3},
{c:'photo',t:'Document every still with the lie it still contains',n:['eoref'],d:'Relief exaggerated, cloud not of that day, cities a proxy, ocean colour a ramp. A caption template. Stated limits on the photograph itself.',k:'PLAY',e:'S',i:3},
{c:'photo',t:'Match sun angle, not only geography',n:['eoref'],d:'Blue Marble 2002 is a mosaic with a chosen illumination. If our still uses a side sun and theirs is high, the comparison is about lighting. Store `uSun` with the recipe.',k:'PLAY',e:'S',i:2},
{c:'photo',t:'A "why this is not Earth" readout on generated worlds',n:['earthcal'],d:'Land fraction, ice, desert belt latitude, cloud mean — each versus modern Earth, as a short list on the disc. Honesty for the seed that is Earth-class but not Earth.',k:'PLAY',e:'S',i:2},
{c:'photo',t:'Refuse to put an unlabelled render next to NASA in the README',n:['eoref'],d:'The README already uses in-app shots. When a shot is a comparison, it needs the recipe and the date of the NASA frame. Otherwise we are training people to see our diagram as the planet.',k:'PLAY',e:'S',i:2},
{c:'photo',t:'Cloud-free and cloudy as two targets',n:['eoref'],d:'A cloud-free mosaic teaches materials; a typical-cloud disc teaches weather. Both exist in the NASA archive. Test both or the cloud code will be tuned to disappear.',k:'PLAY',e:'M',i:2},
{c:'photo',t:'SST false colour against a GHRSST-style ramp',n:['eoref'],d:'The `temp` overlay is a rainbow of a 0–1 field. Earth SST maps are a published diverging palette around a stated midpoint. Steal the legend, not the data.',k:'PLAY',e:'S',i:1},
{c:'photo',t:'The first-frame still is a photograph, not a loading mesh',n:['eoref'],d:'PURPOSE says ninety seconds. The first present of terra should already be the Blue Marble look, even if cloud and grain fade in. A faceted lime ball is the anti-demo.',k:'PLAY',e:'M',i:3},
{c:'photo',t:'Store hashes per GPU vendor or use perceptual tolerance',n:['eoref','visreg'],d:'Exact PNG hashes will fail on Apple versus Adreno. deltaE and a fail fraction, as the first-pass visreg item said. Earth tests will be the ones people actually run, so they have to survive drivers.',k:'PLAY',e:'M',i:2},
{c:'photo',t:'A public "how Earth-like is this seed" score',n:['earthcal'],d:'Weighted: hypsometry, albedo, ice pulse, desert latitude, cloud distribution, night-light geography. Not a health score. A resemblance score, with the weights published.',k:'PLAY',e:'M',i:2},
{c:'photo',t:'Deep-time Earth stills: GOE, snowball, PETM, now',n:['eoref'],d:'Four photographs the model claims it can be. Even toy stills, authored, give the evolution backlog a visual contract. Modern Earth is one of four, not the only one.',k:'PLAY',e:'M',i:2},
{c:'photo',t:'Never use a screenshot with UI chrome as a calibration target',n:['eoref'],d:'Docks, ribbons and FPS counters are not Earth. Capture mode strips them. The NASA comparison is a disc on black, like theirs.',k:'PLAY',e:'S',i:2},
{c:'photo',t:'Credit the NASA / NOAA sources in the panel',n:['eoref'],d:'Blue Marble, EPIC, VIIRS, MODIS, NSIDC — the same way the exoplanet archive is credited in the README. The modern SimEarth is in conversation with those instruments.',k:'PLAY',e:'S',i:1},
{c:'photo',t:'A failure should show the two crops, not a boolean',n:['earthcal'],d:'When earthcal fails, write the NASA crop and the render crop to `vr/sim/output/` like the golden run. A boolean is how visual tests get ignored.',k:'PLAY',e:'S',i:2},
{c:'photo',t:'Keep the recipes versioned with the shader',n:['eoref'],d:'A camera recipe that assumed Blinn-Phong will mis-expose GGX. Version the stills when the tone curve changes, or the test becomes a freeze on an old look.',k:'PLAY',e:'S',i:1},
{c:'photo',t:'The photograph is the spec for every item in this pass',n:['eoref'],d:'If a new effect does not move an Earth still toward its reference, it is a toy effect and belongs in the diagram mode. This is the sequencing rule for the second 400.',k:'PLAY',e:'S',i:3},
{c:'photo',t:'Himawari / GOES as a geostationary recipe',n:['eoref','zoomspan'],d:'A full disc that barely rotates relative to the camera is how most people have seen live Earth. One snap, one still, one weather-teaching mode. Different from EPIC, different from ISS.',k:'PLAY',e:'S',i:2},
{c:'photo',t:'Refuse beauty passes that break the stills',n:['eoref'],d:'A bloom, a grain, a grade that makes the disc "cinematic" will fail earthcal. Lock the photograph look behind a named preset and put cinema in diagram mode. Earth is not a trailer.',k:'EYE',e:'S',i:2},
/* --------------------------------------------------------------- zoom -- */
{c:'zoom',t:'One scale, from table to footprint',g:'zoomspan',d:'`scaleXR` 0.07–0.95, `LOCAL_RADII` 3–28, N 64 default versus `N_LADDER` calling 96 the shipped default, two noise octaves on the globe, stamps on the map. None of this is one descent. Put every rung on a single kilometres-from-surface number and drive LOD, patch radius and XR scale from it.',k:'PLAY',e:'L',i:3},
{c:'zoom',t:'Print the altitude of the eye, always',n:['zoomspan'],d:'"8 r = 51,000 km", "400 km ISS", "10 km airliner", "2 m standing". The number is the missing label on every screenshot. SimEarth had a time slider; this product needs a distance slider that talks.',k:'PLAY',e:'S',i:3},
{c:'zoom',t:'ISS altitude as a named snap',n:['zoomspan'],d:'400 km is the photograph people think of as "from space". A snap that matches that FOV, with the limb thickness that implies, is the Blue Marble camera. It is not the orrery and not the walk-in.',k:'PLAY',e:'S',i:3},
{c:'zoom',t:'Geostationary as a named snap',n:['zoomspan'],d:'Himawari / GOES distance: a full disc that barely moves. Useful for weather, honest about perspective. Two named space cameras cover most of the NASA archive we are matching.',k:'PLAY',e:'S',i:2},
{c:'zoom',t:'N=96 as the Earth photograph default',n:['zoomspan'],d:'`sphere.js` still exports `N = 64`. `resolution.js` says 96 is shipped. A 157 km cell cannot hold an island arc or a real coast. Make the photograph path 96 (or say why 64 is the spec) and stop citing both as default.',k:'SIM',e:'M',i:3},
{c:'zoom',t:'Mesh LOD that follows the eye, not a global subd',n:['zoomspan','lodmesh'],d:'`GLOBE_SUBD` is one number. Standing on a coast should tessellate that face; the orrery should not. The first-pass lodmesh item, restated as a scale-rung requirement.',k:'EYE',e:'L',i:3},
{c:'zoom',t:'Field mips so the orrery does not alias into noise',n:['zoomspan','seamfix'],d:'At table distance a cell is a fraction of a pixel. Without mips the atlas sparkles and the Blue Marble becomes glitter. Face-local mips, never across the six-strip seam.',k:'EYE',e:'M',i:3},
{c:'zoom',t:'A rung between continent and patch',n:['zoomspan'],d:'Orbit to a 25 km square is four orders of magnitude. A 2,000 km "country" view — still the globe, with the patch as a real inset — is the missing SimEarth regional map.',k:'PLAY',e:'M',i:3},
{c:'zoom',t:'Continuous patch zoom, not six radii',n:['zoomspan'],d:'`LOCAL_RADII = [3,5,8,12,18,28]`. With a cached ImageData base, radius can be a float. The stair of rungs is why the descent feels like menus.',k:'PLAY',e:'L',i:2},
{c:'zoom',t:'Detail octaves that appear as you approach, then yield to stamps',n:['zoomspan'],d:'Two fbm octaves cover 250 km to 5 km. Below that the map must take over with a shared material, not a different planet. Crossfade on the kilometres number, not on `cellPx >= 6`.',k:'EYE',e:'M',i:3},
{c:'zoom',t:'Relief exaggeration that falls as you approach',n:['zoomspan'],d:'0.028 is a 20× Earth at orbit and a cartoon at walk-in. Let exaggeration lerp toward 1× as altitude drops, and print the factor. Honest mountains at the beach; readable mountains from the table.',k:'PLAY',e:'M',i:3},
{c:'zoom',t:'Clouds that become weather, not a texture, as you fall',n:['zoomspan','cloudtop'],d:'From the table, cloud is albedo. From 10 km, it is a deck you are under. The shell cannot stay a planet-sized mesh at every rung. LOD the cloud the same way as the ground.',k:'EYE',e:'M',i:2},
{c:'zoom',t:'Entities that exist only at the rungs that can show them',n:['zoomspan'],d:'1,400 sprites at orrery distance are noise and cost. Fade them in with the patch; on the globe, herds are a texture. SimEarth never drew a deer on the disc.',k:'EYE',e:'S',i:2},
{c:'zoom',t:'XR pinch mapped in log kilometres',n:['zoomspan','holdfeel'],d:'Linear `scaleXR *= g.scaleDelta` spends half the gesture on useless near-orbit. Log scale spends equal hand motion per decade, which is how the descent can be one gesture.',k:'PLAY',e:'M',i:3},
{c:'zoom',t:'A scale legend that uses Earth facts',n:['zoomspan'],d:'"This view is about France", "this cell is Belgium", "this patch is Texas". `st.scaleNamed` already tries. Put it on the globe, not only in a status strip.',k:'PLAY',e:'S',i:2},
{c:'zoom',t:'Stop quoting 250 km per cell as if N were fixed',n:['zoomspan'],d:'This document, the living backlog and half the comments still say 250 km. At N=64 it is ~157 km; at 96, ~104. A helper `cellKm(N)` and a pass over the copy. Stated limits include the grid.',k:'PLAY',e:'S',i:2},
{c:'zoom',t:'The pixel map should know how wide it is in kilometres',n:['zoomspan'],d:'Radius 28 at N=64 is not the same Earth as radius 28 at N=256. Convert to km for the scale bar or the bar is a lie when someone moves N in Lab.',k:'PLAY',e:'S',i:3},
{c:'zoom',t:'Horizon culling that depends on altitude',n:['zoomspan'],d:'From the table, draw the disc. From ISS, cull the far limb less naively. From the ground, do not draw the back of the planet at all. One indexed draw of 786,432 vertices is an orbit budget.',k:'SIM',e:'M',i:2},
{c:'zoom',t:'A zoom that eases, with a hold of the outgoing picture',n:['zoomspan'],d:'The local map already eases pans. Altitude changes are cuts. Crossfade or a brief motion-blurred dolly is what makes a descent feel like falling rather than like a tab.',k:'EYE',e:'M',i:2},
{c:'zoom',t:'Do not refresh 24,576 vertex colours because the patch radius changed',n:['zoomspan'],d:'`refreshColours(1)` on focus change is already a first-pass crime. Radius change is the same crime on the zoom axis. Uniforms and a mask, not a CPU bake.',k:'SIM',e:'M',i:3},
{c:'zoom',t:'Named rungs in the UI: table, disc, ISS, country, patch, stand',n:['zoomspan'],d:'Six words. They are the product. Chips that snap, with the km number under them. SimEarth had Geologic / Evolution / Civilisation time; we need distance.',k:'PLAY',e:'S',i:3},
{c:'zoom',t:'A test that the Blue Marble still is taken at the ISS snap',n:['zoomspan','eoref'],d:'If someone retunes FOV, the comparison camera moves. Bind the Earth stills to named snaps, not to magic numbers in a comment.',k:'PLAY',e:'S',i:2},
{c:'zoom',t:'Allow N=128 for a photograph session without rebaking the sim',n:['zoomspan'],d:'Presentation resolution versus sim resolution. A finer atlas upsample, even fake, for screenshots. The god-game can stay at 96; the README should not have to.',k:'SIM',e:'L',i:2},
{c:'zoom',t:'The descent should not change the time step silently',n:['zoomspan'],d:'Walk-in is not an excuse to freeze geology, but it is an excuse to run presentation weather. Declare it. A player who shrinks should not discover that ice sheets stopped.',k:'SIM',e:'S',i:2},
{c:'zoom',t:'Remember the last altitude per world on the shelf',n:['zoomspan','holdfeel'],d:'Pick up Earth where you left it — usually ISS. Pick up a daisyworld at table. Session memory is how a toy becomes yours.',k:'PLAY',e:'S',i:1},
{c:'zoom',t:'ISS FOV as the default screenshot camera',n:['zoomspan','eoref'],d:'README and site images should come from the named ISS snap, not from whatever the last debug camera was. The public Earth is a 400 km Earth.',k:'PLAY',e:'S',i:3},
{c:'zoom',t:'A country-rung that still has a limb',n:['zoomspan'],d:'At 2,000 km you should see a curved horizon and weather, not a flat map. If the country view is the pixel map scaled up, the descent skipped a planet.',k:'EYE',e:'M',i:3},
{c:'zoom',t:'Do not change N as a zoom substitute',n:['zoomspan'],d:'Raising N to see a coast is a sim cost; approaching is a camera cost. Teach the difference in Lab or people will crank 256 to screenshot a beach and drop the frame rate of the toy.',k:'PLAY',e:'S',i:2},
/* ------------------------------------------------------------- record -- */
{c:'record',t:'The surface as a palimpsest, not a state vector',g:'palimpsest',d:'Earth looks old because scars overlap: craton, orogen, glacial polish, farm, burn, road. Fields here are the present. Keep a low-resolution history of ice max, last fire, last flood, last plough, and let the shader read it as wear. Generated is the opposite of Earth.',k:'SIM',e:'L',i:3},
{c:'record',t:'Cratons that stay red and low',n:['palimpsest'],d:'`age[c] > 400` already lifts a ridged term. Real shields are iron-stained, flattened, and they refuse mountains. Colour and a hardness that erosion respects would show the oldest rock as a place, not as a bump.',k:'EYE',e:'M',i:2},
{c:'record',t:'Moraines and lake stipple after ice',n:['palimpsest'],d:'Maximum ice extent per cell, then a stipple of lakes and a pale arc of till when ice leaves. Canada and Finland are a climate memory. Without this, deglaciation is a colour lerp.',k:'SIM',e:'M',i:3},
{c:'record',t:'River terraces as benches',n:['palimpsest'],d:'Sea-level steps leave stairs in valleys. Even one extra contour of former `seaLevel` as a brighter lip is a Holocene story you can walk.',k:'SIM',e:'M',i:1},
{c:'record',t:'Burn scars that last a decade of presentation time',n:['palimpsest'],d:'Fire exists in extinction and disaster. A black-to-green fade, visible from orbit, is time passing. Right now the forest returns as a scalar and the photograph never happened.',k:'SIM',e:'S',i:3},
{c:'record',t:'Ruins when build falls',n:['palimpsest'],d:'`W.build` decays by 0.004 a tick and the city is gone. A pale footprint, a grid in the canopy, a harbour wall. Civilisation as a layer that can be abandoned — SimEarth had this as a mood, we can have it as a texture.',k:'EYE',e:'M',i:2},
{c:'record',t:'Chronicle events that leave a mark at the cell',n:['palimpsest'],d:'`W.chron` has a cell. Impacts, first cities, floods should stain. `whatHappenedHere` using `Math.abs(e.cell - cell)` is not geography and not a picture. Project events onto neighbours with a real distance and a fading decal.',k:'PLAY',e:'M',i:3},
{c:'record',t:'A core as a stripe on a cliff, not only a panel',n:['palimpsest'],d:'The core sampler is one of the best instruments and it lives in a dock. When the patch is a canyon, the wall should show the same layers. Geology becoming scenery is Earth.',k:'EYE',e:'M',i:2},
{c:'record',t:'Impact craters that remain on land that is not Selene',n:['palimpsest'],d:'Earth wipes craters; it does not wipe them instantly. A few visible bowls — with lakes — say the planet is in a solar system. Deep time can heal them; Holocene should still show a Chicxulub-class scar if it happened.',k:'SIM',e:'M',i:2},
{c:'record',t:'Farmland that remembers last year',n:['palimpsest','phenology'],d:'Stubble, flood silt, a fallow patch. Seasonal agriculture is a record at 1-year scale. The Anthropocene is not only lights.',k:'EYE',e:'S',i:1},
{c:'record',t:'Sediment as a colour of history at the river mouth',n:['palimpsest'],d:'The plume is this year. The delta lobe is a thousand years. If `sediment` saturates at 1 and stops, the photograph of a delta cannot age. Let it build a brighter, shallower fan over deep time.',k:'SIM',e:'M',i:2},
{c:'record',t:'A "what this place used to be" sentence on inspect',n:['palimpsest'],d:'`patch.status` has a whisper. Add a former biome, a former shoreline, a former ice. The modern SimEarth inspect is a small history, not a sensor dump.',k:'PLAY',e:'S',i:2},
{c:'record',t:'Do not destroy ENT identity if the ground is supposed to remember them',n:['palimpsest'],d:'`respawnEntities` wipes names several times a minute. Tracks and graves cannot exist on top of that. The living backlog said this; the photograph of a path needs it too.',k:'SIM',e:'M',i:2},
{c:'record',t:'Plate motion as a slow smear in time-lapse',n:['palimpsest'],d:'From the table, a 10 Myr time-lapse of coasts is the Wilson cycle as a movie. Without a recorded trail of the shoreline, there is nothing to smear. Sample a coast polyline every N ticks.',k:'PLAY',e:'M',i:2},
{c:'record',t:'Volcanic provinces with an age colour',n:['palimpsest'],d:'Fresh black, then red, then vegetated. LIPs and arcs should remain as provinces long after `ash[c]` is zero. Deccan and Siberia are still visible in a true-colour Earth.',k:'EYE',e:'M',i:2},
{c:'record',t:'A glacial striation texture where ice once flowed',n:['palimpsest'],d:'Oriented scratches at the standing rung, aligned to former ice motion. Cheap in the local map, invisible from orbit, and the reason a granite slab looks like Earth and not like noise.',k:'EYE',e:'S',i:1},
{c:'record',t:'Keep a screenshot of first life, first ice, first city',n:['palimpsest'],d:'Finale already exports. Auto-still at chronicle firsts, shown as a contact sheet at the end of a run. SimEarth had a report card; ours can be a photo album of a planet.',k:'PLAY',e:'M',i:2},
{c:'record',t:'Unconformity: a missing time that shows as a line',n:['palimpsest'],d:'The core sampler invents a column. A gap is information. Draw it as a sharp colour step in the cliff and as a break in the strip. Earth is mostly missing time.',k:'SIM',e:'M',i:1},
{c:'record',t:'Name the eon on the disc without opening Lab',n:['palimpsest'],d:'A small ICS colour pip and a word: Holocene, Pleistocene, Archean. People navigate Earth by "when" as much as "where". The ribbon at the bottom is easy to ignore.',k:'PLAY',e:'S',i:2},
{c:'record',t:'Do not let overlays erase the palimpsest',n:['palimpsest'],d:'Temperature rainbows hide scars. A "surface" underlay should remain faintly visible, or the teaching tool becomes a false-colour planet with no Earth in it.',k:'EYE',e:'S',i:2},
{c:'record',t:'A memory budget so history cannot be unbounded',n:['palimpsest'],d:'Per-cell history is RAM. Keep maxima, last-event ids, and a ring of coastlines, not a stack of every tick. Stated limits on memory are part of stated limits on the picture.',k:'SIM',e:'S',i:2},
{c:'record',t:'The pixel map as the close reader of the palimpsest',n:['palimpsest','groundcam'],d:'Orbit shows the burn; the patch shows charcoal and new shoots. Shared history fields, two densities. That pairing is the product again.',k:'EYE',e:'M',i:2},
{c:'record',t:'Calibrate "old" against a craton map of real Earth',n:['palimpsest','eoref'],d:'Even a cartoon of Archean shields versus Phanerozoic belts, used only in locked-coastline mode, teaches the collage. Generated worlds get the process, not the map.',k:'PLAY',e:'M',i:1},
{c:'record',t:'Let a god-act leave a dated stamp',n:['palimpsest'],d:'Receipts exist. A faint sigil or a dated scar at the brush cell, decaying, is how the planet remembers you. SimEarth players remembered where they put the deserts.',k:'PLAY',e:'S',i:2},
{c:'record',t:'History that is wrong should look uncertain',n:['palimpsest'],d:'If the column is reconstructed, hatch it. If the ice max is a proxy, desaturate the moraine. Implied precision on a palimpsest is how a toy becomes a fake archive.',k:'PLAY',e:'S',i:2},
{c:'record',t:'A shoreline of last interglacial, faintly',n:['palimpsest'],d:'Raised beaches a few metres above now. Even a one-pixel pale contour on the standing coast is a Holocene fact. Sea-level history the hydro model already inches toward.',k:'EYE',e:'S',i:1},
{c:'record',t:'First light as a chronicle still',n:['palimpsest','lights'],d:'The night the first settlement crosses a threshold, snapshot the disc. Civilisation arriving is a SimEarth beat and a photograph.',k:'PLAY',e:'S',i:2},
{c:'record',t:'Do not remember what the model does not know',n:['palimpsest'],d:'If there is no ice-max field, do not draw moraines. Empty palimpsest is honest; invented glacial sculpture is a poster. Stated limits on memory.',k:'PLAY',e:'S',i:2},
/* --------------------------------------------------------------- toy -- */
{c:'toy',t:'Keep the toy, make the toy Earth',g:'simdna',d:'Wright planet was sliders, a disc, a report. ORRERY has receipts, a redox tower and a catalogue. The second 400 is not "delete the toy". It is: every slider must photographically change Earth, and Earth must still be holdable. If a control cannot be seen on the disc, it is Lab, not SimEarth.',k:'PLAY',e:'M',i:3},
{c:'toy',t:'Atmosphere gauges that change the limb the same frame',n:['simdna','limbvol'],d:'CO2, O2, aerosols as sliders. SimEarth did this with a delay. Ours can do it with `scatter.js` rebuilt on commit. The limb is the gauge.',k:'PLAY',e:'M',i:3},
{c:'toy',t:'A time slider that is a film of the disc',n:['simdna','phenology'],d:'The ICS ribbon jumps. A scrubbable year — or a 4 Gyr with keyframes — should show ice, green, cities arriving. If scrubbing only changes a label, it is not a slider, it is a caption.',k:'PLAY',e:'L',i:3},
{c:'toy',t:'Biome paint that is a god-act with a weather answer',n:['simdna'],d:'SimEarth let you paint desert. We have a brush. Painting forest should change albedo, then cloud, then rain, in view. If the paint is only `W.life[c] = 1`, it is a texture stamp.',k:'PLAY',e:'M',i:3},
{c:'toy',t:'A report card that is photographs plus numbers',n:['simdna','eoref'],d:'End of run: four stills, Bond albedo, ice, O2, a sentence. SimEarth printed a moral; we can print a before/after. `finale.js` is the hook.',k:'PLAY',e:'M',i:3},
{c:'toy',t:'Daisyworld remains the first planet on the shelf',n:['simdna','daisyviz'],d:'Not buried in scenarios. A beginner world that is obviously a parable, sitting next to Earth that is obviously a photograph. The pair is the thesis: toy, then Earth, same hands.',k:'PLAY',e:'S',i:3},
{c:'toy',t:'Geologic / Evolution / Civilization as three clocks you can see',n:['simdna'],d:'SimEarth speed settings. Ours: plates smear, phenology pulses, lights spread. Three presentation modes, mutually exclusive, labelled. Deep time that shows all three at once shows none.',k:'PLAY',e:'M',i:3},
{c:'toy',t:'A "random planet" that is still Earth-class',n:['simdna'],d:'The fun of SimEarth was a new disc. Seed a hypsometry, not a lime ball. The class test from marble is the generator contract.',k:'PLAY',e:'M',i:2},
{c:'toy',t:'Disasters as weather you watch, not a dialog',n:['simdna'],d:'Meteor, plague, nuclear — SimEarth icons. We have `god/disaster.js`. An impact should flash the disc, raise a plume, and leave a palimpsest. A modal is 1990; a photograph is 2026.',k:'PLAY',e:'M',i:2},
{c:'toy',t:'The History of Earth as a guided film',n:['simdna'],d:'A scenario that is not a puzzle: 4 Ga to now, authored camera, GOE limb, snowball, forests, cities. The modern encyclopedia mode. Skip it if you want to play; it teaches the photograph.',k:'PLAY',e:'L',i:2},
{c:'toy',t:'Keep the dock from covering the disc',n:['simdna'],d:'SimEarth put gauges around a planet you could still see. Our docks eat the limb. A photo mode, a play mode with a thinner chrome, and Lab. Three visibilities.',k:'PLAY',e:'S',i:3},
{c:'toy',t:'Sound that is 2026 MIDI: sparse, diegetic, optional',n:['simdna'],d:'A hum that tracks health, a click on a tick of the year, biome beds at walk-in. Mute by default in Lab, on in play. The 55 Hz sine is a placeholder that became the product.',k:'PLAY',e:'M',i:2},
{c:'toy',t:'A civilisations layer you can turn off like SimEarth',n:['simdna','lights'],d:'The toggle is also a teaching tool: the Holocene without us. Store it as a presentation flag, not by deleting `city.js`.',k:'PLAY',e:'S',i:2},
{c:'toy',t:'God budget as a visible strain on the disc',n:['simdna'],d:'`budgetMode` starts false. When it is on, overuse should show: a too-hot limb, a grey biome, a receipt. Economy that is only a number is a spreadsheet, not a toy planet.',k:'PLAY',e:'M',i:2},
{c:'toy',t:'One-button "make it like Earth again"',n:['simdna','earthcal'],d:'After chaos, a Holocene reset that is labelled as a cheat. SimEarth had it in spirit. Calibration as a god-act, not only as a test.',k:'PLAY',e:'S',i:2},
{c:'toy',t:'The planet should be funny when you are funny',n:['simdna'],d:'A daisyworld next to a lava world on the table, a report card that can say "you froze Canada". Delight in the first ninety seconds includes a grin, not only a correct limb.',k:'PLAY',e:'S',i:1},
{c:'toy',t:'Do not hide N and exposure in Lab only',n:['simdna'],d:'Photograph quality is a play control: chunky toy at 32, Earth at 96, "why is it slow" at 256. SimEarth let you see the model grain. So should we.',k:'PLAY',e:'S',i:2},
{c:'toy',t:'A boxed Earth: the default seed is a beautiful still',n:['simdna','bluemarble'],d:'First boot is not a random ugly hypsometry. A known seed that passes earthcal and looks like a marble. Then "new planet". Toys are designed; sandboxes come second.',k:'PLAY',e:'M',i:3},
{c:'toy',t:'Controller and mouse both get the same toy verbs',n:['simdna','holdfeel'],d:'Spin, scale, paint, inspect, time. If desktop cannot hold, it should still spin with inertia and scale in km. The DNA is the verbs, not the headset.',k:'PLAY',e:'M',i:2},
{c:'toy',t:'A pause that is a still photograph, not a frozen sim with a live boil',n:['simdna','globeclock'],d:'`boil` runs off `S._t`. Pause should freeze presentation too, or "pause" is a lie and you cannot look. Earth itself can be examined.',k:'PLAY',e:'S',i:3},
{c:'toy',t:'Tips that point at the disc, not at the dock',n:['simdna'],d:'`god/tips.js` teaches tools. A first-session tip should circle the Sahara, the limb, a cyclone. The photograph is the tutorial.',k:'PLAY',e:'S',i:2},
{c:'toy',t:'Export a postcard: disc, black, caption',n:['simdna'],d:'No chrome, a one-line date and seed, a NASA-style caption. The shareable unit of the modern SimEarth. `exportPng` plus a template.',k:'PLAY',e:'S',i:2},
{c:'toy',t:'Keep Daisyworld ugly on purpose',n:['simdna','daisyviz'],d:'If daisyworld becomes a beautiful Earth, the parable dies. High contrast, two pigments, grey rock. The toy is allowed to look like 1990; Earth is not.',k:'EYE',e:'S',i:2},
{c:'toy',t:'A kids mode: photograph, three sliders, no redox tower',n:['simdna'],d:'Sun, tilt, clouds. The disc answers. Everything else behind a More. The modern extrapolation still has to be holdable by a child who liked SimEarth.',k:'PLAY',e:'M',i:3},
{c:'toy',t:'Credits that name Wright and Sagan without being a museum',n:['simdna'],d:'A short colophon in the pause screen. The product is a conversation with 1990 and with a pale blue photograph. Say so, once.',k:'PLAY',e:'S',i:1},
{c:'toy',t:'The toy must survive a phone',n:['simdna','tier'],d:'A 12 cm disc at 30 Hz with the photograph look at N=48 is more SimEarth than a perfect ISS still on a workstation nobody holds. Tier defaults are a design decision, not a perf footnote.',k:'PLAY',e:'M',i:3},
{c:'toy',t:'Let people collect stills on the shelf like globes',n:['simdna','holdfeel'],d:'Each shelf entry can store a thumbnail of its disc. A row of marbles you made. That is the god-game as a hobby, which is what SimEarth was.',k:'PLAY',e:'S',i:2},
{c:'toy',t:'A new-planet button that plays the settle film',n:['simdna'],d:'The first-pass settle animation — ocean fill, first ice, first green — is the toy birth. Wire it to New, not only to the first boot. Every disc should get a beginning.',k:'PLAY',e:'S',i:2},
{c:'toy',t:'Keep the time ribbon honest about what you will see',n:['simdna'],d:'If Geologic mode cannot show plates moving in the current still, say so on the chip. A speed setting that does not change the photograph is a broken toy.',k:'PLAY',e:'S',i:2},
/* -------------------------------------------------------------- teach -- */
{c:'teach',t:'Earth is the legend for every other world',g:'earthlegend',d:'The catalogue is unreadable if Earth is a biome diagram. Once the photograph is right, "this is drier than Earth", "this limb is thicker than Earth", "this night has no cities" become sentences. Until then every comparison is two diagrams.',k:'PLAY',e:'M',i:3},
{c:'teach',t:'A always-on readout of what you are looking at',n:['earthlegend'],d:'Lat, month, km/cell, true-colour badge, seed. Small. The NASA stills have captions; ours hide in a status strip that compresses them away.',k:'PLAY',e:'S',i:3},
{c:'teach',t:'Stated exaggeration of relief, on the disc',n:['earthlegend'],d:'0.028 versus 0.0014 is a factor of twenty. Print "relief ×20" until it is 1. Implied mountains are the most common planetary lie in educational software.',k:'PLAY',e:'S',i:3},
{c:'teach',t:'Stated cloud: typical, not this day',n:['earthlegend'],d:'We will never match EPIC of 17 August 2026. Say "synoptic cloud from the model, not a weather archive". Then the comparison is fair.',k:'PLAY',e:'S',i:3},
{c:'teach',t:'Stated cities: proxy, not census',n:['earthlegend','lights'],d:'Night lights are not VIIRS. A caption "civilisation proxy from settlements" stops a journalist treating our Honshu as data.',k:'PLAY',e:'S',i:2},
{c:'teach',t:'A glossary tap on the limb, the desert, the bloom',n:['earthlegend'],d:'`glossary.js` exists. Long-press a feature, get the word. The photograph is a textbook if the words are in it.',k:'PLAY',e:'M',i:2},
{c:'teach',t:'Compare-to-Earth as a default overlay for exoplanets',n:['earthlegend'],d:'Radius, insolation, limb, day length, as multiples of Earth, drawn on the other body. The modern SimEarth catalogue is a set of Earth-lessons.',k:'PLAY',e:'M',i:3},
{c:'teach',t:'Do not imply 0.01 °C on a 0–1 temperature field',n:['earthlegend'],d:'`main.js` already prints a °C conversion for Earth. Significant figures should follow `calibrate.mjs` tolerances, not JavaScript floats. Implied precision is the PURPOSE sin.',k:'PLAY',e:'S',i:3},
{c:'teach',t:'A "what is toy" list in the pause screen',n:['earthlegend'],d:'No crustal thickening during run, AMOC is a stub, coastlines are generated, N is 100 km. Ten lines. Updated when items land. The honest box copy.',k:'PLAY',e:'S',i:3},
{c:'teach',t:'School mode: Earth, true colour, ISS snap, no god brush',n:['earthlegend','zoomspan'],d:'A presentation that cannot accidentally paint a continent. Export the postcard. This is how the photograph gets into a classroom without the god-game.',k:'PLAY',e:'M',i:2},
{c:'teach',t:'The Whittaker plot with Earth cells as the background cloud',n:['earthlegend'],d:'Already an instrument. Underplot a faint modern-Earth occupancy so an alien climate is a deviation, not a modern art piece.',k:'PLAY',e:'S',i:2},
{c:'teach',t:'Energy budget as a picture of the disc',n:['earthlegend'],d:'The first-pass diagram item, restated: in, out, ice, cloud, on the planet. SimEarth had an energy flow cartoon. Ours can be the disc with annotated arrows.',k:'PLAY',e:'M',i:2},
{c:'teach',t:'Never ship a lime Earth in the pitch site',n:['earthlegend','eoref'],d:'`site/img/earth-hud.png` is the promise. When the look changes, regenerate it from the ISS snap of the boxed seed, or the site teaches the old diagram.',k:'PLAY',e:'S',i:3},
{c:'teach',t:'A teacher note per named snap',n:['earthlegend'],d:'ISS: limb and weather. Night: cities. Table: pale blue. Ground: one biome. Four paragraphs in `teach.js`. The product already has a teach module; give it cameras.',k:'PLAY',e:'S',i:2},
{c:'teach',t:'Colourblind Earth still has dark sea and bright cloud',n:['earthlegend','truecolor'],d:'Restate the luminance structure as a teaching requirement, not only a chroma item. If a classroom projector is terrible, Earth must still parse as a planet.',k:'EYE',e:'S',i:2},
{c:'teach',t:'Say when the year is presentation theatre',n:['earthlegend','phenology'],d:'If seasons run on `presentTime` while `dtYr` is 10 kyr, print "seasonal display, not simulated weather of this millenium". Stated limits on time are the hard ones.',k:'PLAY',e:'S',i:3},
{c:'teach',t:'A failure of earthcal should block the Earth label',n:['earthlegend','earthcal'],d:'If iceFrac or albedo is out of band, the world picker should say "Earth-class (uncalibrated)" not "Earth". The name is a claim.',k:'PLAY',e:'S',i:3},
{c:'teach',t:'Deep time labelled as not the photograph of 2026',n:['earthlegend'],d:'Archean Earth is a different planet. A badge. People will still call it Earth; the badge is how we do not.',k:'PLAY',e:'S',i:2},
{c:'teach',t:'Cite the Blue Marble and EPIC in the in-app about',n:['earthlegend','eoref'],d:'Same standard as the NASA Exoplanet Archive credit in the README. The look is downstream of those missions.',k:'PLAY',e:'S',i:1},
{c:'teach',t:'Keyboard: 1 table, 2 disc, 3 ISS, 4 patch, 5 stand',n:['earthlegend','zoomspan'],d:'Snaps as numbers, like overlay keys in the first pass. A teacher can drive the descent without hunting chips.',k:'PLAY',e:'S',i:2},
{c:'teach',t:'Do not teach plate names on a Voronoi Earth',n:['earthlegend'],d:'The plates overlay is identity colour. On a generated planet, "Pacific" is a lie. Use generated names, or say "this run". Locked-coastline mode can use real names.',k:'PLAY',e:'S',i:2},
{c:'teach',t:'A printed scale in every exported still',n:['earthlegend'],d:'km, exaggeration, month, seed. The first-pass screenshot-with-legend item, tightened for Earth: without it the postcard cannot be used in a slide deck.',k:'PLAY',e:'S',i:3},
{c:'teach',t:'The modern SimEarth sentence, on first boot',n:['earthlegend','simdna'],d:'"Hold a planet. This one is Earth. Shrink when you want to stand on it." Then the ISS still. No redox. The photograph teaches the pitch; the pitch should not teach the photograph.',k:'PLAY',e:'S',i:3},
{c:'teach',t:'Keep a changelog of looks, not only of systems',n:['earthlegend'],d:'When GGX landed, when the nibble pack died, when true colour becomes default. Visual history so a still in an old brief is dated. The picture is a product surface.',k:'PLAY',e:'S',i:1},
{c:'teach',t:'An Earth that can be wrong on purpose, labelled',n:['earthlegend'],d:'"Diagram mode", "boosted vegetation", "exaggerated relief". The toy looks, named. The photograph is the unmarked default. That is how you keep SimEarth and Earth in one binary.',k:'PLAY',e:'M',i:3},
{c:'teach',t:'Measure whether people call it Earth',n:['earthlegend'],d:'A tiny optional prompt on the boxed seed: "What planet is this?" If the answer is not Earth, the look failed, however many items are checked. The only test that matches the brief.',k:'PLAY',e:'S',i:2},
{c:'teach',t:'A caption generator for every named snap',n:['earthlegend'],d:'ISS, night, table, stand — four sentences filled from live fields (month, cloud mean, ice). Teachers paste them under a projector. The modern textbook figure.',k:'PLAY',e:'S',i:2},
{c:'teach',t:'Do not call a generated continent by a real name',n:['earthlegend'],d:'Status text that says "Africa" on a Voronoi landmass is how a teaching tool loses the room. Generated: "a southern continent". Locked-coastline: the real names. Pick.',k:'PLAY',e:'S',i:3},
{c:'teach',t:'Earth as the unmarked default of the world picker',n:['earthlegend'],d:'First slot, boxed seed, photograph look. Daisyworld second. The catalogue after. SimEarth opened on Earth. So does this, and it should look like it.',k:'PLAY',e:'S',i:3},
];

const D = [...PASS1, ...PASS2];



/* ------------------------------------------------------------- derive -- */
D.forEach((x, i) => { x.id = i + 1; });

const byCat = (id) => D.filter((x) => x.c === id);
const count = (f) => D.filter(f).length;
const KIND = { SIM: 'Sim', EYE: 'Eye', PLAY: 'Play' };
/** Literal pipes inside inline code would split a markdown table cell. */
const md = (t) => String(t).replace(/\|/g, '\\|');

const provides = new Map();
for (const x of D) if (x.g) provides.set(x.g, x);
const dependents = (tok) => D.filter((y) => (y.n || []).includes(tok)).length;
const CRITICAL = [...provides.keys()]
  .map((k) => ({ k, x: provides.get(k), n: dependents(k) }))
  .filter((r) => r.n > 0)
  .sort((a, b) => b.n - a.n);

const FIXED = [
  ['Two fields shared one byte in a filtered texture', '`uField0.a` carried `sedQ + cldQ * 16` and the atlas was sampled `LINEAR`. Hardware interpolation between two packed bytes runs straight across the nibble boundary, so `mod(packed, 16.0)` returned nonsense wherever cloud cover crossed any of its sixteen steps. The visible symptom was a tan sediment contour stair-stepping across four kilometres of open ocean — a set of terraced bands over the entire sea that read as a broken terrain layer. Cloud, sediment, intertidal, precipitation and river discharge now have their own channels across three atlases.'],
  ['The atmosphere shell was never tonemapped', 'The surface runs `tonemap(col * uExposure)`. The shell computed an unbounded radiance, wrote `o = vec4(col, 1.0)` and was additively blended on top, so the sunward limb clipped to flat white and painted a fat ring of blown sky beyond the disc. It now shares the same curve and the same exposure and writes a premultiplied coverage instead of a constant alpha.'],
  ['The moon was an unlit disc', 'It was drawn with `healthProg`, whose entire fragment shader is `o = vec4(uCol, 0.85)`, with the phase faked by scaling a constant colour. There is now a small-body shader with a real terminator, maria, craters, Lommel-Seeliger backscatter, an opposition surge and limb darkening.'],
  ['The sun glint was a white blob at every angle', 'A Blinn-Phong lobe wide enough to survive a calm sea plus a second wider lobe on top. It is a GGX microfacet lobe now, with roughness driven by the wind field and its energy clamped, plus a Fresnel sky reflection that is most of why a real ocean is not a flat tinted disc.'],
  ['The cloud shell was a quarter of the grid resolution, sampled nearest', 'Coverage came from `dirToCell` onto `6 x 17 x 17` vertices and was then used to displace the shell radially, so every band edge became a hard terrace with a visible ledge on the limb. The shell now matches N, samples bilinearly, and takes its lift from convective type rather than raw coverage.'],
  ['Two noise patterns were anchored to the world normal', 'The sea-ice floe pattern and the lightning flash were hashed from `N.xy` — the *world* normal — so both swam across the surface as the planet turned. Object space now, so the pack ice stays where it is.'],
  ['There was nothing between 250 km and one metre', 'A cell is about 250 km across and the surface was one interpolated colour with no sub-cell variation at all. Two octaves of object-space value noise now drive an albedo mottle and a sun-direction relief term, faded out by `fwidth(vObj)` before either period reaches the sampling limit.'],
];

const NOW = [
  ['The picture and the model are computed twice, differently', '`refreshColours` is 320 lines of per-cell colour logic on the CPU — depth ramps, ice leads, whitecaps, SST shift, rain darkening, blooms, sediment, reefs, plumes, storm trails, biomes, ash, build, guild tint. The fragment shader then computes a second, overlapping set of effects from the field atlas. `describeCell` in `present.js` computes a third for the pixel map. Three descriptions of the same cell, in three files, that drift apart every time one of them is touched.'],
  ['There is no level of detail anywhere', '`buildLatticeArrays` emits 786,432 vertices at N=64 and subd 2 and draws all of them from the orrery table and from a coastline alike. The field atlas has no mipmaps. The local map redraws every cell of the patch, with `describeCell`, on every frame. Nothing in the renderer knows how far away it is except the two detail-fade terms added in this pass.'],
  ['The field atlas is wrong in a band around all twelve cube edges', '`vFieldUV` maps cell `(f, i, j)` into a `6N x N` strip with `CLAMP_TO_EDGE`, so a fragment near the edge of one face blends with the edge of a face that is somewhere else entirely on the planet. Every field the surface shader reads is corrupt in a one-cell border around every face.'],
  ['Moisture is pinned at its ceiling over two thirds of the planet', 'A 120-tick probe of the terra ruleset returns `moist` with an area-weighted mean of 0.775 and 69.4% of cells at or above 0.985. A field saturated over most of its domain cannot express a gradient, so cloud formation, soil colour, vegetation and haze are all reading a constant across most of the world.'],
  ['Nothing on the globe moves between two frames', '`presentAdvance` gives the view a clock independent of the 10 kyr sim tick and only the local map uses it. `uTime` reaches the surface shader for the lightning hash and the aurora pulse and nothing else. A paused ORRERY and a running one are almost the same image from orbit.'],
  ['Only three fields are interpolated across the tick', '`life`, `temp` and `ice` are lerped between `prev` and current. Cloud, moisture, NPP, wind, sediment, precipitation and discharge all snap, and that snap is the single loudest motion artefact in the frame.'],
  ['Every flow in the model is drawn as 1600 one-frame line segments', '`fillFlowStreaks` emits `prev -> pos` per particle at a constant alpha with no taper, no lifetime and no width — `gl.lineWidth` is clamped to 1 on essentially every implementation. And because `stepFlow` reads the velocity at the containing cell centre, every particle entering a cell moves in exactly the same direction, so the paths collapse onto a handful of shared streamlines with visible corners at cell boundaries.'],
  ['There is no shadow of any kind on the planet', 'Terrain does not shade the ground behind it, clouds do not cast onto the surface — `col *= 1.0 - cloudF * landMask * 0.38` darkens the cell that is under the cloud rather than the cell the sun projects it onto — and nothing standing on the surface casts anything. The one occlusion term is `pow(1 - heightF, 1.4)`, a guess with no direction in it.'],
  ['The pixel map has no visual hierarchy', 'The base fill, the detail pass, the biome texture, the life stamps, the buildings, the grid, the rivers, the weather and the plumes all draw at roughly the same alpha and the same density, with more than sixty separate `rgba(...)` literals between them. A savanna cell and a river and a herd of animals put down the same amount of ink, so nothing reads as figure and nothing reads as ground.'],
  ['The two views disagree about the light', 'The globe computes lighting in a fragment shader from `uSun` and a surface normal; the map calls `cellLight` and `applyLight`. They disagree on direction, on colour and on where the terminator is, and both panels are on screen at the same time showing the same place.'],
  ['One byte per channel, for everything', 'Every field the shader reads is `UNSIGNED_BYTE`. `heightF = clamp(0.5 + (h - sea) * 2.2, 0, 1)` throws away everything below and above roughly four kilometres of elevation and quantises what is left to 1/255 — on the field that drives the water mask, the shoreline, the valley darkening and the new sediment gate.'],
  ['The renderer is unmeasured and untested', 'There is no GPU timer query, no frame budget, no device tier, no per-pass cost, and no rendered-reference test of any kind. `npm test` runs 59 assertions about physics and zero about the picture, which means every item in this document can be silently reverted by one optimisation and nothing will fail.'],
];

const EARTH = [
  ['uEarth makes Earth quieter, not truer', '`pop = lifeGreen * (1.0 - uEarth * 0.65)` and the vegetation mix `mix(0.58, 0.30, uEarth)` dim the biosphere on the one world everyone can fact-check. Quiet is not a photograph. Real canopy albedo is about 0.08; the render tints toward a mid green that reads as grass from orbit, then turns it down so it will not pop.'],
  ['Continents are climate belts', '`seedEarthBiosphere` paints life by `|lat|` and moisture; `primeEarthMoisture` hard-codes a desert belt between 0.28 and 0.50. The Sahara–Amazon–Siberia triad exists as climate and not as geography, so a generated Earth is a diagram of Hadley cells wearing terrain.'],
  ['Ocean colour is two triples', '`ocean(d) => [10+42d, 48+72d, 96+100d]` mixed with a depth lerp to `[22,45,75]`. Open-ocean albedo is about 0.06; the blue in a Blue Marble is almost all sky. The water is a bright game ocean, then bloom and sediment are painted on top.'],
  ['Daisyworld is a luminance filter', '`blackDaisy` and `whiteDaisy` are real fields, and `uDaisy` then guesses them back from `daisyBW = max(smoothstep(0.72, 0.9, lum), ...)`. The SimEarth tutorial is the one world that should be two albedos doing work, and it is a mix factor on the Earth shader.'],
  ['Calibration has never seen a colour', '`calibrate.mjs` allows landFrac 0.22–0.38, iceFrac 0–0.30, meanTemp 0.38–0.62. It does not assert ocean chromaticity, cloud distribution, night-light geography, or a limb width. A passing Earth can still be a lime continent with a fat halo.'],
  ['N is 64 in code and 96 in the ladder', '`sphere.js` exports `N = 64` (~157 km/cell). `N_LADDER` calls 96 the shipped default. This document, and several others, still say 250 km. The grid that is supposed to hold a coastline cannot agree with itself about how fine it is.'],
  ['The hold is a joystick axis', '`scaleXR` clamps 0.07–0.95; `orreryTable.js` tints six slots from meanLife and meanTemp. Relative radii are unused; a thumb cannot occlude the limb; the live world is duplicated onto the table as a second bead. The product is named for a table of worlds you hold.'],
  ['Gaia is a HUD on stub variables', '`TIPPING` names Amazon, AMOC, monsoon; `W._amoc` is `W.conveyor ?? W._amoc ?? 0.7` and `_monsoon` is a constant 0.5. Resilience is a popcount of eight life classes. The metabolism does not show on the disc, so the SimEarth thesis — the planet as a face — is a panel.'],
];

const SEQ = [
  ['Make the picture measurable before making it better', '`gputime`, `imgtest`, `visreg`. A GPU timer query, a debug overlay showing per-pass cost, and a handful of rendered reference frames diffed with a perceptual tolerance. Everything below this line costs milliseconds, and a renderer with no visual test is one clever optimisation away from losing all of it. The field inspector belongs here too: every artefact fixed in this pass took hours to find and would have taken minutes with a way to look at a channel.'],
  ['Fix the pipeline, then stop computing the picture twice', '`nopack` is done. `seamfix`, `floatfield`, `gpubasis`, then `gpucolour`. A one-texel gutter kills the corruption around all twelve cube edges; float channels give height and temperature back their dynamic range; the tangent frame on the GPU unblocks every direction-aware effect in the document; and moving `refreshColours` into the fragment shader deletes the largest CPU cost in the renderer while making every effect it performs sub-cell instead of per-cell.'],
  ['Then light it properly, once', '`tonecurve`, `hdrbuf`, `terrshadow`. One linear HDR target, every pass writing into it, one resolve. Bloom, adaptation and correct additive blending all fall out of that, and so does the end of the class of bug this pass spent most of its time on — two differently-scaled images meeting at a limb.'],
  ['Then give the surface a material and a scale', '`material`, `lodmesh`. A material table selected from rock, soil and life replaces one albedo and one roughness heuristic; a quadtree LOD replaces 786,432 vertices drawn at every distance. Together they are what make the four decades between a cell and a footprint into something rather than nothing.'],
  ['Then make the water and the sky behave', '`watercol`, `swell`, `cloudtop`. Depth-dependent extinction with a real spectrum replaces the two-colour ramp and gets turquoise-to-indigo for free; a swell field that travels gives every coast a surf line connected to a storm somewhere else; a cloud top height turns one coverage scalar into a sky with layers, anvils, shadows and a limb profile.'],
  ['Then make it move', '`globeclock`. Interpolate every field across the tick, advect the cloud texture with the wind, give the tracers a lifetime and a taper and sample their velocity between cells rather than at the centre, and let the tide move the shoreline against the presentation clock. This is the category with the worst ratio of effort to felt improvement in the whole document, because almost nothing has been done in it.'],
  ['Then rebuild the pixel map around a hierarchy', '`imgdata`, `hierarchy`, `sharedlight`. Composite into a typed array instead of issuing tens of thousands of `fillRect` calls; give every layer an explicit tier and an alpha budget; and share one description of a cell and one lighting model with the globe. The map is the half of the product with the most ground to make up, and every item in it is blocked on those three.'],
  ['Then let the other 119 worlds look like themselves', '`worldshader`. One shader with an `uEarth` branch is serving a catalogue that includes gas giants, ice moons, lava worlds, hazy worlds and free-floaters. Rings, a real host star in the sky, a locked eyeball ocean and true relative radii are the four items that would do most to make the catalogue a claim you can see.'],
  ['Then make the disc a photograph of Earth', '`bluemarble`, `truecolor`, `eoref`. Dark ocean, dark forest, pale desert, white ice, white cloud; albedo numbers instead of a biome palette; a shelf of NASA stills the render has to sit beside. `uEarth` as a dimmer comes off. Until a stranger calls the boxed seed Earth, nothing in the second pass has landed.'],
  ['Then the limb and the coast, which are how you know', '`limbvol`, `coastline`. Scale height over radius is 8.5/6371, not a halo thicker than Everest; the strand is fractal, asymmetric, and moves with the tide. These two edges are the whole of a Blue Marble at thumbnail size.'],
  ['Then the year, the lights and the face', '`phenology`, `lights`, `gaiaface`. A green wave that travels, VIIRS geography instead of `vD.b`, tipping elements as places. This is SimEarth DNA on a planet that photographs.'],
  ['Then one scale you can hold', '`zoomspan`, `holdfeel`, `groundcam`. Table, disc, ISS, country, patch, stand — one kilometres number, true relative radii on the table, a horizon when you walk in. The thesis is a descent, not two apps and a clamp.'],
];

/* ------------------------------------------------------------ markdown -- */
function markdown() {
  const L = [];
  L.push('# ORRERY — realism');
  L.push('');
  L.push(`**${D.length} items.** Generated from \`scripts/realism.mjs\` — edit that file, not this one, then run \`node scripts/realism.mjs\`.`);
  L.push('');
  L.push('Two passes. The first 400 items are the pipeline: fields, materials, water, sky, the mesh, the pixel map, the budget. Seven rendering faults were found and fixed while writing that pass; those are listed first, because they are the shape of the rest.');
  L.push('');
  L.push('The second 400 is the photograph. SimEarth painted biomes as a palette and let you hold the disc. The modern claim is that the disc is Earth — the same object DSCOVR photographs, the same one in the 2002 Blue Marble — and that you can still hold it, still push sliders, still walk in. `uEarth` currently turns the vegetation mix down so the result is quieter rather than truer; `seedEarthBiosphere` paints life by latitude belt; `calibrate.mjs` asserts climate scalars and has never asserted a colour. This pass is what has to be true for the globe in your hands to be Earth itself.');
  L.push('');
  L.push(`Kind: **${count((x) => x.k === 'EYE')}** picture, **${count((x) => x.k === 'SIM')}** mechanism, **${count((x) => x.k === 'PLAY')}** instrument or lever. Effort is S/M/L. Impact is 1–3.`);
  L.push('');

  L.push('## Fixed in this pass');
  L.push('');
  for (const [a, b] of FIXED) L.push(`- **${a}.** ${b}`);
  L.push('');

  L.push('## Where the picture actually is');
  L.push('');
  for (const [a, b] of NOW) L.push(`- **${a}.** ${b}`);
  L.push('');

  L.push('## Where Earth actually is');
  L.push('');
  for (const [a, b] of EARTH) L.push(`- **${a}.** ${b}`);
  L.push('');

  L.push('## The critical path');
  L.push('');
  L.push('The capabilities the largest number of other items are waiting on.');
  L.push('');
  L.push('| Capability | Item | Unblocks |');
  L.push('|---|---|---|');
  for (const r of CRITICAL.slice(0, 16)) {
    L.push(`| \`${r.k}\` | ${r.x.id}. ${md(r.x.t)} | ${r.n} items |`);
  }
  L.push('');

  for (const [id, name, blurb] of CATS) {
    const items = byCat(id);
    L.push(`## ${name} — ${items.length}`);
    L.push('');
    L.push(`_${blurb}_`);
    L.push('');
    L.push('| # | Item | Detail | Kind | Effort | Impact |');
    L.push('|---|---|---|---|---|---|');
    for (const x of items) {
      const gives = x.g ? ` <br>gives \`${x.g}\`` : '';
      const needs = x.n?.length ? ` <br>needs ${x.n.map((t) => '`' + t + '`').join(' ')}` : '';
      L.push(`| ${x.id} | **${md(x.t)}**${gives}${needs} | ${md(x.d)} | ${KIND[x.k]} | ${x.e} | ${x.i} |`);
    }
    L.push('');
  }

  L.push('## Sequencing');
  L.push('');
  SEQ.forEach(([a, b], i) => L.push(`${i + 1}. **${a}.** ${b}`));
  L.push('');
  L.push('The through-line of the first pass: the picture has never been measured. There is no GPU timer, no frame budget, no device tier, no reference frame and no test — so a nibble-packed field could corrupt the ocean of every world for as long as it liked, an untonemapped shell could clip the limb to white, and the nearest object to the planet could be an unlit beige circle, all at once, in a codebase with 59 passing assertions about physics. Fix the instruments first. Then fix the pipeline so the picture is computed once instead of three times.');
  L.push('');
  L.push('The through-line of the second: SimEarth let you hold a diagram. The modern extrapolation has to be Earth itself — dark ocean, thin blue limb, a year that travels, lights that mean cities — and still a toy you can tilt. `bluemarble` and `eoref` first, because a photograph without a photograph to sit beside is taste. Then `limbvol` and `coastline`, the two edges that survive a thumbnail. Then `phenology`, `lights` and `gaiaface`, which are SimEarth DNA on a planet that photographs. Then `zoomspan` and `holdfeel`, because the thesis is a descent and a hand.');
  L.push('');

  return L.join('\n');
}
/* ----------------------------------------------------------------- html -- */
function html() {
  const data = JSON.stringify(D.map((x) => ({
    id: x.id, c: x.c, t: x.t, d: x.d, k: x.k, e: x.e, i: x.i, g: x.g || '', n: x.n || [],
  })));
  const cats = JSON.stringify(CATS.map(([id, name, blurb]) => ({ id, name, blurb })));
  const crit = JSON.stringify(CRITICAL.slice(0, 16).map((r) => ({ k: r.k, id: r.x.id, t: r.x.t, n: r.n })));
  return `<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>ORRERY — realism</title>
<style>
:root{
  --ground:#0c0f16; --panel:#151a24; --panel2:#1b2231; --rule:#252d3d;
  --text:#dbe1ec; --dim:#98a3b7; --faint:#6c7688;
  --accent:#4fb0c6; --accent-soft:rgba(79,176,198,.13); --accent-line:rgba(79,176,198,.36);
  --sim:#7fc8a9; --sim-soft:rgba(127,200,169,.14);
  --eye:#7fb0e0; --eye-soft:rgba(127,176,224,.14);
  --sans:-apple-system,BlinkMacSystemFont,"Helvetica Neue","Segoe UI",Roboto,sans-serif;
  --mono:ui-monospace,"SF Mono",SFMono-Regular,Menlo,Consolas,monospace;
  --serif:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
}
@media (prefers-color-scheme: light){
  :root{ --ground:#eef0f3; --panel:#fff; --panel2:#f5f6f9; --rule:#d9dde5;
    --text:#12151c; --dim:#4e5768; --faint:#727d90;
    --accent:#1b6b80; --accent-soft:rgba(27,107,128,.09); --accent-line:rgba(27,107,128,.32);
    --sim:#22705a; --sim-soft:rgba(34,112,90,.09); --eye:#215e93; --eye-soft:rgba(33,94,147,.09); }
}
:root[data-theme="dark"]{ --ground:#0c0f16; --panel:#151a24; --panel2:#1b2231; --rule:#252d3d;
  --text:#dbe1ec; --dim:#98a3b7; --faint:#6c7688;
  --accent:#4fb0c6; --accent-soft:rgba(79,176,198,.13); --accent-line:rgba(79,176,198,.36);
  --sim:#7fc8a9; --sim-soft:rgba(127,200,169,.14); --eye:#7fb0e0; --eye-soft:rgba(127,176,224,.14); }
:root[data-theme="light"]{ --ground:#eef0f3; --panel:#fff; --panel2:#f5f6f9; --rule:#d9dde5;
  --text:#12151c; --dim:#4e5768; --faint:#727d90;
  --accent:#1b6b80; --accent-soft:rgba(27,107,128,.09); --accent-line:rgba(27,107,128,.32);
  --sim:#22705a; --sim-soft:rgba(34,112,90,.09); --eye:#215e93; --eye-soft:rgba(33,94,147,.09); }

*{box-sizing:border-box;}
body{margin:0; background:var(--ground); color:var(--text);
     font:400 16px/1.6 var(--sans); -webkit-font-smoothing:antialiased;}
.wrap{max-width:1080px; margin:0 auto; padding:40px 26px 110px;}

header{border-bottom:1px solid var(--rule); padding-bottom:28px;}
.eyebrow{font:500 10.5px/1 var(--mono); letter-spacing:.24em; text-transform:uppercase; color:var(--accent);}
h1{font:700 clamp(34px,5.4vw,54px)/1.03 var(--sans); letter-spacing:-.035em; margin:15px 0 0; text-wrap:balance;}
.sub{font:italic 400 clamp(17px,2.2vw,21px)/1.45 var(--serif); color:var(--dim);
     margin:18px 0 0; max-width:50ch;}
.nav{margin-top:20px; font:400 12.5px/1.7 var(--mono); color:var(--faint);}
.nav a{color:var(--dim); text-decoration:none; border-bottom:1px solid var(--rule);}
.nav a:hover{color:var(--accent); border-color:var(--accent-line);}

.tally{display:grid; grid-template-columns:repeat(auto-fit,minmax(126px,1fr)); gap:1px;
       background:var(--rule); border:1px solid var(--rule); border-radius:8px;
       overflow:hidden; margin-top:26px;}
.tally > div{background:var(--panel); padding:13px 15px;}
.tally dt{font:500 9.5px/1 var(--mono); letter-spacing:.15em; text-transform:uppercase; color:var(--faint);}
.tally dd{margin:9px 0 0; font:600 26px/1 var(--sans); letter-spacing:-.02em;
          font-variant-numeric:tabular-nums;}
.tally dd small{display:block; font:400 11px/1.5 var(--mono); color:var(--faint); margin-top:6px; letter-spacing:0;}

.prose{margin-top:40px;}
.prose h2{font:650 21px/1.2 var(--sans); letter-spacing:-.022em; margin:0 0 12px;
          border-bottom:1px solid var(--rule); padding-bottom:10px;}
.prose p{color:var(--dim); max-width:74ch; font-size:14.5px;}
.state{list-style:none; margin:14px 0 0; padding:0; display:flex; flex-direction:column; gap:1px;
       background:var(--rule); border:1px solid var(--rule); border-radius:8px; overflow:hidden;}
.state li{background:var(--panel); padding:13px 16px; color:var(--dim); font-size:13.5px; line-height:1.6;}
.state b{color:var(--text); font-weight:600;}
.crit{width:100%; border-collapse:collapse; margin-top:14px; font-size:13.5px;}
.crit td{border-top:1px solid var(--rule); padding:9px 12px; color:var(--dim);}
.crit td:first-child{font:500 11.5px/1.6 var(--mono); color:var(--accent); width:1%; white-space:nowrap;}
.crit td:last-child{text-align:right; font:500 11.5px/1.6 var(--mono); color:var(--faint); white-space:nowrap;}
.seq{margin:14px 0 0; padding-left:20px; color:var(--dim); font-size:14px;}
.seq li{margin-bottom:9px; max-width:74ch;}
.seq b{color:var(--text);}
code{font:500 12.5px/1 var(--mono); background:var(--panel2); border:1px solid var(--rule);
     padding:2px 5px; border-radius:4px; color:var(--accent);}

.controls{position:sticky; top:0; z-index:5; background:var(--ground);
          padding:18px 0 14px; border-bottom:1px solid var(--rule); margin:44px 0 6px;}
.filters{display:flex; flex-wrap:wrap; gap:7px; align-items:center;}
.flabel{font:500 9.5px/1 var(--mono); letter-spacing:.17em; text-transform:uppercase;
        color:var(--faint); margin-right:3px;}
button.f{font:500 11.5px/1 var(--mono); color:var(--dim); cursor:pointer; background:transparent;
         border:1px solid var(--rule); border-radius:5px; padding:7px 10px;}
button.f:hover{border-color:var(--accent-line); color:var(--text);}
button.f[aria-pressed="true"]{background:var(--accent-soft); border-color:var(--accent-line); color:var(--accent);}
button.f.sim[aria-pressed="true"]{background:var(--sim-soft); border-color:var(--sim); color:var(--sim);}
button.f.eye[aria-pressed="true"]{background:var(--eye-soft); border-color:var(--eye); color:var(--eye);}
#q{flex:1; min-width:170px; font:400 13px/1 var(--sans); color:var(--text);
   background:var(--panel); border:1px solid var(--rule); border-radius:5px; padding:8px 11px;}
#q::placeholder{color:var(--faint);}
.tally2{margin-top:11px; font:500 11px/1 var(--mono); color:var(--faint); font-variant-numeric:tabular-nums;}

section{padding-top:38px; scroll-margin-top:120px;}
.sechead{display:flex; align-items:baseline; gap:12px; flex-wrap:wrap;
         border-bottom:1px solid var(--rule); padding-bottom:10px;}
.sechead h2{font:650 21px/1.2 var(--sans); letter-spacing:-.022em; margin:0;}
.sechead .n{font:500 10.5px/1 var(--mono); color:var(--accent); background:var(--accent-soft);
            border:1px solid var(--accent-line); padding:4px 7px; border-radius:4px;}
.blurb{margin:13px 0 0; color:var(--dim); max-width:74ch; font-size:14.5px;}

ol{list-style:none; margin:16px 0 0; padding:0; display:flex; flex-direction:column; gap:1px;
   background:var(--rule); border:1px solid var(--rule); border-radius:8px; overflow:hidden;}
li.item{background:var(--panel); padding:13px 16px; display:grid;
   grid-template-columns:38px minmax(0,1fr) auto; gap:4px 14px; align-items:baseline;}
li .id{font:500 11px/1.5 var(--mono); color:var(--faint); font-variant-numeric:tabular-nums;}
li .t{font:600 14.5px/1.4 var(--sans); letter-spacing:-.008em;}
li .d{grid-column:2; color:var(--dim); font-size:13.5px; line-height:1.55; max-width:76ch;}
li .dep{grid-column:2; font:400 11px/1.6 var(--mono); color:var(--faint); margin-top:4px;}
li .dep .gives{color:var(--accent);}
li .tags{display:flex; gap:5px; align-items:center; grid-row:1; grid-column:3;}
.tag{font:600 9px/1 var(--mono); letter-spacing:.1em; text-transform:uppercase;
     padding:4px 6px; border-radius:3px; white-space:nowrap; border:1px solid transparent;}
.tag.sim{background:var(--sim-soft); color:var(--sim); border-color:var(--sim);}
.tag.eye{background:var(--eye-soft); color:var(--eye); border-color:var(--eye);}
.tag.play{background:transparent; color:var(--dim); border-color:var(--rule);}
.tag.e{background:transparent; color:var(--faint); border-color:var(--rule);}
.dots{display:inline-flex; gap:2px;}
.dots i{width:5px; height:5px; border-radius:50%; background:var(--rule); display:block;}
.dots i.on{background:var(--accent);}
.empty{padding:44px 16px; text-align:center; color:var(--faint); font:400 13.5px/1.6 var(--mono);}
:focus-visible{outline:2px solid var(--accent); outline-offset:2px; border-radius:4px;}
footer{margin-top:64px; padding-top:22px; border-top:1px solid var(--rule);
       font:400 12px/1.7 var(--mono); color:var(--faint);}
@media (max-width:640px){
  li.item{grid-template-columns:30px minmax(0,1fr);}
  li .tags{grid-row:auto; grid-column:2; margin-top:7px;}
}
@media (prefers-reduced-motion: reduce){ *{transition:none !important;} }
</style>
<link rel="stylesheet" href="doc-responsive.css">

<div class="wrap">
<header>
  <div class="eyebrow">Deep dive · Earth itself</div>
  <h1>Realism</h1>
  <p class="sub">Two passes. The first 400 items are the pipeline — the globe, the pixel map,
  and what has to be true underneath for either to read as a place. The second 400 is the
  photograph: SimEarth painted biomes as a palette; the modern claim is that the disc in your
  hands is Earth, and that you can still hold it, still push sliders, still walk in.</p>
  <p class="nav"><a href="./">Pitch</a> · <a href="backlog.html">Systems</a> ·
  <a href="worlds.html">Worlds</a> · <a href="evolution.html">Evolution</a> ·
  <a href="godgame.html">God layer</a> · <a href="next.html">Next 200</a> ·
  <a href="tides-weather.html">Tides &amp; weather</a> · <a href="geology.html">Geology</a> ·
  <a href="exoparams.html">Real parameters</a> · <a href="living.html">Alive</a> ·
  <a href="currents.html">Currents</a> · <a href="../vr/">Prototype</a></p>
  <dl class="tally">
    <div><dt>Items</dt><dd>${D.length}<small>${CATS.length} categories</small></dd></div>
    <div><dt>Kind</dt><dd>${count((x) => x.k === 'EYE')}/${count((x) => x.k === 'SIM')}/${count((x) => x.k === 'PLAY')}<small>eye · sim · play</small></dd></div>
    <div><dt>Impact 3</dt><dd>${count((x) => x.i === 3)}<small>of ${D.length}</small></dd></div>
    <div><dt>Effort</dt><dd>${count((x) => x.e === 'S')}/${count((x) => x.e === 'M')}/${count((x) => x.e === 'L')}<small>S / M / L</small></dd></div>
  </dl>
</header>

<div class="prose">
  <h2>Fixed in this pass</h2>
  <ul class="state" id="fixed"></ul>

  <h2 style="margin-top:40px">Where the picture actually is</h2>
  <ul class="state" id="now"></ul>

  <h2 style="margin-top:40px">Where Earth actually is</h2>
  <ul class="state" id="earth"></ul>

  <h2 style="margin-top:40px">The critical path</h2>
  <p>The capabilities the largest number of other items wait on.</p>
  <table class="crit"><tbody id="crit"></tbody></table>
</div>

<div class="controls">
  <div class="filters">
    <span class="flabel">Kind</span>
    <button class="f sim" data-k="k" data-v="SIM" aria-pressed="false">Sim</button>
    <button class="f eye" data-k="k" data-v="EYE" aria-pressed="false">Eye</button>
    <button class="f" data-k="k" data-v="PLAY" aria-pressed="false">Play</button>
    <span class="flabel" style="margin-left:9px">Effort</span>
    <button class="f" data-k="e" data-v="S" aria-pressed="false">S</button>
    <button class="f" data-k="e" data-v="M" aria-pressed="false">M</button>
    <button class="f" data-k="e" data-v="L" aria-pressed="false">L</button>
    <span class="flabel" style="margin-left:9px">Impact</span>
    <button class="f" data-k="i" data-v="3" aria-pressed="false">3</button>
    <button class="f" data-k="i" data-v="2" aria-pressed="false">2</button>
    <button class="f" data-k="i" data-v="1" aria-pressed="false">1</button>
    <input id="q" type="search" placeholder="Search ${D.length} items…" aria-label="Search items">
  </div>
  <div class="tally2" id="shown"></div>
</div>

<div id="list"></div>

<div class="prose" style="margin-top:56px">
  <h2>Sequencing</h2>
  <ol class="seq" id="seq"></ol>
  <p style="margin-top:16px">The first pass: the picture has never been measured. There is no
  GPU timer, no frame budget, no device tier, no reference frame and no test — so a nibble-packed
  field could corrupt the ocean of every world for as long as it liked. Fix the instruments
  first. Then fix the pipeline so the picture is computed once instead of three times. The
  second pass: SimEarth let you hold a diagram. The modern extrapolation has to be Earth itself
  — dark ocean, thin blue limb, a year that travels — and still a toy you can tilt.</p>
</div>

<footer>
  Generated from <code>scripts/realism.mjs</code> — edit the source and re-run, do not edit the output.
</footer>
</div>

<script>
"use strict";
var DATA = ${data};
var CATS = ${cats};
var CRIT = ${crit};
var NOW = ${JSON.stringify(NOW)};
var EARTH = ${JSON.stringify(EARTH)};
var FIXED = ${JSON.stringify(FIXED)};
var SEQ = ${JSON.stringify(SEQ)};
var KLABEL = {SIM:'Sim', EYE:'Eye', PLAY:'Play'};
var active = {k:new Set(), e:new Set(), i:new Set()};
var query = '';
var listEl = document.getElementById('list');
var shownEl = document.getElementById('shown');

function esc(s){ return String(s).replace(/[&<>"]/g, function(c){
  return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); }

document.getElementById('now').innerHTML = NOW.map(function(r){
  return '<li><b>' + esc(r[0]) + '.</b> ' + esc(r[1]) + '</li>'; }).join('');
document.getElementById('earth').innerHTML = EARTH.map(function(r){
  return '<li><b>' + esc(r[0]) + '.</b> ' + esc(r[1]) + '</li>'; }).join('');
document.getElementById('fixed').innerHTML = FIXED.map(function(r){
  return '<li><b>' + esc(r[0]) + '.</b> ' + esc(r[1]) + '</li>'; }).join('');
document.getElementById('crit').innerHTML = CRIT.map(function(r){
  return '<tr><td>' + esc(r.k) + '</td><td>' + r.id + '. ' + esc(r.t) +
         '</td><td>' + r.n + ' items</td></tr>'; }).join('');
document.getElementById('seq').innerHTML = SEQ.map(function(r){
  return '<li><b>' + esc(r[0]) + '.</b> ' + esc(r[1]) + '</li>'; }).join('');

function match(o){
  if (active.k.size && !active.k.has(o.k)) return false;
  if (active.e.size && !active.e.has(o.e)) return false;
  if (active.i.size && !active.i.has(String(o.i))) return false;
  if (query){
    var hay = (o.t + ' ' + o.d + ' ' + o.g + ' ' + o.n.join(' ')).toLowerCase();
    if (hay.indexOf(query) === -1) return false;
  }
  return true;
}

function dots(n){
  var out = '<span class="dots" title="Impact ' + n + ' of 3">';
  for (var k = 1; k <= 3; k++) out += '<i class="' + (k <= n ? 'on' : '') + '"></i>';
  return out + '</span>';
}

function render(){
  var html = '', total = 0;
  for (var ci = 0; ci < CATS.length; ci++){
    var cat = CATS[ci];
    var items = DATA.filter(function(o){ return o.c === cat.id && match(o); });
    if (!items.length) continue;
    total += items.length;
    html += '<section id="' + cat.id + '"><div class="sechead"><h2>' + esc(cat.name) +
            '</h2><span class="n">' + items.length + '</span></div>' +
            '<p class="blurb">' + esc(cat.blurb) + '</p><ol>';
    for (var k = 0; k < items.length; k++){
      var o = items[k];
      var cls = o.k === 'SIM' ? 'sim' : o.k === 'EYE' ? 'eye' : 'play';
      var dep = '';
      if (o.g) dep += '<span class="gives">gives ' + esc(o.g) + '</span>';
      if (o.n.length) dep += (dep ? ' · ' : '') + 'needs ' + o.n.map(esc).join(' ');
      html += '<li class="item"><span class="id">' + o.id + '</span>' +
              '<span class="t">' + esc(o.t) + '</span>' +
              '<span class="tags"><span class="tag ' + cls + '">' + KLABEL[o.k] + '</span>' +
              '<span class="tag e">' + o.e + '</span>' + dots(o.i) + '</span>' +
              '<span class="d">' + esc(o.d) + '</span>' +
              (dep ? '<span class="dep">' + dep + '</span>' : '') + '</li>';
    }
    html += '</ol></section>';
  }
  if (!total) html = '<p class="empty">Nothing matches those filters.</p>';
  listEl.innerHTML = html;
  shownEl.textContent = 'Showing ' + total + ' of ' + DATA.length;
}

var btns = document.querySelectorAll('button.f');
for (var b = 0; b < btns.length; b++){
  btns[b].addEventListener('click', function(){
    var k = this.dataset.k, v = this.dataset.v;
    if (active[k].has(v)) { active[k].delete(v); this.setAttribute('aria-pressed','false'); }
    else { active[k].add(v); this.setAttribute('aria-pressed','true'); }
    render();
  });
}
document.getElementById('q').addEventListener('input', function(){
  query = this.value.trim().toLowerCase(); render();
});
render();
</script>
`;
}

/* ----------------------------------------------------------------- emit -- */
await mkdir(join(ROOT, 'briefs'), { recursive: true });
await mkdir(join(ROOT, 'site'), { recursive: true });
await writeFile(join(ROOT, 'briefs', 'realism-backlog.md'), markdown() + '\n');
await writeFile(join(ROOT, 'site', 'realism.html'), html());

console.log(`realism: ${D.length} items across ${CATS.length} categories`);
for (const [id, name] of CATS) console.log(`  ${String(byCat(id).length).padStart(3)}  ${name}`);
console.log(`\nkind     eye ${count((x) => x.k === 'EYE')} · sim ${count((x) => x.k === 'SIM')} · play ${count((x) => x.k === 'PLAY')}`);
console.log(`effort   S ${count((x) => x.e === 'S')} · M ${count((x) => x.e === 'M')} · L ${count((x) => x.e === 'L')}`);
console.log(`impact   3 ${count((x) => x.i === 3)} · 2 ${count((x) => x.i === 2)} · 1 ${count((x) => x.i === 1)}`);
console.log('\ncritical path:');
for (const r of CRITICAL.slice(0, 16)) {
  console.log(`  ${String(r.n).padStart(3)}  ${r.k.padEnd(12)} ${r.x.t}`);
}
const unmet = new Set();
for (const x of D) for (const t of x.n || []) if (!provides.has(t)) unmet.add(t);
if (unmet.size) console.log(`\nWARNING unmet tokens: ${[...unmet].join(', ')}`);
console.log('\nwrote briefs/realism-backlog.md and site/realism.html');
